// ===== main.js : 初始化/配置/UI/主循环 =====
/* ===== 全局错误捕获：白屏时显示报错信息，方便排查 ===== */
window.addEventListener('error', function(e) {
  var d = document.createElement('div');
  d.style.cssText = 'position:fixed;top:0;left:0;right:0;z-index:99999;background:#300;color:#f88;padding:12px;font:14px monospace;white-space:pre-wrap;word-break:break-all;';
  d.textContent = 'JS错误: ' + (e.message || '未知') + '\n行: ' + (e.filename || '') + ':' + (e.lineno || 0) + '\n\n请截图发给开发者';
  document.body ? document.body.appendChild(d) : document.documentElement.appendChild(d);
});
window.addEventListener('unhandledrejection', function(e) {
  var d = document.createElement('div');
  d.style.cssText = 'position:fixed;top:0;left:0;right:0;z-index:99999;background:#300;color:#f88;padding:12px;font:14px monospace;white-space:pre-wrap;word-break:break-all;';
  d.textContent = 'Promise错误: ' + (e.reason && e.reason.message ? e.reason.message : e.reason) + '\n\n请截图发给开发者';
  document.body ? document.body.appendChild(d) : document.documentElement.appendChild(d);
});
