/* 幸运对局内概率的修正（读 meta.luck；菜单/旧档均安全） */
function luckAdjustedRates() {
  const Lk = GAME_CONFIG.luck;
  let L = 0;
  try { L = Math.min(Lk.maxLevel, (getMeta().luck) || 0); } catch (_) {}
  return {
    stone: Math.min(Lk.stoneSlotCap, Lk.stoneSlotBase + L * Lk.stoneSlotPerLevel),
    samadhi: Math.min(Lk.samadhiCap, Lk.samadhiBase + L * Lk.samadhiPerLevel),
  };
}
/* ============================================================
   五行劫：渊海镇魂录 — 单文件 HTML5 Canvas 游戏
   v3：有限波次进度条 / 暂停键P / 经验加速吸附 /
       BOSS宝箱 / 新兵种（射手/治疗/自爆/精英/分裂）
   ============================================================ */

/* ====== 主菜单背景（Canvas 绘制）+ 菜单粒子动画 ====== */
let _menuBg = null;
let _menuDecor = null;
let menuParticles = [];
let _lastMenuOrientation; // 上一次菜单背景所用方向，用于方向切换时刷新背景源
// ===== 主界面背景图资源：优先使用内嵌羊皮纸背景（data URI，单文件自带），其次同目录图片，缺失则回退程序绘制星空 =====
const _menuBgImg = new Image();
_menuBgImg._loaded = false;
_menuBgImg._failed = false;
// 内嵌背景（构建时由「主背景.png」注入；占位符会被替换为 data:image/png;base64,...）
const _MENU_BG_DATA_URI = 'data:image/png;base64,';
// 候选：内嵌 data URI 优先；其次相对 HTML 所在目录的图片文件（双击打开与本地服务器均兼容）
const _menuBgCandidates = [
  _MENU_BG_DATA_URI.indexOf('data:image/') === 0 ? _MENU_BG_DATA_URI : null,
  'menu-bg.jpg', 'menu-bg.png', 'menu-bg.webp',
  'assets/menu-bg.jpg', 'assets/menu-bg.png'
].filter(Boolean);
let _menuBgIdx = 0;
function _applyParchmentTheme(on) {
  if (!document.body) return;
  document.body.classList.toggle('menu-parchment', !!on);
  // 主菜单背景挂到 #stage 上：原图 1024×576 与设计分辨率 1280×720 同为 16:9。
  // 用 contain 保证整张图始终完整显示——16:9 屏幕上恰好铺满（等同 cover）；
  // 宽屏/带鱼屏 resize() 会横向扩展 stage（宽度>1280），contain 改为两侧露深色边，
  // 不再像 cover 那样按宽度放大把图片上下裁掉（木框/烛台完整可见）。
  const stage = document.getElementById('stage');
  if (stage) {
    const activeImg = _getActiveMenuBgImg();
    if (on && activeImg && activeImg.src) {
      // 背景图挂到 CSS 变量，由 #stage::after 独立背景层消费（锐化/降噪/暗化滤镜只作用于该层，不波及文字与 UI）
      stage.style.setProperty('--menu-bg-src', 'url("' + activeImg.src + '")');
      stage.style.backgroundColor = 'rgb(7,9,22)';
    } else {
      stage.style.removeProperty('--menu-bg-src');
      stage.style.backgroundColor = '';
    }
  }
}
_menuBgImg.onload = function () {
  if (_menuBgImg.naturalWidth > 0) {
    _menuBgImg._loaded = true;
    _menuBgImg._failed = false;
    _menuBg = null;  // 强制 ensureMenuBg 下次重绘，套用背景图
    _applyParchmentTheme(true);
    // 图片加载完成后立即重绘背景，避免等待下一帧
    if (typeof W !== 'undefined' && typeof H !== 'undefined' && W > 0 && H > 0) {
      try { ensureMenuBg(W, H); } catch(e) {}
    }
  } else {
    _tryNextMenuBg();
  }
};
_menuBgImg.onerror = function () { _tryNextMenuBg(); };
function _tryNextMenuBg() {
  if (_menuBgIdx >= _menuBgCandidates.length) {
    _menuBgImg._failed = true;
    _menuBgImg._loaded = false;
    _menuBg = null;
    _applyParchmentTheme(false);
    return;
  }
  _menuBgImg.src = _menuBgCandidates[_menuBgIdx++];
}
_tryNextMenuBg();

// ===== 竖屏专属背景图（竖屏菜单时优先使用，横屏回退到 _menuBgImg） =====
const _menuBgPortraitImg = new Image();
_menuBgPortraitImg._loaded = false;
_menuBgPortraitImg._failed = false;
_menuBgPortraitImg.onload = function () {
  if (_menuBgPortraitImg.naturalWidth > 0) {
    _menuBgPortraitImg._loaded = true;
    _menuBgPortraitImg._failed = false;
    _menuBg = null; // 强制 ensureMenuBg 下次重绘
    _applyParchmentTheme(true);
    if (typeof W !== 'undefined' && typeof H !== 'undefined' && W > 0 && H > 0) {
      try { ensureMenuBg(W, H); } catch(e) {}
    }
  } else {
    _menuBgPortraitImg._failed = true;
  }
};
_menuBgPortraitImg.onerror = function () {
  _menuBgPortraitImg._failed = true;
  _menuBgPortraitImg._loaded = false;
};
_menuBgPortraitImg.src = 'assets/images/立绘/ui/fVaBTG41rRF-lptvBfnNL.png';

// 返回当前方向下应使用的菜单背景图：竖屏且竖屏图已加载则用竖屏图，否则用横屏图
function _getActiveMenuBgImg() {
  const isPortrait = (typeof window._isPortrait !== 'undefined')
    ? window._isPortrait
    : (window.innerWidth < window.innerHeight);
  if (isPortrait && _menuBgPortraitImg._loaded && _menuBgPortraitImg.complete && _menuBgPortraitImg.naturalWidth > 0) {
    return _menuBgPortraitImg;
  }
  return _menuBgImg;
}

