// 初始即为主菜单状态，先打上 in-menu 类，保证首帧渲染前 CSS 背景已生效
if (document.body) document.body.classList.add('in-menu');

(function initMenuParticles(){
  for (let i = 0; i < 80; i++) {
    menuParticles.push({
      x: Math.random(), y: Math.random(),
      r: Math.random()*1.6 + 0.4,
      s: Math.random()*0.018 + 0.004,
      h: Math.random()*360
    });
  }
})();
function ensureMenuBg(w, h) {
  if (_menuBg && _menuBg.width === w && _menuBg.height === h) return;
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  const g = c.getContext('2d');

  // ===== 1) 羊皮纸主界面背景图（按 cover 方式铺满） =====
  const _activeBg = _getActiveMenuBgImg();
  const _hasBgImg = _activeBg._loaded && _activeBg.complete && _activeBg.naturalWidth > 0;
  if (_hasBgImg) {
    const iw = _activeBg.naturalWidth, ih = _activeBg.naturalHeight;
    const s = Math.max(w / iw, h / ih);
    const dw = iw * s, dh = ih * s;
    const dx = (w - dw) / 2, dy = (h - dh) / 2;
    g.drawImage(_activeBg, dx, dy, dw, dh);
    // 暖色统一 + 顶部/底部轻微压暗，保证标题与按钮可读
    const overlay = g.createLinearGradient(0, 0, 0, h);
    overlay.addColorStop(0,   'rgba(26,13,0,0.16)');
    overlay.addColorStop(0.45,'rgba(0,0,0,0)');
    overlay.addColorStop(1,   'rgba(26,13,0,0.24)');
    g.fillStyle = overlay; g.fillRect(0,0,w,h);
  }
  // ===== 否则用程序绘制兜底（星空山景） =====
  if (!_hasBgImg) {
    // 1) 深空渐变
    const bg = g.createLinearGradient(0, 0, 0, h);
    bg.addColorStop(0, '#0a0e2a');
    bg.addColorStop(0.45, '#1b1b4b');
    bg.addColorStop(1, '#3b1e5a');
    g.fillStyle = bg; g.fillRect(0,0,w,h);
    // 星云斑块（柔光）
    const clouds = [
      [0.22, 0.28, w*0.55, '#5b4bff', 0.22],
      [0.78, 0.36, w*0.62, '#ff6b9d', 0.22],
      [0.50, 0.78, w*0.70, '#00c2a8', 0.18],
      [0.16, 0.82, w*0.40, '#ffb74d', 0.18],
    ];
    for (const [cx, cy, size, col, a] of clouds) {
      const x = cx*w, y = cy*h;
      const rg = g.createRadialGradient(x, y, 0, x, y, size/2);
      rg.addColorStop(0, hexAlpha(col, a));
      rg.addColorStop(1, hexAlpha(col, 0));
      g.fillStyle = rg; g.fillRect(x-size/2, y-size/2, size, size);
    }
    // 远山剪影（3 层叠色 视差感）
    function drawMountain(ys, color, amp, step, seed) {
      g.fillStyle = color; g.beginPath(); g.moveTo(0, h);
      for (let x = 0; x <= w; x += step) {
        const k = Math.sin((x + seed*37) * 0.008) * amp * 0.62
                + Math.sin((x + seed*113) * 0.0023) * amp * 0.38;
        g.lineTo(x, ys + k);
      }
      g.lineTo(w, h); g.closePath(); g.fill();
    }
    drawMountain(h * 0.72, '#111240', h*0.10, 18, 1);
    drawMountain(h * 0.80, '#0a0a2a', h*0.12, 22, 3);
    drawMountain(h * 0.88, '#05051a', h*0.09, 26, 7);
    // 前景树丛
    g.fillStyle = 'rgba(0,0,0,0.6)';
    for (let i = 0; i < 22; i++) {
      const bx = (i / 22) * w + (i%3)*18 + 10;
      const bw = 50 + (i%4)*12;
      const bh = 80 + (i%5)*10;
      const by = h - bh;
      g.beginPath();
      g.arc(bx, by + bh*0.55, bw*0.6, 0, TAU);
      g.arc(bx - bw*0.35, by + bh*0.7, bw*0.4, 0, TAU);
      g.arc(bx + bw*0.35, by + bh*0.7, bw*0.45, 0, TAU);
      g.arc(bx, by + bh*0.3, bw*0.42, 0, TAU);
      g.fill();
      g.fillRect(bx - bw*0.08, by + bh*0.6, bw*0.16, bh*0.4);
    }
    // 远景塔 / 城
    g.fillStyle = 'rgba(255, 228, 180, 0.08)';
    for (let i = 0; i < 8; i++) {
      const x = w*(0.1 + i*0.11);
      const ty = h*0.74 + (i%3)*8;
      const th = h*(0.08 + (i%4)*0.015);
      const tw = 10 + (i%3)*4;
      g.fillRect(x, ty - th, tw, th);
      g.beginPath();
      g.moveTo(x - 2, ty - th); g.lineTo(x + tw/2, ty - th - 14); g.lineTo(x + tw + 2, ty - th);
      g.closePath(); g.fill();
    }
    // 静态星点
    for (let i = 0; i < 220; i++) {
      const x = Math.random() * w, y = Math.random() * h * 0.82;
      const r = Math.random() * 1.4 + 0.2;
      const a = 0.4 + Math.random() * 0.6;
      g.fillStyle = `rgba(255, 240, 200, ${a})`;
      g.beginPath(); g.arc(x, y, r, 0, TAU); g.fill();
    }
    // 流星尾迹
    g.globalCompositeOperation = 'lighter';
    for (let i = 0; i < 3; i++) {
      const sx = Math.random()*w, sy = Math.random()*h*0.6;
      const len = w*0.35 + Math.random()*w*0.2;
      const ang = Math.PI/5 + (Math.random()-0.5)*0.2;
      const grd = g.createLinearGradient(sx, sy, sx + Math.cos(ang)*len, sy + Math.sin(ang)*len);
      grd.addColorStop(0, 'rgba(255,255,255,0.0)');
      grd.addColorStop(0.85, 'rgba(255,230,160,0.55)');
      grd.addColorStop(1, 'rgba(255,255,255,0.0)');
      g.strokeStyle = grd; g.lineWidth = 2;
      g.beginPath(); g.moveTo(sx, sy); g.lineTo(sx + Math.cos(ang)*len, sy + Math.sin(ang)*len); g.stroke();
    }
    g.globalCompositeOperation = 'source-over';
  }

  // ===== 2) 星空主题叠加层：魔法光尘 + 能量纹（羊皮纸背景图时跳过，避免蓝点污染纸面） =====
  if (!_hasBgImg) {
    g.save(); g.globalCompositeOperation = 'lighter';
    for (let i = 0; i < 140; i++) {
      const x = (i * 173.3 % w), y = ((i * 97.7) % h);
      const r = (i % 3) * 0.7 + 0.8;
      const hue = 210 + (i * 37 % 120);
      g.fillStyle = `hsla(${hue}, 95%, 78%, ${0.18 + (i%5)*0.08})`;
      g.beginPath(); g.arc(x, y, r, 0, TAU); g.fill();
    }
    // 魔法竖纹光带
    for (let i = 0; i < 4; i++) {
      const vx = w * (0.15 + i * 0.22);
      const vg2 = g.createLinearGradient(vx - 40, 0, vx + 40, 0);
      vg2.addColorStop(0, 'rgba(130,200,255,0)');
      vg2.addColorStop(0.5, 'rgba(160,200,255,0.06)');
      vg2.addColorStop(1, 'rgba(130,200,255,0)');
      g.fillStyle = vg2; g.fillRect(vx - 40, 0, 80, h);
    }
    g.restore();
  }

  // 3) 暗角（加深氛围；羊皮纸背景图本身边缘已暗，用更轻的暗角）
  const vg = g.createRadialGradient(w/2, h/2, Math.min(w,h)*0.3, w/2, h/2, Math.max(w,h)*0.75);
  vg.addColorStop(0, 'rgba(0,0,0,0)');
  vg.addColorStop(1, 'rgba(0,0,0,' + (_hasBgImg ? 0.45 : 0.78) + ')');
  g.fillStyle = vg; g.fillRect(0,0,w,h);

  _menuBg = c;
}
/* =============================================================
   🎨 通用颜色工具函数（健壮版）
   - 支持所有输入：'#RRGGBB' / '#RGB' / 'rgb(R,G,B)' / 'rgba(R,G,B,A)' / 纯数字 6-char hex / 缺省值
   - 任意函数可链式传入另一函数的输出：hexAlpha(mix(a,b,t), a) / shade(mix(...), -20) / mix(hexAlpha(...), ...)
   - 解析失败一律 fallback 到 '#808080' / r=128 g=128 b=128 而非 NaN, 避免 CanvasGradient.addColorStop 抛错
   ============================================================= */
function _parseRGB(c) {
  if (c == null) return [128,128,128];
  if (typeof c !== 'string') c = String(c);
  c = c.trim();
  // rgb(...) / rgba(...)
  const ma = c.match(/rgba?\\s*\\(\\s*([\\d.]+%?)\\s*,\\s*([\\d.]+%?)\\s*,\\s*([\\d.]+%?)\\s*(?:,\\s*([\\d.]+)\\s*)?\\)/i);
  if (ma) {
    const v = (s) => {
      if (s == null || s === '') return null;
      let pct = false;
      if (s.endsWith('%')) { pct = true; s = s.slice(0,-1); }
      let n = parseFloat(s); if (isNaN(n)) return null;
      return pct ? Math.round(n * 2.55) : Math.round(n);
    };
    const r = v(ma[1]), g = v(ma[2]), b = v(ma[3]);
    return [ r==null?128:Math.max(0,Math.min(255,r)),
             g==null?128:Math.max(0,Math.min(255,g)),
             b==null?128:Math.max(0,Math.min(255,b)) ];
  }
  // '#RRGGBB' / '#RGB' / 'RRGGBB' / 'RGB'
  let h = c.replace(/^#/, '').replace(/\s+/g,'');
  if (h.length === 3) h = h.split('').map(ch => ch+ch).join('');
  if (h.length >= 6) h = h.substring(0,6);
  if (/^[0-9a-fA-F]{6}$/.test(h)) {
    const r = parseInt(h.substring(0,2),16);
    const g = parseInt(h.substring(2,4),16);
    const b = parseInt(h.substring(4,6),16);
    return [r, g, b];
  }
  // fallback: muted grey
  return [128, 128, 128];
}
function _rgbHex(arr) {
  const z = (n) => { n = Math.max(0, Math.min(255, Math.round(isNaN(n)||n==null?128:n))); return (n<16?'0':'') + n.toString(16); };
  return `#${z(arr[0])}${z(arr[1])}${z(arr[2])}`;
}
function hexAlpha(hex, a) {
  const [r,g,b] = _parseRGB(hex);
  const av = (a == null || isNaN(a)) ? 1 : Math.max(0, Math.min(1, +a));
  return `rgba(${r},${g},${b},${av})`;
}
function shade(hex, amt) {
  const [r,g,b] = _parseRGB(hex);
  const n = isNaN(+amt) ? 0 : +amt;
  return _rgbHex([r+n, g+n, b+n]);
}
function brighten(hex, amt) { return shade(hex, amt); }
function clamp255(v) { return Math.max(0, Math.min(255, Math.round(isNaN(v)?128:v))); }
function mix(a, b, t) {
  const [ar,ag,ab] = _parseRGB(a);
  const [br,bg,bb] = _parseRGB(b);
  const tt = isNaN(+t) ? 0.5 : Math.max(0, Math.min(1, +t));
  return _rgbHex([ ar*(1-tt)+br*tt, ag*(1-tt)+bg*tt, ab*(1-tt)+bb*tt ]);
}
function drawMenuScene(tMs) {
  const _activeBg = _getActiveMenuBgImg();
  const _hasBg = _activeBg._loaded && _activeBg.complete && _activeBg.naturalWidth > 0;
  if (_hasBg) {
    // 背景图由 #gameWrap CSS 背景渲染（原图直接高质量缩放，不走 canvas pixelated 管线）
    ctx.clearRect(0, 0, W, H);
  } else {
    // 图片缺失时兜底：程序绘制的星空山景
    ensureMenuBg(W, H);
    ctx.drawImage(_menuBg, 0, 0, W, H);
  }
  // 飘移星尘（前景）
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  for (const p of menuParticles) {
    p.y -= p.s;
    if (p.y < -0.02) { p.y = 1.02; p.x = Math.random(); }
    const x = p.x * W, y = p.y * H;
    const tw = (Math.sin((tMs/400) + p.h/57) + 1) * 0.5;
    ctx.fillStyle = `hsla(${p.h}, 90%, 78%, ${0.35 + tw*0.5})`;
    ctx.beginPath(); ctx.arc(x, y, p.r + tw*0.9, 0, TAU); ctx.fill();
  }
  ctx.restore();
  // 暗角：背景图模式下压轻（暖色压暗已由 CSS 遮罩负责），兜底星空模式保持原强度
  const vgAlpha = _hasBg ? 0.32 : 0.75;
  const vg = ctx.createRadialGradient(W/2, H/2, Math.min(W,H)*0.3, W/2, H/2, Math.max(W,H)*0.75);
  vg.addColorStop(0, 'rgba(0,0,0,0)');
  vg.addColorStop(1, 'rgba(0,0,0,' + vgAlpha + ')');
  ctx.fillStyle = vg; ctx.fillRect(0,0,W,H);
}

const canvas = document.getElementById('game');
