// 整体舞台自适应：游戏内部固定 1280×720 横屏
// 手机竖屏时自动旋转90°填满屏幕，无需改游戏逻辑/HUD/渲染
// 🔒 竖屏主菜单：彻底屏蔽页面滑动（触摸滑动 + 鼠标滚轮）。
// 判定收紧到“portrait-ui + 主菜单可见”；天赋/武器/图鉴/修炼/说明等子页内容多，保留其内部滚动。
document.addEventListener('wheel', function(e) {
  if (document.body.classList.contains('portrait-ui') &&
      document.getElementById('mainMenuView').style.display !== 'none' &&
      !(e.target && e.target.closest && e.target.closest('#guideBox'))) {
    e.preventDefault();
  }
}, { passive: false });
document.addEventListener('touchmove', function(e) {
  if (document.body.classList.contains('portrait-ui') &&
      document.getElementById('mainMenuView').style.display !== 'none' &&
      !(e.target && e.target.closest && e.target.closest('#guideBox'))) {
    e.preventDefault();
  }
}, { passive: false });

function resize() {
  let w = window.innerWidth, h = window.innerHeight;
  // Safari/iOS 地址栏修正
  if (h && typeof window.visualViewport !== 'undefined' && window.visualViewport.height) {
    h = Math.min(h, window.visualViewport.height);
    w = Math.min(w, window.visualViewport.width);
  }
  if (!w) w = 1280;
  if (!h) h = 720;
  // —— 全局强制不出现滚动条（兼容高DPI缩放）——
  // 使用 innerWidth/innerHeight 精确像素替代 100vw/100vh，
  // 避免 100vw 含滚动条宽度而 innerWidth 不含，导致舞台居中偏移
  try {
    const root = document.documentElement;
    root.style.cssText = 'width:' + w + 'px!important;height:' + h + 'px!important;overflow:hidden!important;position:fixed!important;top:0!important;left:0!important;right:0!important;bottom:0!important;margin:0!important;padding:0!important;';
    if (document.body) document.body.style.cssText = 'width:' + w + 'px!important;height:' + h + 'px!important;overflow:hidden!important;position:fixed!important;top:0!important;left:0!important;right:0!important;bottom:0!important;margin:0!important;padding:0!important;';
    window.scrollTo(0, 0);
  } catch(_) {}
  const DESIGN_W = 1280, DESIGN_H = 720;
  const isPortrait = _portraitForced !== null ? _portraitForced : (w < h);
  window._isPortrait = isPortrait;
  // 舞台是否发生了 90° 旋转（旧版竖屏战斗会旋转；现已改为真竖屏，恒为 false，保留给输入映射判断）
  window._stageRotated = false;
  // 菜单/对局选项界面（主菜单/职业/关卡/天赋/武器/图鉴/修炼都在 gameState==='menu' 下显示）
  const inMenuUI = (typeof gameState !== 'undefined' && gameState === 'menu');
  // 手机横屏判定：横屏 + 菜单 + 视口高度 ≤520（主流手机横屏高度 320~428）
  // 核心策略：User-Agent 识别移动设备为主，屏幕尺寸为辅。
  // 为什么不用屏幕尺寸单独判断：高 DPI 缩放桌面（如 1080p@225%→CSS 853×480）会让 screen 短边 ≤520，误判为手机。
  // 为什么不用触屏：触屏笔记本（Surface 等）maxTouchPoints>0 也会误判。
  // UA 含 Mobi/Android/iPhone/iPad/iPod/Windows Phone/BlackBerry → 移动设备；否则一律按桌面处理。
  const isMobileUA = /Mobi|Android|iPhone|iPad|iPod|Windows Phone|BlackBerry|Opera Mini|IEMobile/i.test(navigator.userAgent || '');
  // 指针类型：(pointer:fine) 表示有鼠标/触控板，基本可判定为桌面设备（即使 UA 被伪装成移动端）
  let hasFinePointer = false;
  try { hasFinePointer = !!(window.matchMedia && window.matchMedia('(pointer: fine)').matches); } catch (_) {}
  let screenShortSide = 9999;
  try {
    const sw = Math.max(window.screen.width || 0, window.screen.availWidth || 0);
    const sh = Math.max(window.screen.height || 0, window.screen.availHeight || 0);
    if (sw > 100 && sh > 100) screenShortSide = Math.min(sw, sh);
  } catch (_) {}
  // 三重保险：UA 为移动 + 无精细指针 + 屏幕短边 ≤700，才判定为手机横屏
  const isPhoneLandscape = !isPortrait && inMenuUI && h <= 520 && isMobileUA && !hasFinePointer && screenShortSide <= 700;
  // 电脑横屏窗口强制竖屏时，根元素设暗色背景（舞台居中后两侧留黑）
  document.documentElement.style.background = (isPortrait && w > h) ? '#060614' : '';
  if (document.body) {
    // portrait-ui：竖屏菜单；landscape-ui：手机横屏菜单。battle-portrait：竖屏对局内真竖屏
    document.body.classList.toggle('portrait-ui', isPortrait && inMenuUI);
    document.body.classList.toggle('landscape-ui', isPhoneLandscape);
    document.body.classList.toggle('battle-portrait', isPortrait && !inMenuUI);
  }
  // 📱 方向变化时刷新菜单背景源（竖屏图/横屏图切换）
  if (inMenuUI && (typeof _lastMenuOrientation === 'undefined' || _lastMenuOrientation !== isPortrait)) {
    _lastMenuOrientation = isPortrait;
    try { _applyParchmentTheme(true); } catch(e) {}
  }
  const stage = document.getElementById('stage');
  const c = canvas;
  if (!stage) return;

  // ===== 统一等比缩放系统：虚拟设计分辨率 + 单一缩放系数 + DPR 高清背板 =====
  // 横屏虚拟分辨率 1280×720，竖屏 720×1280；所有画面元素（Canvas 图像/DOM UI/字体/图标）
  // 均在固定虚拟坐标系内布局，再由同一个 scale 等比映射到屏幕，
  // 任何缩放下相对位置与比例完全一致，杜绝错位/偏移/拉伸变形
  const _vDesign = isPortrait ? { w: 720, h: 1280 } : { w: 1280, h: 720 };
  const _s = Math.min(w / _vDesign.w, h / _vDesign.h); // 唯一等比缩放系数
  let _dpr = 1;
  try { _dpr = Math.max(1, Math.min(window.devicePixelRatio || 1, 2)); } catch (_) {}
  let _k = _s * _dpr;                                    // 背板相对虚拟分辨率的倍率（高清）
  const _MAX_BACKING = 6000000;                          // 背板总像素上限（移动端防爆显存）
  if (_vDesign.w * _k * _vDesign.h * _k > _MAX_BACKING) {
    _k = Math.sqrt(_MAX_BACKING / (_vDesign.w * _vDesign.h));
  }
  // 舞台：固定虚拟尺寸 + 居中等比缩放（不足区域留黑边）
  // 容器与舞台定位均使用 innerWidth/innerHeight 精确像素，彻底杜绝 100vw 与 innerWidth 不一致导致的偏移
  const wrap = document.getElementById('gameWrap');
  if (wrap) {
    wrap.style.setProperty('width', w + 'px', 'important');
    wrap.style.setProperty('height', h + 'px', 'important');
  }
  stage.style.width = _vDesign.w + 'px';
  stage.style.height = _vDesign.h + 'px';
  stage.style.left = (w / 2) + 'px';
  stage.style.top = (h / 2) + 'px';
  stage.style.transform = 'translate(-50%, -50%) scale(' + _s + ')';
  document.documentElement.style.background = '#060614';
  // 画布：CSS 始终铺满舞台（随舞台一起等比缩放），背板按 DPR 高清分配
  if (c) {
    c.style.width = '100%';
    c.style.height = '100%';
    c.style.borderRadius = isPortrait ? '0' : '';
    c.style.imageRendering = 'auto';   // 平滑等比缩放，避免像素化锯齿
    const _bw = Math.max(1, Math.round(_vDesign.w * _k));
    const _bh = Math.max(1, Math.round(_vDesign.h * _k));
    if (c.width !== _bw) c.width = _bw;
    if (c.height !== _bh) c.height = _bh;
  }
  // 全局逻辑视口：游戏世界/HUD 一律使用虚拟坐标 W/H，与设备物理分辨率完全解耦
  W = _vDesign.w; H = _vDesign.h;
  window.__VIEW__ = {
    vw: _vDesign.w, vh: _vDesign.h, scale: _s, dpr: _dpr, backing: _k,
    orientation: isPortrait ? 'portrait' : 'landscape'
  };
  // 横竖屏/窗口变化后摄像机立即按新 W/H 重新居中（帧循环也会持续跟随）
  try {
    if (typeof cam !== 'undefined' && cam && typeof player !== 'undefined' && player) {
      cam.x = player.x - W / 2;
      cam.y = player.y - H / 2;
    }
  } catch (_) {}
}
window.addEventListener('resize', resize);
window.addEventListener('orientationchange', resize);
if (typeof window.visualViewport !== 'undefined') {
  window.visualViewport.addEventListener?.('resize', resize);
}
// DOMContentLoaded 后再跑一次，确保 canvas W/H 已就绪
window.addEventListener('DOMContentLoaded', resize);
// —— 浏览器缩放兜底：部分浏览器缩放时 resize 事件延迟或不触发，
// 用轻量轮询检测 innerWidth/innerHeight 变化并重新布局，杜绝缩放后UI偏移 ——
(function () {
  var _lw = window.innerWidth, _lh = window.innerHeight;
  setInterval(function () {
    var w = window.innerWidth, h = window.innerHeight;
    if (w !== _lw || h !== _lh) { _lw = w; _lh = h; try { resize(); } catch (_) {} }
  }, 400);
})();
resize();

/* ---------- 工具函数 ---------- */
const rand  = (a, b) => a + Math.random() * (b - a);
const randi = (a, b) => Math.floor(rand(a, b));
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
// Fisher-Yates 洗牌（觉醒池随机抽取用）
function shuffle(a) {
  for (let i = a.length - 1; i > 0; i--) {
    const j = (Math.random() * (i + 1)) | 0;
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}
const lerp  = (a, b, t) => a + (b - a) * t;
const dist  = (a, b) => Math.hypot(a.x - b.x, a.y - b.y);
const dist2 = (a, b) => { const dx = a.x - b.x, dy = a.y - b.y; return dx * dx + dy * dy; };
const TAU = Math.PI * 2;

/* =============================================================
   🔬 DEBUG POINT — Instrumentation (session: game-freeze-bug)
   · 仅运行时日志采集环形缓冲 + 网络上报 Debug Server，不改业务逻辑
   · 通过浏览器 evaluate 读取 window.__DBG__.events
   ============================================================= */
//#region debug-point bootstrap (global ring buffer + network report + onerror)
(function initDbg(){
  const SID = 'game-freeze-bug';
  const MAX = 2000;
  const buf = [];
  const DBG_URL = 'http://127.0.0.1:7778/event';
  const state = {
    sessionId: SID, runId: 'pre-fix', events: buf, max: MAX, idx: 0,
    perf: {lastT: 0, framesThisSec: 0, nextReport: 1.0, maxFdt: 0},
    _pending: 0
  };
  state.push = function(ev){
    ev.sessionId = SID; ev.runId = 'pre-fix'; ev.ts = Date.now(); ev.i = state.idx++;
    if (buf.length >= MAX) buf.shift();
    buf.push(ev);
    try {
      const payload = JSON.stringify({
        sessionId: SID, runId: 'pre-fix',
        hypothesisId: ev.hyp || '_',
        location: ev.loc || '',
        msg: ev.msg || '',
        data: ev.data || {},
        ts: ev.ts
      });
      if (state._pending < 8) {
        state._pending++;
        fetch(DBG_URL, {method:'POST',body:payload,headers:{'Content-Type':'application/json'}})
          .catch(()=>{})
          .finally(()=>{ state._pending--; });
      }
    } catch(_) {}
  };
  window.__DBG__ = state;
  try {
    window.addEventListener('error', function(e){
      state.push({hyp:'E',msg:'onerror: '+(e.message||'')+' @'+(e.filename||'?')+':'+(e.lineno||'?')+':'+(e.colno||'?'), stack:(e.error&&e.error.stack)?String(e.error.stack).slice(0,400):''});
    }, true);
    window.addEventListener('unhandledrejection', function(e){
      state.push({hyp:'E',msg:'unhandledrejection: '+(e.reason?String(e.reason).slice(0,400):'')});
    }, true);
  } catch(_) {}
  state.push({hyp:'_',msg:'dbg bootstrap OK, url='+DBG_URL});
})();
//#endregion debug-point bootstrap


/* =============================================================
   💰 元进度（金币 / 天赋 / 职业解锁）
   ============================================================= */
const META_KEY = 'survivor_rogue_meta_v1';
/* 新版 meta 默认值（五行祭坛/灵石/图鉴批次新增字段；旧档经 defaultMeta 深合并升级） */
const WUXING_ELEMENTS = ['metal', 'wood', 'water', 'fire', 'earth'];
function defaultMeta() {
  return {
    coins: 0, talents: {}, equippedWeapon: 'none', unlocks: ['metal_sword'],
    // —— 五行祭坛批次：局外资源与养成 ——
    spirit: 0,                                   // 灵石（通用稀有货币）
    fragments: { metal: 0, wood: 0, water: 0, fire: 0, earth: 0 }, // 各系碎片（突破门槛）
    origin: 0,                                   // 五行之源（觉醒门槛）
    luck: 0,                                     // 幸运等级 0-10
    altar: { metal: 0, wood: 0, water: 0, fire: 0, earth: 0 },    // 各系祭坛等级 0-21
    collection: { seen: {}, secret: {} },        // 图鉴：见过 / 隐藏成就
    flags: { spiritGuide: false, zoneUnlocked: 1 }, // zoneUnlocked: 初始只开放 zone 1 (earth)；通关完整 25 波后解锁下一关（最大 5）
  };
}
function getMeta() {
  let m = {};
  try { m = JSON.parse(localStorage.getItem(META_KEY)) || {}; }
  catch { m = {}; }
  const d = defaultMeta();
  // 浅层标量默认
  const out = Object.assign({}, d, m);
  // 深层对象默认（旧档缺字段时补齐，不覆盖已有值）
  out.fragments  = Object.assign({}, d.fragments,  m.fragments  || {});
  out.altar      = Object.assign({}, d.altar,      m.altar      || {});
  out.collection = { seen: Object.assign({}, (m.collection && m.collection.seen) || {}),
                     secret: Object.assign({}, (m.collection && m.collection.secret) || {}) };
  out.flags      = Object.assign({}, d.flags,      m.flags      || {});
  if (!Array.isArray(out.unlocks) || !out.unlocks.length) out.unlocks = d.unlocks;
  return out;
}
function saveMeta(m) { try { if (!m) m = getMeta(); localStorage.setItem(META_KEY, JSON.stringify(m)); } catch {} }
/* —— 五行资源/解锁唯一写口（写后刷新菜单资源 HUD，UI 未加载时静默跳过）—— */
function _metaTouch(m) { saveMeta(m); try { if (typeof refreshAltarHud === 'function') refreshAltarHud(); } catch (_) {} }
function metaAddSpirit(n) { const m = getMeta(); m.spirit = Math.max(0, (m.spirit || 0) + n); _metaTouch(m); return m.spirit; }
function metaAddFragment(el, n) { const m = getMeta(); if (!m.fragments) m.fragments = defaultMeta().fragments; m.fragments[el] = (m.fragments[el] || 0) + n; _metaTouch(m); return m.fragments[el]; }
function metaAddOrigin(n) { const m = getMeta(); m.origin = (m.origin || 0) + n; _metaTouch(m); return m.origin; }
/* 图鉴解锁写口：kind='seen'|'secret'，id 去重；返回 true=本次新发（用于发奖励） */
function awardUnlock(kind, id) {
  if (kind !== 'seen' && kind !== 'secret') return false;
  const m = getMeta();
  if (!m.collection) m.collection = { seen: {}, secret: {} };
  if (m.collection[kind][id] != null) return false; // 0 也是有效记录（菜单态解锁）
  m.collection[kind][id] = timeElapsedForMeta();
  _metaTouch(m);
  return true;
}
function isUnlocked(kind, id) { const m = getMeta(); return !!(m.collection && m.collection[kind] && m.collection[kind][id] != null); }
/* 解锁时间戳（记录当局秒数；菜单态 timeElapsed=0 时存 1 作为真值，仅用于排序/展示） */
function timeElapsedForMeta() {
  try { if (typeof timeElapsed === 'number' && timeElapsed > 0) return Math.round(timeElapsed); } catch (_) {}
  return 1;
}

