const EQUIP_RARITY_WEIGHT = { '普通': 50, '稀有': 30, '史诗': 10 };

function rollEquipment() {
  const slots = ['head', 'chest', 'legs'];
  const slot = slots[Math.floor(Math.random() * 3)];
  const pool = EQUIPMENT_POOL[slot];
  // 按稀有度权重抽取
  const weighted = [];
  for (const e of pool) {
    const w = EQUIP_RARITY_WEIGHT[e.rarity] || 10;
    for (let i = 0; i < w; i++) weighted.push(e);
  }
  return { slot, item: weighted[Math.floor(Math.random() * weighted.length)] };
}

function applyEquipment(player, slot, item) {
  // 如果已有装备，先移除旧装备效果（记录原始值太复杂，改为不替换已有装备）
  if (player.equipment[slot]) return false; // 已有该部位装备，不可替换
  player.equipment[slot] = item;
  item.apply(player);
  rebuildBlades(player);
  return true;
}

/* ⚔️ 按 id 从装备池查找装备（用于存档恢复；旧存档/未匹配 id 返回 null） */
function findEquipmentById(id) {
  if (!id) return null;
  for (const slot of ['head', 'chest', 'legs']) {
    const it = (EQUIPMENT_POOL[slot] || []).find(x => x.id === id);
    if (it) return it;
  }
  return null;
}

