/* 发放隐藏成就奖励（内部） */
function _grantCollectionReward(entry) {
  if (!entry || !entry.reward) return;
  if (entry.reward.type === 'fragment') metaAddFragment(entry.reward.el, entry.reward.n);
  else if (entry.reward.type === 'spirit') metaAddSpirit(entry.reward.n);
}
/* 结算时统一判定通关隐藏成就，返回本次新发 {id, reward} 列表（供结算界面展示与发奖）。
   注意：本函数只做判定与 awardUnlock（seen/secret 写入），不直接操作 meta 数值；
   奖励发放由调用方（triggerGameOver）在同一 meta 对象上统一执行，避免多对象覆盖。 */
function evaluateRunSecrets(p, win) {
  const fresh = [];
  if (!win || !p) return fresh;
  try {
    for (const el of WUXING_ELEMENTS) {
      if (stoneLevel(p, el) >= GAME_CONFIG.collection.stoneSecretWinLevel) {
        if (awardUnlock('secret', 'stone_' + el)) fresh.push('stone_' + el);
      }
    }
    if (p.samadhiMeteor && awardUnlock('secret', 'stone_sanwei')) fresh.push('stone_sanwei');
    if (p.resWoodFire && hasFullAffinity(p, 'fire') && stoneLevel(p, 'wood') >= 3 && awardUnlock('secret', 'bond_wood_fire')) fresh.push('bond_wood_fire');
    if (p.resWaterFire && hasFullAffinity(p, 'water') && hasFullAffinity(p, 'fire') && awardUnlock('secret', 'bond_water_fire')) fresh.push('bond_water_fire');
  } catch (_) {}
  return fresh;
}
/* =============================================================
   ☯ 五行修炼 · 命石祭坛后端（局外永久养成 0-21 级）
   首批仅开放 wood；其余四系卡位"未开放"（配置已预留）。
   升级写口 SpiritStoneUpgrade(el)：校验→扣除→落盘→返回结果码。
   开局生效 applyAltarToPlayer(p)：在 resetGame 构造 Player 后调用。
   ============================================================= */
const _GC_ALT = GAME_CONFIG.altar;
/* 升到目标等级所需消耗 {spirit, fragment:{el,n}, origin, locked} */
function altarCost(el, targetLv) {
  const cfg = _GC_ALT[el];
  if (!cfg) return { locked: true };
  const cost = { spirit: 0, fragment: null, origin: 0, locked: false };
  if (targetLv < 1 || targetLv > _GC_ALT.maxLevel) return { locked: true };
  // 灵石消耗（共用曲线 × 系别价格因子）
  const sc = _GC_ALT._spiritCost;
  const cf = cfg.costFactor || 1;
  if (sc && sc[targetLv] != null) cost.spirit = Math.round(sc[targetLv] * cf);
  // Lv.11 突破门槛
  if (targetLv === 11 && cfg.gate11) cost.fragment = { el: cfg.gate11.fragment, n: cfg.gate11.fragmentN };
  // Lv.21 觉醒门槛
  if (targetLv === 21 && cfg.gate21) cost.origin = cfg.gate21.origin || 0;
  return cost;
}
/* 当前等级的被动效果（五系通用结构） */
function altarEffect(el, lv) {
  const cfg = _GC_ALT[el];
  if (!cfg) return { hp: 0, primary: 0, passive11: null, per12_20: 0, aura21: null, affinityLevel: 0, shelter: false, regenMul: 1 };
  const hp = Math.min(lv, 10) * (cfg.hpPerLevel_1_10 || 0);
  // Lv.1-10 主属性累计
  const primary = lv > 0 ? Math.min(lv, 10) * (cfg.primaryStat ? cfg.primaryStat.value : 0) : 0;
  const primaryType = cfg.primaryStat ? cfg.primaryStat.type : null;
  // Lv.11 被动
  const passive11 = lv >= 11 ? (cfg.passive11 || null) : null;
  // Lv.12-20 每级加成累计
  const per12_20 = lv >= 12 ? (Math.min(lv, 20) - 11) * (cfg.perLevel_12_20 ? cfg.perLevel_12_20.value : 0) : 0;
  const per12_20Type = cfg.perLevel_12_20 ? cfg.perLevel_12_20.type : null;
  // Lv.21 光环
  const aura21 = lv >= 21 ? (cfg.aura21 || null) : null;
  // 木系庇护特殊（向后兼容）
  const shelter = el === 'wood' ? lv >= 11 : false;
  const regenMul = (el === 'wood' && lv >= 12) ? 1 + (Math.min(lv, 20) - 11) * (cfg.perLevel_12_20 ? cfg.perLevel_12_20.value : 0) : 1;
  // 非本系开局命石等级
  let affinityLevel = 0;
  if (cfg.runStartAffinity) {
    for (const k of Object.keys(cfg.runStartAffinity).sort((a, b) => b - a)) {
      if (lv >= Number(k)) { affinityLevel = cfg.runStartAffinity[k]; break; }
    }
  }
  return { hp, primary, primaryType, passive11, per12_20, per12_20Type, aura21, affinityLevel, shelter, regenMul };
}
/* 唯一升级写口：返回 {ok, code, lv, cost} code: ok|insufficient|max|locked */
function SpiritStoneUpgrade(el) {
  const m = getMeta();
  const cur = (m.altar && m.altar[el]) || 0;
  if (!_GC_ALT.unlocked.includes(el)) return { ok: false, code: 'locked', lv: cur };
  if (cur >= _GC_ALT.maxLevel) return { ok: false, code: 'max', lv: cur };
  const target = cur + 1;
  const cost = altarCost(el, target);
  // 校验资源
  if (cost.spirit > (m.spirit || 0)) return { ok: false, code: 'insufficient', lv: cur, cost };
  if (cost.fragment && (m.fragments[cost.fragment.el] || 0) < cost.fragment.n) return { ok: false, code: 'insufficient', lv: cur, cost };
  if (cost.origin > (m.origin || 0)) return { ok: false, code: 'insufficient', lv: cur, cost };
  // 扣除
  m.spirit -= cost.spirit;
  if (cost.fragment) m.fragments[cost.fragment.el] -= cost.fragment.n;
  if (cost.origin) m.origin -= cost.origin;
  if (!m.altar) m.altar = defaultMeta().altar;
  m.altar[el] = target;
  _metaTouch(m);
  return { ok: true, code: 'ok', lv: target, cost };
}
/* 幸运购买 */
function buyLuck() {
  const m = getMeta();
  const Lk = GAME_CONFIG.luck;
  const cur = m.luck || 0;
  if (cur >= Lk.maxLevel) return { ok: false, code: 'max' };
  const cost = Lk.costBase + cur * Lk.costStep;
  if ((m.spirit || 0) < cost) return { ok: false, code: 'insufficient', cost };
  m.spirit -= cost;
  m.luck = cur + 1;
  _metaTouch(m);
  return { ok: true, code: 'ok', lv: cur + 1, cost };
}
/* 开局生效：在 resetGame 构造 Player 后调用，把五系祭坛永久数值挂到玩家 */
function applyAltarToPlayer(p) {
  if (!p) return;
  const m = getMeta();
  const ELEMENTS = ['metal', 'wood', 'water', 'fire', 'earth'];
  p.altarAuras = [];                          // Lv.21 光环数组
  p.woodShelter = false; p._shelterCd = 0; p._shelterActive = 0;
  p.altarDmgReduction = 0;                    // 祭坛累计减伤
  p.altarShieldChance = 0;                    // 祭坛累计挡伤概率
  p.altarIgniteChance = 0;                    // 祭坛累计点燃概率
  p.altarCritChance = 0;                      // 祭坛累计暴击率
  p.altarCdr = 0;                             // 祭坛累计冷却缩减
  for (const el of ELEMENTS) {
    const lv = (m.altar && m.altar[el]) || 0;
    if (lv <= 0) continue;
    const eff = altarEffect(el, lv);
    // 最大生命（全系统有）
    if (eff.hp > 0) { p.maxHp += eff.hp; p.hp = Math.min(p.maxHp, p.hp + eff.hp); }
    // Lv.1-10 主属性
    if (eff.primaryType === 'armor') p.armor = (p.armor || 0) + eff.primary;
    else if (eff.primaryType === 'regen') p.regen = (p.regen || 0) + eff.primary;
    else if (eff.primaryType === 'fireRateMul') p.fireRateMul = (p.fireRateMul || 1) * (1 + eff.primary);
    else if (eff.primaryType === 'damageMul') p.damageMul = (p.damageMul || 1) * (1 + eff.primary);
    else if (eff.primaryType === 'critChance') p.critChance = (p.critChance || 0) + eff.primary;
    else if (eff.primaryType === 'cdr') p.altarCdr += eff.primary;
    // Lv.11 被动
    if (eff.passive11) {
      const pt = eff.passive11.type, pv = eff.passive11.value;
      if (pt === 'dmgReduction') p.altarDmgReduction += pv;
      else if (pt === 'shelter') { p.woodShelter = true; } // 木系森之庇护
      else if (pt === 'shieldChance') p.altarShieldChance += pv;
      else if (pt === 'igniteChance') p.altarIgniteChance += pv;
    }
    // Lv.12-20 每级加成
    if (eff.per12_20 > 0 && eff.per12_20Type) {
      if (eff.per12_20Type === 'damageMul') p.damageMul = (p.damageMul || 1) * (1 + eff.per12_20);
      // 修复：木祭坛 Lv.12-20「再生 +10%/级」应使用 altarEffect 已算好的 regenMul（1+0.1n），
      // 旧代码误用 per12_20（即 0.1~0.9 的增量本身）作乘数，导致越升级再生越低
      else if (eff.per12_20Type === 'regenMul') { p.regenMul = (p.regenMul || 1) * eff.regenMul; p.regen = (p.regen || 0) * eff.regenMul; }
      else if (eff.per12_20Type === 'armor') p.armor = (p.armor || 0) + eff.per12_20;
      else if (eff.per12_20Type === 'cdr') p.altarCdr += eff.per12_20;
      else if (eff.per12_20Type === 'critChance') p.critChance = (p.critChance || 0) + eff.per12_20;
      else if (eff.per12_20Type === 'critDmg') p.critDmg = (p.critDmg || 0) + eff.per12_20;
      // 修复：水祭坛 Lv.12-20「攻速 +3%/级」此前缺少 fireRateMul 分支，加成被静默丢弃
      else if (eff.per12_20Type === 'fireRateMul') p.fireRateMul = (p.fireRateMul || 1) * (1 + eff.per12_20);
    }
    // Lv.21 光环
    if (eff.aura21) p.altarAuras.push({ ...eff.aura21, _tick: 0 });
    // 非本系职业开局局内命石等级
    if (eff.affinityLevel > 0 && CLASS_ELEMENT[p.classId] !== el) {
      p.elementStones[el] = Math.min(3, (p.elementStones[el] || 0) + eff.affinityLevel);
      try { awardUnlock('seen', 'stone_' + el); } catch (_) {}
    }
  }
  // 把减伤合并到 dmgReduction 乘区
  if (p.altarDmgReduction > 0) p.dmgReduction = (p.dmgReduction || 0) + p.altarDmgReduction;
}
/* 菜单态资源 HUD 刷新钩子（UI 未加载时静默） */
function refreshAltarHud() { try { if (typeof renderAltarView === 'function') renderAltarView(); } catch (_) {} }

class Bullet {
  constructor(x, y, angle, opt) {
    this.x = x; this.y = y;
    this.kind = opt.kind || 'bullet';
    this.speed = opt.speed;
    this.vx = Math.cos(angle) * this.speed;
    this.vy = Math.sin(angle) * this.speed;
    this.ang = angle;
    this.dmg = opt.dmg;
    this.pierce = opt.pierce || 0;
    this.hitSet = new Set();
    this.life = opt.life;
    this.age = 0;                                    // 已存活时间（震波等动画用）
    if (this.kind === 'shockwave') this.lifeMax = opt.life || 0.6;  // 震波总寿命
    this.splash = opt.splash || 0;
    this.r = (this.kind === 'orb') ? 11
          : (this.kind === 'arrow') ? 4
          : (this.kind === 'summon') ? 7
          : (this.kind === 'evoBullet' || this.kind === 'evoArcBullet') ? 10
          : (this.kind === 'arcBullet') ? 8
          : 5;
    this.dead = false;
    // —— 玩家子弹标识：命中走玩家 vs 敌人的分支；并决定“不因时间/距离消失”
    this.player = true;

    // —— ⚠️ 特殊子弹携带的扩展参数（构造函数必须显式复制，否则 onHit/落地效果全部失效）——
    this.zoneData   = opt.zoneData   || null;   // spore 落地生成荆棘领域所需数据
    this.knockback  = opt.knockback  || 0;      // waterKnife 击退力
    this.explosion  = opt.explosion  || null;   // fireball/meteor 爆炸参数
    this.onHitCustom = opt.onHitCustom || null; // 自定义命中回调（毒弹等）
    if (opt.radius) this.r = opt.radius;         // bubble 等需要更大碰撞半径的子弹

    // 🎯 远程武器射程上限：屏幕可视宽度的 3/4
    this.maxRange = opt.maxRange || null;
    this.traveled = 0;
    this._ox = x; this._oy = y;

    // —— 抛物线投掷弹（木·青萝孢子炸弹）——
    this.isLob = !!opt.isLob;
    if (this.isLob) {
      this.lobStart = opt.lobStart || { x: x, y: y };
      this.lobTarget = opt.lobTarget || { x: x + vx, y: y + vy };
      this.lobTargetEnemy = opt.lobTargetEnemy || null;  // 追踪目标引用，每帧刷新 lobTarget
      this.lobDur = opt.lobDur || 1.0;
      this.lobArcH = opt.lobArcH || 70;
      this.lobT = 0;                            // 飞行进度 0→1
      this._height = 0;                         // 当前视觉高度（用于绘制偏移）
    }

    // —— 弧形贝塞尔弹（冒险者）——
    this.isArc = !!opt.isArc;
    if (this.isArc) {
      this.arcP0 = opt.arcP0;                     // 起点（玩家位置）
      this.arcP1 = opt.arcP1;                     // 控制点（弯弧“鼓包”）
      this.arcTarget = opt.arcTarget || null;     // 锁定敌人（动态P2）
      this.arcT = 0;                              // 进度 0→1
      this.arcDur = opt.arcDur || 0.5;            // 总时长（秒）
      this.arcHand = opt.arcHand || 1;            // 手性
      this.arcFinished = false;
    }
  }
  update(dt) {
    // —— 玩家子弹不因“时间过长/飞出距离”消失：仅在越界 / pierce 耗尽 / postCd 走完 才死亡
    //    （保留 life 字段只读不扣减，兼容未来外部判定；EnemyBullet 类内部另有它自己的 life 限制）
    //    ⚠️ spore（木·青萝孢子炸弹）/ bubble（水·沧澜水泡）例外：它们依赖 life<=0 触发落地/破裂效果，
    //       必须扣减 life，否则命中不到敌人时会永远飞行、永远不生成荆棘领域/水泡溅射
    if (this.kind === 'shockwave') this.age += dt;  // 🌊 震波动画年龄
    if (!this.player || this.kind === 'spore' || this.kind === 'bubble' || this.kind === 'shockwave') this.life -= dt;
    if (this.isArc) {
      // —— 贝塞尔曲线插值（Q 二次：P0 → P1 → P2）——
      // 规则：
      //  a) 若 arcTarget 死亡：优先重新锁定一个新敌人（改造成新的 P0→P1→P2 贝塞尔，延长 arcDur）
      //  b) 重锁后仍无目标：按当前方向作 _fallback 直线继续（允许穿透）
      //  c) arcFinished 到达 t=1：兜底 100%命中；若仍有 pierce > 0 则沿导数方向直线继续（即使目标死也继续）
      //  d) 兜底命中时给 this._arcGuaranteedHit=true，避免 processCollisions 对同一目标重复扣一次 pierce
      let tgt = this.arcTarget;
      let tgtAlive = tgt && !tgt.dead;
      // —— 重锁：目标死（且未重锁过）→ 找最近敌人重新建立弧段 ——
      if (!tgtAlive && !this._fallback) {
        // —— 跟踪优化：允许最多重锁 3 次（原仅 1 次）；重锁半径从 1200 → 3000 px，覆盖全屏
        const maxRetargets = 3;
        if ((this._arcRetargetCount ?? 0) < maxRetargets) {
          const nextTgt = (typeof nearestEnemyFromPoint === 'function')
            ? nearestEnemyFromPoint(this.x, this.y, tgt, 3000 * 3000)
            : null;
          if (nextTgt) {
            // 新弧：以当前点为 P0；P1 在当前速度方向推前 45% 距离并叠加原手性半径（半径再缩小一半更贴直线）
            const dxRaw = this.vx, dyRaw = this.vy;
            const Lv = Math.hypot(dxRaw, dyRaw) || 1;
            //#region debug-point C (hypC: Lv=0 → NaN nrmX / crash via NaN coords)
            try {
              const __dbg = window.__DBG__;
              if (__dbg && Lv < 0.0001 && Math.abs(dxRaw) < 1e-6 && Math.abs(dyRaw) < 1e-6) {
                if (!(__dbg._cSpam) || Date.now() - __dbg._cSpam > 200) {
                  __dbg._cSpam = Date.now();
                  __dbg.push({hyp:'C', msg:'ARC_RETARGET_ZEROV: b.x='+this.x.toFixed(0)+' y='+this.y.toFixed(0)+' speed='+this.speed+' arcT='+(this.arcT||0).toFixed(3)+' hand='+(this.arcHand||0)+' ret='+(this._arcRetargetCount||0)});
                }
              }
            } catch(_) {}
            //#endregion debug-point C
            const nrmX = dxRaw / Lv, nrmY = dyRaw / Lv;
            const perpX = -nrmY, perpY = nrmX;
            const dxT = nextTgt.x - this.x, dyT = nextTgt.y - this.y;
            const dist = Math.hypot(dxT, dyT) || 1;
            const hand = ((this.arcHand || 1) >= 0) ? 1 : -1;
            const radius = (22 + Math.min(36, dist * 0.08)) * hand;
            const P1new = {
              x: this.x + nrmX * (dist * 0.45) + perpX * radius,
              y: this.y + nrmY * (dist * 0.45) + perpY * radius,
            };
            const estArcLen = dist + Math.abs(radius) * 1.05;
            this.arcP0 = { x: this.x, y: this.y };
            this.arcP1 = P1new;
            this.arcTarget = nextTgt;
            tgt = nextTgt;
            tgtAlive = true;
            this.arcT = 0;
            this.arcDur = Math.max(0.18, Math.min(1.2, estArcLen / (this.speed || 540)));
            this.arcFinished = false;
            this._arcRetargetCount = (this._arcRetargetCount ?? 0) + 1;
            this._arcRetargetDone = true;   // 兼容旧字段：有过至少一次重锁
          }
        }
      }
      // 若仍没有目标：建立 _fallback（直线飞行）
      if (!this._fallback) {
        tgtAlive = tgt && !tgt.dead;
        if (!tgtAlive) {
          const dx = this.vx, dy = this.vy;
          const L = Math.hypot(dx, dy) || 1;
          this._fallback = { x: this.x + dx / L * 1400, y: this.y + dy / L * 1400 };
        }
      }
      const P0 = this.arcP0;
      const P1 = this.arcP1;
      tgtAlive = tgt && !tgt.dead;
      const P2 = (tgtAlive) ? { x: tgt.x, y: tgt.y } : this._fallback;

      if (!this.arcFinished) {
        this.arcT += dt / this.arcDur;
        if (this.arcT >= 1) {
          this.arcT = 1;
          this.arcFinished = true;
          // —— 穿透修复：弧完成后，出口方向用“P0→P2 直线方向 + 原手性切向微偏”，
          //    不再用贝塞尔末端导数（曲线末端切线常垂直于目标连线导致 pierce 偏出走廊）。
          //    这样 100% 命中后 pierce 直线继续时，会沿着玩家到目标的延长线，
          //    刚好命中沿连线排列的后续敌人
          if (tgtAlive && tgt) {
            const dxEx = (tgt.x - this.arcP0.x), dyEx = (tgt.y - this.arcP0.y);
            const lenEx = Math.hypot(dxEx, dyEx) || 1;
            const nxEx = dxEx / lenEx, nyEx = dyEx / lenEx;
            // 加入原手性的轻微出口角度偏移（弯弧视觉感保留，不直溜溜飞走）
            // —— 跟踪优化：偏角从 8° 缩到 3°，弧线结束后更贴直线，利于穿透与继续连射
            const perpExX = -nyEx, perpExY = nxEx;
            const handSign = ((this.arcHand || 1) >= 0) ? 1 : -1;
            const exitAng = 0.052 * handSign; // ~3°
            const csE = Math.cos(exitAng), snE = Math.sin(exitAng);
            const vxN = nxEx * csE + perpExX * snE;
            const vyN = nyEx * csE + perpExY * snE;
            this.vx = vxN * this.speed;
            this.vy = vyN * this.speed;
            this.ang = Math.atan2(vyN, vxN);
          }
          // 100% 命中兜底：独立走一次伤害 + onHit，并在后续 processCollisions 里通过 hitSet 去重
          if (tgtAlive && tgt && !this.hitSet.has(tgt)) {
            this.x = tgt.x; this.y = tgt.y;
            const arcDmg = this.dmg;
            if (typeof spawnFloat === 'function') spawnFloat(tgt.x + (Math.random()*16-8), tgt.y - tgt.r, `-${Math.round(arcDmg)}`, this.kind === 'evoArcBullet' ? '#ffd58a' : '#a3d0ff');
            if (typeof addParticle === 'function' && typeof Particle === 'function') {
              const col = (this.kind === 'evoArcBullet') ? '#ffd58a' : '#a3d0ff';
              for (let i = 0; i < 5; i++) addParticle(new Particle(this.x, this.y, col));
            }
            try {
              this.hitSet.add(tgt);
              tgt.hurt(arcDmg, this.vx * 0.002, this.vy * 0.002);
              this._arcGuaranteedHit = true;   // 给 processCollisions 看：这次已经算过 pierce，不要重复扣
              this._arcGuaranteedTarget = tgt;
              this.onHit(tgt);
            } catch (_) {}
          } else if (tgtAlive) {
            this.x = tgt.x; this.y = tgt.y;
          }
          // —— 命中（或到达弧末端）后：有穿透强化则重新锁定最近敌人再飞一段弧线；无穿透则消失 ——
          if (this.pierce > 0) {
            this.pierce--;
            const fromObj = (tgtAlive && tgt) ? tgt : null;
            const nextTgt = (typeof nearestEnemyFromPoint === 'function')
              ? nearestEnemyFromPoint(this.x, this.y, fromObj, 3000 * 3000)
              : null;
            if (nextTgt && !this.hitSet.has(nextTgt)) {
              // 以当前点为 P0，沿当前速度方向 + 原手性建新控制点，飞向新目标
              const dxT = nextTgt.x - this.x, dyT = nextTgt.y - this.y;
              const dist = Math.hypot(dxT, dyT) || 1;
              let lvx = this.vx, lvy = this.vy;
              let Lv = Math.hypot(lvx, lvy);
              if (Lv < 1e-6) { lvx = dxT / dist; lvy = dyT / dist; Lv = 1; }
              const nrmX = lvx / Lv, nrmY = lvy / Lv;
              const perpX = -nrmY, perpY = nrmX;
              const hand = ((this.arcHand || 1) >= 0) ? 1 : -1;
              const radius = (22 + Math.min(36, dist * 0.08)) * hand;
              this.arcP0 = { x: this.x, y: this.y };
              this.arcP1 = { x: this.x + nrmX * (dist * 0.45) + perpX * radius,
                             y: this.y + nrmY * (dist * 0.45) + perpY * radius };
              this.arcTarget = nextTgt;
              this.arcT = 0;
              this.arcFinished = false;
              this.arcDur = Math.max(0.18, Math.min(1.2, dist / (this.speed || 540)));
              this._arcPierceWindow = 0;
              this._arcPostCd = 0;
              this._fallback = null;
            } else {
              this.dead = true;
            }
          } else {
            // 无穿透：命中第一个敌人即消失
            this.dead = true;
          }
        }
      }
      // —— 导数 & 朝向：如果已经 arcFinished 并在兜底命中里重写了出口方向（沿 P0→P2 延长线），
      //    就不要再用贝塞尔末端切线覆盖 vx/vy/ang，那会把正确的出口方向掰回曲线切线导致穿透失败
      if (!this.arcFinished || !(this.vx || this.vy || this.ang)) {
        const t = this.arcT;
        const omt = 1 - t;
        const dxB = 2*omt*(P1.x - P0.x) + 2*t*(P2.x - P1.x);
        const dyB = 2*omt*(P1.y - P0.y) + 2*t*(P2.y - P1.y);
        const dBlen = Math.hypot(dxB, dyB) || 1;
        this.vx = dxB / dBlen * this.speed;
        this.vy = dyB / dBlen * this.speed;
        this.ang = Math.atan2(dyB, dxB);
      }
      const t = this.arcT;
      const omt = 1 - t;
      const nx = omt*omt*P0.x + 2*omt*t*P1.x + t*t*P2.x;
      const ny = omt*omt*P0.y + 2*omt*t*P1.y + t*t*P2.y;
      if (!this.arcFinished) {
        this.x = nx; this.y = ny;
      } else {
        // —— 无限飞行：arcFinished 后永远按当前 vx/vy 直线前进，
        //    不再依赖 pierce / _arcPierceWindow / _fallback；三者任一为真或假都继续飞，
        //    直到越界 / collisions 里 pierce=0 且无窗口 → dead
        this.x += this.vx * dt;
        this.y += this.vy * dt;
        if ((this._arcPierceWindow ?? 0) > 0) this._arcPierceWindow -= dt;
      }
      // —— 玩家子弹不再“时间/距离消失”：删除旧 postCd 自动判死（原 40ms 窗口即死会导致刚命中就没）。
      //    仅保留 0.04s “命中后允许碰撞补判”窗口：arcFinished 瞬间若还有需要补判的越界/错位命中，
      //    等下一帧 collisions 跑过一次。若 arcFinished 时 pierce 已<0、窗口跑完、无 fallback，
      //    也仍不主动 dead → 子弹会按当前方向无限飞，直到它飞出 WORLD 边界被下一行判死。
      if (this.arcFinished && this.pierce <= 0 && ((this._arcPierceWindow ?? 0) <= 0) && !this._fallback) {
        this._arcPostCd = (this._arcPostCd ?? 0.04) - dt;
        // —— 只当 postCd 已跑完 AND 弧弹已经完全没移动时才死（极少发生：vx=vy=0 且所有条件满足）
        //    正常情况下 vx/vy 非 0 就继续直线飞，靠越界边界判死
        if (this._arcPostCd <= 0 && Math.abs(this.vx) < 1e-6 && Math.abs(this.vy) < 1e-6) {
          this.dead = true;
        }
      }
    } else if (this.isLob) {
      // —— 抛物线投掷弹（木·青萝孢子炸弹）：地面位置 lerp + 垂直 sin 曲线弧高 ——
      this.lobT += dt / this.lobDur;
      if (this.lobT > 1) this.lobT = 1;
      const t = this.lobT;
      // 实时追踪目标怪物：每帧刷新落地目标为怪物当前中心位置（怪物死亡则保留最后已知位置）
      if (this.lobTargetEnemy && !this.lobTargetEnemy.dead) {
        this.lobTarget.x = this.lobTargetEnemy.x;
        this.lobTarget.y = this.lobTargetEnemy.y;
      }
      // 地面位置：起点 → 目标点 线性插值
      this.x = this.lobStart.x + (this.lobTarget.x - this.lobStart.x) * t;
      this.y = this.lobStart.y + (this.lobTarget.y - this.lobStart.y) * t;
      // 视觉高度：sin(π*t) 在 t=0.5 时达到峰值，形成上凸抛物线
      this._height = this.lobArcH * Math.sin(Math.PI * t);
      this.ang = Math.atan2(this.lobTarget.y - this.lobStart.y, this.lobTarget.x - this.lobStart.x);
      // 落地：到达终点时生成荆棘领域并销毁
      if (t >= 1 && !this._zoneSpawned) {
        this._zoneSpawned = true;
        spawnThornAt(this);
        this.dead = true;
      }
    } else {
      this.x += this.vx * dt;
      this.y += this.vy * dt;
    }
    // —— 玩家子弹：不再用 life<=0 判死；只在越界时 dead = true
    //    （非玩家子弹保持 life + 越界双保险，未来如果造非玩家 Bullet 也能正常用）
    //    spore / bubble 例外：到期落地/破裂触发效果
    if (this.kind === 'spore' && this.life <= 0 && !this._zoneSpawned) {
      this._zoneSpawned = true;
      spawnThornAt(this);
      this.dead = true;
    } else if (this.kind === 'bubble' && this.life <= 0 && !this._bubbleSplashSpawned) {
      this._bubbleSplashSpawned = true;
      spawnBubbleSplash(this, null);
      this.dead = true;
    } else if ((this.kind === 'fireball' || this.kind === 'meteor') && this.life <= 0 && !this._exploded) {
      // 🔥 火球/陨石到期未命中也爆炸
      this._exploded = true;
      if (this.explosion) triggerExplosion(this.x, this.y, this.explosion, this);
      this.dead = true;
    } else if (this.kind === 'shockwave' && this.life <= 0) {
      // 🌊 震波：寿命结束即消散（不再横穿全屏）
      this.dead = true;
    } else if ((!this.player && this.life <= 0) ||
        (this.player && (this.x < cam.x - 50 || this.x > cam.x + W + 50 || this.y < cam.y - 50 || this.y > cam.y + H + 50))) this.dead = true;
    // 🎯 射程上限：远程武器子弹飞行距离超过屏幕 3/4 宽度时消失
    if (this.player && this.maxRange) {
      const dx = this.x - this._ox, dy = this.y - this._oy;
      this.traveled = Math.hypot(dx, dy);
      if (this.traveled >= this.maxRange) {
        // 水泡：到达射程时触发溅射
        if (this.kind === 'bubble' && !this._bubbleSplashSpawned) {
          this._bubbleSplashSpawned = true;
          spawnBubbleSplash(this, null);
        }
        // 火球：到达射程时爆炸
        if ((this.kind === 'fireball' || this.kind === 'meteor') && !this._exploded && this.explosion) {
          this._exploded = true;
          triggerExplosion(this.x, this.y, this.explosion, this);
        }
        this.dead = true;
      }
    }
  }
  /* 命中一个敌人后：处理范围爆炸 */
  onHit(e) {
    if (this.splash > 0) {
      const rr = this.splash + 20;
      for (const o of enemies) {
        if (o.dead || o === e) continue;
        if (dist2(this, o) <= rr * rr) {
          o.hurt(this.dmg * 0.7);
          spawnFloat(o.x + rand(-8, 8), o.y - o.r, `-${Math.round(this.dmg * 0.7)}`, '#c98bff');
        }
      }
      for (let i = 0; i < 10; i++) addParticle(new Particle(this.x, this.y, '#c98bff'));
      orbExplosionFx.push({ x: this.x, y: this.y, t: 0, r: rr });
    }
    // —— 孢子命中：生成荆棘领域（无论是敌人还是到期消失都触发一次）——
    //    ⚠️ 用 _zoneSpawned 标记防重复：命中生成后到期判定不再二次生成
    if (this.kind === 'spore' && !this._zoneSpawned) {
      this._zoneSpawned = true;
      spawnThornAt(this);
    }
    // —— 水泡命中破裂 ——
    if (this.kind === 'bubble' && !this._bubbleSplashSpawned) {
      this._bubbleSplashSpawned = true;
      spawnBubbleSplash(this, e);
      // 💧 水之祝福：命中回血
      if (player && player.waterHeal && player.waterHealCd <= 0) {
        player.waterHealCd = 0.5;
        player.hp = Math.min(player.maxHp, player.hp + (player.waterHealAmount || 1));
      }
    }
    // ❄️ 寒冰水幕：小水球/水刀概率冻结
    if ((this.kind === 'bubbleMini' || this.kind === 'waterKnife') && player && player.waterFrozen) {
      if (Math.random() < (player.waterFrozenChance || 0.25)) {
        e._stun = Math.max(e._stun || 0, player.waterFrozenDur || 1.0);
      }
    }
    // —— 自定义 onHit（plant 子弹 etc）——
    if (typeof this.onHitCustom === 'function') this.onHitCustom(e);
    // —— 高压水刀 knockback ——
    if (this.kind === 'waterKnife' && this.knockback && e && !e.dead) {
      const ang = Math.atan2(e.y - this.y, e.x - this.x);
      e.vx = (e.vx || 0) + Math.cos(ang) * this.knockback * 20;
      e.vy = (e.vy || 0) + Math.sin(ang) * this.knockback * 20;
    }
  }
  draw() {
    // —— 🌊 震波斩：独立的扩散震波动画（三层错峰扩散环 + 前端月牙）——
    if (this.kind === 'shockwave') {
      ctx.save();
      ctx.translate(this.x, this.y);
      const life0 = this.lifeMax || 0.6;
      const age = this.age || 0;
      const p = Math.min(1, age / life0);
      const fade = Math.max(0, 1 - p);
      // 三层扩散环（错峰出现，逐渐扩大变淡）
      for (let i = 0; i < 3; i++) {
        const t = p - i * 0.22;
        if (t < 0) continue;
        const rr = 10 + t * 78;
        const ringA = Math.max(0, 1 - t) * (i === 0 ? 0.9 : 0.6);
        ctx.globalAlpha = ringA;
        ctx.lineWidth = Math.max(1.2, 5.5 - i * 1.4);
        ctx.strokeStyle = i === 0 ? '#ffffff' : (i === 1 ? '#d7dce8' : '#8fa5d0');
        ctx.shadowColor = '#5a6b9e'; ctx.shadowBlur = 16;
        ctx.beginPath(); ctx.arc(0, 0, rr, 0, TAU); ctx.stroke();
      }
      // 前端月牙弧（朝飞行方向，冲击波头部最亮）
      ctx.globalAlpha = fade;
      ctx.shadowColor = '#d7dce8'; ctx.shadowBlur = 18;
      ctx.strokeStyle = '#ffffff';
      ctx.lineWidth = 3.5; ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.arc(0, 0, 16, this.ang - 1.05, this.ang + 1.05);
      ctx.stroke();
      ctx.globalAlpha = fade * 0.7;
      ctx.strokeStyle = '#aeb9d6';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(0, 0, 24, this.ang - 0.8, this.ang + 0.8);
      ctx.stroke();
      ctx.restore();
      return;
    }
    // —— 🔥 火球/陨石直接绘制（发光球体 + 拖尾）——
    if (this.kind === 'fireball' || this.kind === 'meteor') {
      ctx.save();
      ctx.translate(this.x, this.y);
      const pulse = 1 + 0.15 * Math.sin(timeElapsed * 20);
      // 外发光
      const glowR = (this.r || 16) * 1.8 * pulse;
      const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, glowR);
      grad.addColorStop(0, 'rgba(255,200,50,0.9)');
      grad.addColorStop(0.5, 'rgba(255,100,20,0.6)');
      grad.addColorStop(1, 'rgba(255,50,0,0)');
      ctx.fillStyle = grad;
      ctx.beginPath(); ctx.arc(0, 0, glowR, 0, TAU); ctx.fill();
      // 核心
      ctx.fillStyle = '#ffeb3b';
      ctx.beginPath(); ctx.arc(0, 0, (this.r || 16) * 0.6, 0, TAU); ctx.fill();
      // 陨石拖尾
      if (this.kind === 'meteor') {
        ctx.globalAlpha = 0.5;
        ctx.strokeStyle = '#ff6b35';
        ctx.lineWidth = 4;
        ctx.beginPath();
        ctx.moveTo(0, 0); ctx.lineTo(0, -40);
        ctx.stroke();
      }
      ctx.restore();
      return;
    }
    const spr = getBulletSprite(this.kind);
    // —— 抛物线投掷弹：先画地面阴影（高度越高阴影越小越淡），再画抬高的精灵 ——
    if (this.isLob && this._height > 0.5) {
      const shadowScale = Math.max(0.4, 1 - this._height / (this.lobArcH * 1.4));
      ctx.save();
      ctx.translate(this.x, this.y);
      ctx.fillStyle = `rgba(0,0,0,${0.35 * shadowScale})`;
      ctx.beginPath();
      ctx.ellipse(0, 0, (spr.width / 2) * shadowScale, (spr.height / 2) * shadowScale * 0.6, 0, 0, TAU);
      ctx.fill();
      ctx.restore();
    }
    ctx.save();
    // 抛物线子弹的精灵抬高 _height 像素，营造飞行高度感
    ctx.translate(this.x, this.y - (this.isLob ? this._height : 0));
    ctx.rotate(this.ang);
    ctx.drawImage(spr, -spr.width / 2, -spr.height / 2);
    ctx.restore();
  }
}

