let slashJudgmentFx = [];     // ☀️ 审判之剑光柱特效
let bubbleSplashFx = [];      // 水·沧澜 水泡爆裂特效
let frostZones = [];           // ❄️ 寒冰结界冰雾区域

let timeElapsed = 0, killCount = 0, pendingLevelUps = 0, runCoins = 0;
