function updateWaterTornadoes(dt) {
  for (const t of waterTornadoes) {
    t.t += dt;
    if (t.t >= t.dur) { t.dead = true; continue; }
    t.phase += dt * 1.5;
    // 🌀 缓慢追踪最近敌人
    let nearest = null, nearestD = 9999;
    for (const e of enemies) {
      if (e.dead || e.type === 'eBullet') continue;
      const d = Math.hypot(e.x - t.x, e.y - t.y);
      if (d < nearestD) { nearestD = d; nearest = e; }
    }
    if (nearest && nearestD > 20) {
      const ang = Math.atan2(nearest.y - t.y, nearest.x - t.x);
      const accel = 80;
      t.vx += Math.cos(ang) * accel * dt;
      t.vy += Math.sin(ang) * accel * dt;
    }
    // 速度限制 + 阻尼
    const spd = Math.hypot(t.vx, t.vy);
    const maxSpd = t.moveSpeed || 40;
    if (spd > maxSpd) {
      t.vx = t.vx / spd * maxSpd;
      t.vy = t.vy / spd * maxSpd;
    }
    t.vx *= 0.95;
    t.vy *= 0.95;
    t.x += t.vx * dt;
    t.y += t.vy * dt;
    // 每 0.3 秒造成一次伤害
    t.tickTimer -= dt;
    if (t.tickTimer <= 0) {
      t.tickTimer = 0.3;
      for (const e of enemies) {
        if (e.dead || e.type === 'eBullet') continue;
        const d = Math.hypot(e.x - t.x, e.y - t.y);
        if (d <= t.r) {
          e.hurt(t.dmg, 0, 0);
          spawnFloat(e.x, e.y - e.r, `-${Math.round(t.dmg)}`, '#7afcff');
        }
      }
    }
    // ⚔️ 涡刃撕裂：周期性向外发射水刀
    if (t.hasBlades) {
      t.bladeTimer -= dt;
      if (t.bladeTimer <= 0) {
        t.bladeTimer = t.bladeCd || 0.5;
        const bladeCount = 4;
        for (let i = 0; i < bladeCount; i++) {
          const ang = (i / bladeCount) * TAU + t.phase * 2;
          bullets.push(new Bullet(t.x, t.y, ang, {
            dmg: t.dmg * 0.6, speed: 520, life: 0.6, pierce: 3,
            kind: 'waterKnife',
            knockback: 8,
          }));
        }
      }
    }
    // 吸附效果
    for (const e of enemies) {
      if (e.dead || e.type === 'eBullet') continue;
      const dx = t.x - e.x, dy = t.y - e.y;
      const d = Math.hypot(dx, dy);
      if (d <= t.r && d > 5) {
        const pull = t.pullForce * (1 - d / t.r * 0.5);
        e.vx = (e.vx || 0) + dx / d * pull * dt;
        e.vy = (e.vy || 0) + dy / d * pull * dt;
      }
    }
  }
  waterTornadoes = waterTornadoes.filter(t => !t.dead);
}
function updateWaves(dt) {
  for (const w of waves) {
    const dx = Math.cos(w.ang) * w.speed * dt;
    const dy = Math.sin(w.ang) * w.speed * dt;
    w.x += dx; w.y += dy;
    w.traveled += Math.hypot(dx, dy);
    if (w.traveled >= w.maxTravel) { w.dead = true; continue; }
    for (const e of enemies) {
      if (e.dead || e.type === 'eBullet') continue;
      if (w.hitSet.has(e)) continue;
      // 距离到巨浪"前沿线"的判定
      const vx = e.x - w.x, vy = e.y - w.y;
      const along = vx * Math.cos(w.ang) + vy * Math.sin(w.ang);
      const perp = -vx * Math.sin(w.ang) + vy * Math.cos(w.ang);
      if (along >= -40 && along <= w.r && Math.abs(perp) <= w.width / 2 + e.r) {
        const finalDmg = w.dmg;
        const kb = 2.4 * (w.kbMul || 1);
        const kx = Math.cos(w.ang) * kb;
        const ky = Math.sin(w.ang) * kb;
        e.hurt(finalDmg, kx, ky);
        spawnFloat(e.x, e.y - e.r, `-${Math.round(finalDmg)}`, '#7afcff');
        // 🌊 海啸附带冻结 + 眩晕
        if (w.freeze) {
          e._stun = Math.max(e._stun || 0, w.stunDur || 1);
          e._frozen = Math.max(e._frozen || 0, w.freezeDur || 1.5);
        }
        // 普通巨浪的冻结（海啸之怒升级）
        if (w.owner && w.owner.waveFreezeDur) {
          e._frozen = Math.max(e._frozen || 0, w.owner.waveFreezeDur);
        }
        w.hitSet.add(e);
      }
    }
  }
}
// —— 金·白庚：剑雨 & 终极万剑归宗 & 触发阶段 ——
function spawnSwordRain(p) {
  const camL = cam.x, camR = cam.x + W, camT = cam.y, camB = cam.y + H;
  for (let i = 0; i < 3; i++) {
    const x = rand(camL, camR);
    const y = rand(camT, camB);
    swordRains.push({
      x, y, t: 0, maxT: 0.38, dead: false,
      dmg: 45 * p.damageMul * (p.swordDamageMul || 1),
      hit: false, ang: rand(-0.4, 0.4) + Math.PI / 4,
    });
  }
}
function updateSwordRains(dt) {
  for (const s of swordRains) {
    s.t += dt;
    if (!s.hit && s.t >= 0.2) {
      s.hit = true;
      for (const e of enemies) {
        if (e.dead || e.type === 'eBullet') continue;
        if (dist2(s, e) <= (28 + e.r) * (28 + e.r)) {
          e.hurt(s.dmg, 0, -0.8);
          spawnFloat(e.x, e.y - e.r, `-${Math.round(s.dmg)}`, '#ffe58a');
        }
      }
    }
    if (s.t >= s.maxT) s.dead = true;
  }
}
function triggerSwordUltimatePhase(p) {
  // 从"剑雨阶段"进入"剑阵领域阶段"：敌人在半径内每秒巨额伤害 + 减速
  if (ultimateSwordDomain) return;
  ultimateSwordDomain = { remain: 6, radius: 260, tick: 0 };
  spawnFloat(p.x, p.y - 70, '万剑归宗！剑阵领域！', '#ffd166');
}
function triggerForestUltimateDetonate(p) {
  // 瞬间引爆所有敌人当前中毒量
  for (const e of enemies) {
    if (e.dead || e.type === 'eBullet') continue;
    if (!e.poisonStacks || e.poisonStacks.length === 0) continue;
    let total = 0;
    for (const s of e.poisonStacks) total += s.dps * s.remain;
    // 基于已损失 HP 的额外巨额伤害
    const lossDmg = (e.maxHp - e.hp) * 0.55;
    const totalDmg = total * 2 + lossDmg;
    e.hurt(totalDmg, 0, 0);
    spawnFloat(e.x, e.y - e.r, `毒爆 -${Math.round(totalDmg)}`, '#b986e5');
    for (let i = 0; i < 8; i++) addParticle(new Particle(e.x, e.y, '#b986e5'));
  }
  ultimateForest = null;
}
// —— 🔥 爆炸触发（范围伤害 + 焦土生成）——
function triggerExplosion(x, y, ex, srcBullet) {
  const r = ex.radius || 70;
  const baseDmg = (srcBullet ? srcBullet.dmg : 20) * (ex.dmgMul || 1);
  const killedByExplosion = [];
  for (const e of enemies) {
    if (e.dead || e.type === 'eBullet') continue;
    const ddx = e.x - x, ddy = e.y - y;
    if (ddx * ddx + ddy * ddy < r * r) {
      const wasAlive = e.hp > 0;
      e.hurt(baseDmg, 0, 0, { element: 'fire', source: 'fire' });
      spawnFloat(e.x, e.y - e.r, `爆炸 -${Math.round(baseDmg)}`, '#ff4500');
      if (wasAlive && e.hp <= 0) killedByExplosion.push(e);
    }
  }
  // 爆炸粒子
  for (let i = 0; i < 20; i++) addParticle(new Particle(x, y, '#ff6b35'));
  // 生成焦土
  if (ex.scorched) {
    scorchedEarth.push({
      x, y, r: r * 0.8,
      remain: ex.scorchedDur || 4,
      tick: 0,
      dps: ex.scorchedDps || 5,
    });
  }
  // 🔗 连锁爆破：爆炸击杀敌人概率触发二次爆炸
  if (player && player.fireChainExplode && !ex._fromChain) {
    const chance = player.fireChainChance || 0.3;
    const dmgMul = player.fireChainDmgMul || 0.6;
    for (const e of killedByExplosion) {
      if (Math.random() < chance) {
        const chainEx = {
          radius: r * 0.6,
          dmgMul: dmgMul,
          scorched: true,
          scorchedDur: (ex.scorchedDur || 4) * 0.5,
          scorchedDps: (ex.scorchedDps || 5) * 0.5,
          _fromChain: true,
        };
        setTimeout(() => triggerExplosion(e.x, e.y, chainEx, null), 50);
      }
    }
  }
}
// —— 火/土/风 三职业持续更新系统 ——
/* ============================================================
   ☯ Wu Xing · Wood-gives-Fire (Karma Burst)
   Full-screen fire AoE on a fire kill. Throttled by p._karmaCd.
   Kills made by the burst carry source 'karma' -> _resonanceKill,
   so they can NOT chain another burst in processEnemyDeaths.
   ============================================================ */
let karmaFlash = 0;
function triggerKarmaBurst() {
  if (!player) return;
  const p = player;
  const _K = GAME_CONFIG.tunables.karma;
  if ((p._karmaCd || 0) > 0) return;
  p._karmaCd = _K.cooldown;
  karmaFlash = _K.flash;
  const dm = p.damageMul || 1;
  const fm = p.fireBallDamageMul || 1;
  // Scales with player attack power; the x3 resonance multiplier,
  // enemy fire-weakness and armor are all applied later in dealDamage.
  const raw = (_K.base + _K.perDmgMul * dm) * fm;
  for (const e of enemies) {
    if (e.dead || e.type === 'eBullet') continue;
    let d = raw;
    const isBig = e.isBoss || e.type === 'elite' ||
      (typeof e.type === 'string' && e.type.indexOf('boss') === 0);
    if (isBig) d *= GAME_CONFIG.tunables.karma.bossMul; // bosses/elites take reduced burst damage
    e.hurt(d, 0, 0, { element: 'fire', source: 'karma' });
    addParticle(new Particle(e.x + rand(-12, 12), e.y + rand(-12, 12), '#ff6b35'));
    addParticle(new Particle(e.x + rand(-12, 12), e.y + rand(-12, 12), '#fff3b0'));
  }
  for (let i = 0; i < 30; i++) {
    addParticle(new Particle(cam.x + rand(0, W), cam.y + rand(0, H), Math.random() < 0.5 ? '#ffb347' : '#ff4500'));
  }
}
/* ============================================================
   ☯ Wu Xing · Water-conquers-Fire : freeze on hit
   Full water affinity -> player hits apply e._frozen.
   Per-target cooldown e._freezeCd prevents permanent lockdown;
   existing longer freezes (Absolute Zero card) are never shortened.
   Melt (true damage) is handled inside Enemy.hurt (Task 1).
   ============================================================ */
function applyFreeze(p, e) {
  if (!p || !e || e.dead || e.type === 'eBullet') return;
  if (!hasFullAffinity(p, 'water')) return;
  if ((e._freezeCd || 0) > 0) return;
  const _Fz = GAME_CONFIG.tunables.freeze;
  let dur = _Fz.normal;                 // normal enemy
  if (e.isBoss) dur = _Fz.boss;      // boss
  else if (e.type === 'elite') dur = _Fz.elite; // elite
  if ((e._frozen || 0) < dur) {
    e._frozen = dur;
    try {
      addParticle(new Particle(e.x, e.y, '#9fe8ff'));
      addParticle(new Particle(e.x, e.y, '#e1f7ff'));
    } catch (_) {}
  }
  e._freezeCd = _Fz.retargetCd;             // per-target re-freeze cooldown (seconds)
}
function updateNewClasses(dt) {
  if (!player) return;
  const p = player;

  // ====== 🔥 焦土区域持续灼烧 + 连锁爆破 ======
  for (let i = scorchedEarth.length - 1; i >= 0; i--) {
    const se = scorchedEarth[i];
    se.remain -= dt;
    se.tick += dt;
    if (se.remain <= 0) { scorchedEarth.splice(i, 1); continue; }
    // 每0.4秒灼烧一次
    if (se.tick >= 0.4) {
      se.tick = 0;
      for (const e of enemies) {
        if (e.dead || e.type === 'eBullet') continue;
        const ddx = e.x - se.x, ddy = e.y - se.y;
        if (ddx * ddx + ddy * ddy < se.r * se.r) {
          e.hurt(se.dps, 0, 0, { element: 'fire', source: 'fire' });
          spawnFloat(e.x, e.y - e.r, `-${Math.round(se.dps)}`, '#ff6b35');
          // 连锁爆破：焦土上的敌人死亡时再次爆炸
          if (p.fireChainExplode && e.hp <= 0 && !e._chainTriggered) {
            e._chainTriggered = true;
            scorchedEarth.push({ x: e.x, y: e.y, r: se.r * 0.8, remain: 2, tick: 0, dps: se.dps * 0.6 });
            for (let j = 0; j < 12; j++) addParticle(new Particle(e.x, e.y, '#ff6b35'));
          }
        }
      }
    }
  }

  // ====== 🔥 流星火雨：每2秒全屏随机落下陨石 ======
  if (p.fireMeteorRain) {
    p.fireMeteorCd -= dt;
    if (p.fireMeteorCd <= 0) {
      p.fireMeteorCd = 2;
      const camL = cam.x, camR = cam.x + W, camT = cam.y, camB = cam.y + H;
      for (let i = 0; i < 5; i++) {
        const mx = rand(camL + 50, camR - 50);
        const my = rand(camT + 50, camB - 50);
        bullets.push(new Bullet(mx, my - 600, Math.PI / 2, {
          dmg: 22 * p.damageMul * p.fireBallDamageMul,
          speed: 700, life: 1.2, pierce: 0,
          kind: 'meteor',
          radius: 16,
          explosion: { radius: 65, dmgMul: 1.0, scorched: true, scorchedDur: 3, scorchedDps: 5 * p.fireBallDamageMul },
        }));
      }
    }
  }

  // ====== ⛰️ 地刺/石柱持续伤害 + 阻挡 ======
  // ====== ☯ Samadhi True Fire : full-screen meteor rain (2.5s) ======
  if (p.samadhiMeteor) {
    p._samadhiCd = (p._samadhiCd || 0) - dt;
    const _Sm = GAME_CONFIG.tunables.samadhi;
    if (p._samadhiCd <= 0) {
      p._samadhiCd = _Sm.interval;
      const sd = _Sm.dmg * (p.damageMul || 1) * (p.fireBallDamageMul || 1);
      const mk = (mx, my) => bullets.push(new Bullet(mx, my - 600, Math.PI / 2, {
        dmg: sd, speed: 720, life: 1.2, pierce: 0,
        kind: 'meteor', radius: 16,
        explosion: { radius: _Sm.meteorRadius, dmgMul: 1.0, scorched: true, scorchedDur: _Sm.scorchedDur, scorchedDps: _Sm.scorchedDps * (p.fireBallDamageMul || 1) },
      }));
      // 1) rain directly onto every living enemy (capped)
      let n = 0;
      for (const e of enemies) {
        if (e.dead || e.type === 'eBullet') continue;
        mk(e.x + rand(-20, 20), e.y + rand(-20, 20));
        n++; if (n >= _Sm.targetCap) break;
      }
      // 2) grid/random points fill the whole visible area (no dead corners)
      for (let i = 0; i < _Sm.rainN; i++) mk(cam.x + rand(40, W - 40), cam.y + rand(40, H - 40));
    }
  }
  for (let i = earthSpikes.length - 1; i >= 0; i--) {
    const sp = earthSpikes[i];
    sp.remain -= dt;
    sp.tick += dt;
    if (sp.remain <= 0) { earthSpikes.splice(i, 1); continue; }
    if (!sp._hitCd) sp._hitCd = {};
    if (sp.isPillar) {
      // 石柱：持续伤害 + 阻挡敌人
      if (sp.tick >= 0.5) {
        sp.tick = 0;
        const dmg = 12 * p.damageMul * p.earthSpikeDamageMul;
        for (const e of enemies) {
          if (e.dead || e.type === 'eBullet') continue;
          const k = e.eid || e;
          if (sp._hitCd[k] > 0) continue;
          const ddx = e.x - sp.x, ddy = e.y - sp.y;
          if (ddx * ddx + ddy * ddy < (sp.r + e.r) * (sp.r + e.r)) {
            e.hurt(dmg, 0, 0);
            sp._hitCd[k] = 0.5;
            spawnFloat(e.x, e.y - e.r, `-${Math.round(dmg)}`, '#d4a373');
          }
        }
        for (const k in sp._hitCd) sp._hitCd[k] -= 0.5;
      }
      // 阻挡：把石柱重叠的敌人推开
      for (const e of enemies) {
        if (e.dead || e.type === 'eBullet') continue;
        const ddx = e.x - sp.x, ddy = e.y - sp.y;
        const d = Math.hypot(ddx, ddy);
        const minD = sp.r + e.r;
        if (d < minD && d > 0) {
          const push = (minD - d) / d;
          e.x += ddx * push; e.y += ddy * push;
        }
      }
    } else if (sp.tickDmg > 0) {
      // ⚔️ 普通地刺：原地持续伤害区（每tickInterval秒造成一次伤害）
      if (sp.tick >= (sp.tickInterval || 0.4)) {
        sp.tick = 0;
        for (const e of enemies) {
          if (e.dead || e.type === 'eBullet') continue;
          const k = e.eid || e;
          if (sp._hitCd[k] > 0) continue;
          const ddx = e.x - sp.x, ddy = e.y - sp.y;
          if (ddx * ddx + ddy * ddy < (sp.r + e.r) * (sp.r + e.r)) {
            e.hurt(sp.tickDmg, 0, 0);
            sp._hitCd[k] = (sp.tickInterval || 0.4);
            spawnFloat(e.x, e.y - e.r, `-${Math.round(sp.tickDmg)}`, '#a0826d');
          }
        }
        for (const k in sp._hitCd) sp._hitCd[k] -= (sp.tickInterval || 0.4);
      }
    }
  }

  // ====== 🌪️ 风刃手里剑状态机：outbound→return + 穿透碰撞 + 真空聚怪 ======
  for (let i = windBlades.length - 1; i >= 0; i--) {
    const wb = windBlades[i];
    wb.t += dt / wb.dur;
    if (wb.t >= 1) {
      if (wb.phase === 'outbound') {
        wb.phase = 'return'; wb.t = 0;
        wb.ox = wb.tx; wb.oy = wb.ty;
        wb.tx = p.x; wb.ty = p.y;
        wb.hitSet.clear();
      } else {
        windBlades.splice(i, 1); continue;
      }
    }
    const tt = Math.max(0, Math.min(1, wb.t));
    const eT = tt * tt * (3 - 2 * tt);
    wb._x = wb.ox + (wb.tx - wb.ox) * eT;
    wb._y = wb.oy + (wb.ty - wb.oy) * eT;
    // 扩大攻击范围（🌀 P0：windRadius 词条半径增量，基线 70 → 基础 14）
    const radiusMul = Math.max(0.5, (p.windRadius || 70) / 70);
    const curR = 14 * radiusMul * (1 + (wb.phase === 'outbound' ? eT * (wb.expand - 1) : 0));
    // 碰撞（🌀 P0：windDmgMul / 疾风追猎击杀增伤 / 击退 / 减速 / 流血 / 连斩）
    const dmg = 16 * p.damageMul * p.windBladeDamageMul * (p.windDmgMul || 1) * p.windAtkSpeed * (p._windKillMul || 1);
    const kbForce = 0.5 * (p.windKnockbackMul || 1) * (p.windKnockback || 1);
    for (const e of enemies) {
      if (e.dead || e.type === 'eBullet') continue;
      const k = e.eid || e;
      if (wb.hitSet.has(k)) continue;
      const ddx = e.x - wb._x, ddy = e.y - wb._y;
      if (ddx * ddx + ddy * ddy < (curR + e.r) * (curR + e.r)) {
        wb.hitSet.add(k);
        const hbAng = Math.atan2(ddy, ddx);
        e.hurt(dmg, Math.cos(hbAng) * kbForce, Math.sin(hbAng) * kbForce);
        spawnFloat(e.x, e.y - e.r, `-${Math.round(dmg)}`, '#48cae4');
        for (let j = 0; j < 3; j++) addParticle(new Particle(wb._x, wb._y, '#b8f2e6'));
        // 💨 疾风退敌 / 疾风击退：命中减速
        if (p.windSlow > 0) applySlow(e, 1 - p.windSlow, 1.0);
        // 🩸 风刃切割（100% 流血）/ 刃舞（概率流血 + 减速 + 易伤）
        if (p.windBleed) {
          const bleedPct = p.windBleedDmg != null ? p.windBleedDmg : (p.windBleedDps != null ? p.windBleedDps : 0.2);
          if (p.windBleedChance > 0) {
            if (Math.random() < p.windBleedChance) applyBleed(e, dmg * bleedPct, p.windBleedDur || 3, p.windBleedSlow, p.windBleedVuln);
          } else {
            applyBleed(e, dmg * bleedPct, p.windBleedDur || 3, p.windBleedSlow || 0, p.windBleedVuln || 0);
          }
        }
        // ⚡ 疾风连斩：命中后概率弹射到附近另一个敌人
        if (p.windChain && wb.chainUsed < (p.windChainMax || 3) && Math.random() < (p.windChainChance || 0.3)) {
          let best = null, bestD = 320 * 320;
          for (const e2 of enemies) {
            if (e2.dead || e2.type === 'eBullet' || e2 === e || wb.hitSet.has(e2.eid || e2)) continue;
            const dd = dist2(e, e2);
            if (dd < bestD) { bestD = dd; best = e2; }
          }
          if (best) {
            wb.chainUsed++;
            const falloff = Math.pow(p.windChainFalloff != null ? p.windChainFalloff : 0.9, wb.chainUsed);
            const chainDmg = dmg * falloff;
            best.hurt(chainDmg, 0, 0);
            spawnFloat(best.x, best.y - best.r, `⚡-${Math.round(chainDmg)}`, '#82e9ff');
            windChainFx.push({ x1: e.x, y1: e.y, x2: best.x, y2: best.y, t: 0.18, max: 0.18 });
          }
        }
        // 真空领域：风刃路径两侧敌人吸入路径中心
        if (p.windVacuum) {
          const pullAng = Math.atan2(wb.ty - wb.oy, wb.tx - wb.ox);
          const pullPower = 160 * (p.windVacuumPower || 1);
          const pullR = 150 * (p.windVacuumPower || 1);
          for (const e2 of enemies) {
            if (e2.dead || e2.type === 'eBullet' || e2 === e) continue;
            const vx = wb._x - e2.x, vy = wb._y - e2.y;
            const dist = Math.hypot(vx, vy);
            if (dist < pullR) {
              e2.vx = (e2.vx || 0) + (vx / dist) * pullPower;
              e2.vy = (e2.vy || 0) + (vy / dist) * pullPower;
              e2.vx = Math.max(-300, Math.min(300, e2.vx));
              e2.vy = Math.max(-300, Math.min(300, e2.vy));
            }
          }
        }
      }
    }
  }

  // ====== 🌀 风刃手里剑：击杀攻速叠加（最高100层），每秒自然衰减1层 ======
  if (p.windBladeActive && p.windAtkStacks > 0) {
    p._windStackDecay = (p._windStackDecay || 0) + dt;
    if (p._windStackDecay >= 1) {
      p._windStackDecay = 0;
      p.windAtkStacks = Math.max(0, p.windAtkStacks - 1);
    }
    p.windAtkSpeed = 1 + p.windAtkStacks * 0.01;
  }
  // ====== 🌀 疾风追猎：击杀叠加风刃伤害（限时层数，每杀 1 敌人 +5%）======
  if (p.windBladeActive && p.windKillStack) {
    const now = timeElapsed;
    p._windKillExp = (p._windKillExp || []).filter(t => t > now);
    p._windKillMul = 1 + p._windKillExp.length * (p.windKillStackDmg || 0.05);
  } else {
    p._windKillMul = 1;
  }
  // ⚡ 疾风连斩闪电轨迹衰减
  for (let i = windChainFx.length - 1; i >= 0; i--) {
    windChainFx[i].t -= dt;
    if (windChainFx[i].t <= 0) windChainFx.splice(i, 1);
  }

  // ====== ⛰️ 不动明王：泰山压顶每3秒 ======
  if (p.earthUltimateOn) {
    p.earthStompCd -= dt;
    if (p.earthStompCd <= 0) {
      p.earthStompCd = p.earthStompInterval;
      // 震晕全屏 + 斩杀当前生命15%
      for (const e of enemies) {
        if (e.dead || e.type === 'eBullet') continue;
        e._stun = Math.max(e._stun || 0, 1.2);
        const dmg = e.hp * 0.15;
        e.hurt(dmg, 0, 0);
        spawnFloat(e.x, e.y - e.r, `泰山 -${Math.round(dmg)}`, '#d4a373');
      }
      for (let j = 0; j < 30; j++) addParticle(new Particle(p.x, p.y, '#d4a373'));
      spawnFloat(p.x, p.y - 60, '泰山压顶！', '#d4a373');
    }
  }

  // ============================================================
  // 🌀 P0：风刃手里剑 · 周期机制（风刃乱舞 / 风暴领域 / 龙卷风 / 真空黑洞 / 风之壁垒 / 万风朝宗 / 寂静之殇）
  // ============================================================
  if (p.equippedWeapon === 'wind_blade' && p.windBladeActive) {
    const windBaseDmg = 16 * p.damageMul * p.windBladeDamageMul * (p.windDmgMul || 1) * p.windAtkSpeed * (p._windKillMul || 1);
    // 🌀 风刃乱舞：周身环形发射
    if (p.windBladeStorm) {
      p._wBladeStormT = (p._wBladeStormT || 0) - dt;
      if (p._wBladeStormT <= 0) {
        p._wBladeStormT = p.windBladeStormCd || 12;
        const n = p.windBladeStormCount || 12;
        const dur = 0.55 / Math.max(0.3, p.windBladeSpeedMul || 1);
        for (let i = 0; i < n; i++) {
          const a = (i / n) * TAU;
          windBlades.push({
            ox: p.x, oy: p.y,
            tx: p.x + Math.cos(a) * (W * 0.6), ty: p.y + Math.sin(a) * (W * 0.6),
            t: 0, dur, phase: 'outbound', expand: p.windBladeExpand,
            hitSet: new Set(), chainUsed: 0, _x: p.x, _y: p.y,
          });
        }
        spawnFloat(p.x, p.y - 60, '风刃乱舞！', '#7fe8ff');
      }
    }
    // 🌪️ 风暴领域：周身持续伤害 + 减速（每 0.5 秒一跳）
    if (p.windStorm && p.windStormDps > 0) {
      p._wStormT = (p._wStormT || 0) - dt;
      if (p._wStormT <= 0) {
        p._wStormT = 0.5;
        const R = p.windStormR || 120;
        const tickDmg = p.windStormDps * p.damageMul * 0.5;
        for (const e of enemies) {
          if (e.dead || e.type === 'eBullet') continue;
          const ddx = e.x - p.x, ddy = e.y - p.y;
          if (ddx * ddx + ddy * ddy <= R * R) {
            e.hurt(tickDmg, 0, 0);
            if (p.windStormSlow > 0) applySlow(e, 1 - p.windStormSlow, 0.6);
          }
        }
      }
    }
    // 🌀 龙卷风暴：周期释放追踪龙卷风
    if (p.windTornado) {
      p._wTornadoT = (p._wTornadoT == null ? p.windTornadoCd : p._wTornadoT) - dt;
      if (p._wTornadoT <= 0) {
        p._wTornadoT = p.windTornadoCd || 15;
        windTornadoes.push({ x: p.x, y: p.y, vx: 0, vy: 0, t: 0, dur: p.windTornadoDur || 4, r: 46,
          dmg: windBaseDmg * 0.8, tickTimer: 0, phase: Math.random() * TAU, pullForce: 220, moveSpeed: 70, type: 'seek' });
        spawnFloat(p.x, p.y - 60, '龙卷风暴！', '#7fe8ff');
      }
    }
    // 🌪️ 万风朝宗：周期召唤 3 个环绕巨型龙卷风
    if (p.bossWindTornado) {
      p._bwTornadoT = (p._bwTornadoT == null ? p.bossWindTornadoCd : p._bwTornadoT) - dt;
      if (p._bwTornadoT <= 0) {
        p._bwTornadoT = p.bossWindTornadoCd || 12;
        const n = p.bossWindTornadoCount || 3, dur = p.bossWindTornadoDur || 8;
        for (let i = 0; i < n; i++) {
          windTornadoes.push({ x: p.x, y: p.y, vx: 0, vy: 0, t: 0, dur, r: 60,
            dmg: windBaseDmg, tickTimer: 0, phase: (i / n) * TAU, pullForce: 300, orbitAng: (i / n) * TAU, orbitR: 110, type: 'orbit' });
        }
        spawnFloat(p.x, p.y - 70, '万风朝宗！', '#b8f2e6');
      }
    }
    // 🕳️ 真空黑洞：周期在最近敌人处生成引力场
    if (p.bossWindVacuum) {
      p._bwvT = (p._bwvT == null ? p.bossWindVacuumCd : p._bwvT) - dt;
      if (p._bwvT <= 0) {
        const tgt = nearestEnemy(p);
        if (tgt) {
          p._bwvT = p.bossWindVacuumCd || 10;
          windVortexes.push({ x: tgt.x, y: tgt.y, t: 0, dur: p.bossWindVacuumDur || 3, r: p.bossWindVacuumR || 150,
            tickTimer: 0, dmg: windBaseDmg * 0.5, pull: 320 });
          spawnFloat(p.x, p.y - 60, '真空黑洞！', '#9fa8da');
        }
      }
    }
    // 💨 风之壁垒：弹开弹幕 + 近身持续伤害/减速
    if (p.bossWindBarrier) {
      const R = p.bossWindBarrierR || 100;
      for (let i = enemies.length - 1; i >= 0; i--) {
        const eb = enemies[i];
        if (eb.type !== 'eBullet' || eb.dead) continue;
        const ddx = eb.x - p.x, ddy = eb.y - p.y;
        if (ddx * ddx + ddy * ddy <= R * R && Math.random() < (p.bossWindBarrierBlock || 0.6)) {
          enemies.splice(i, 1);
          for (let j = 0; j < 4; j++) addParticle(new Particle(eb.x, eb.y, '#b8f2e6'));
        }
      }
      p._bwbT = (p._bwbT || 0) - dt;
      if (p._bwbT <= 0) {
        p._bwbT = 0.4;
        for (const e of enemies) {
          if (e.dead || e.type === 'eBullet') continue;
          const ddx = e.x - p.x, ddy = e.y - p.y;
          if (ddx * ddx + ddy * ddy <= R * R) {
            e.hurt((p.bossWindBarrierDps || 25) * p.damageMul * 0.4, 0, 0);
            applySlow(e, 1 - (p.bossWindBarrierSlow || 0.3), 0.5);
          }
        }
      }
    }
    // 🌀 寂静之殇：全屏切割 + 沉默
    if (p.bossWindSilence) {
      p._bwsT = (p._bwsT == null ? p.bossWindSilenceCd : p._bwsT) - dt;
      if (p._bwsT <= 0) {
        p._bwsT = p.bossWindSilenceCd || 15;
        const dmg = windBaseDmg * (p.bossWindSilenceDmg || 4);
        const camL = cam.x, camR = cam.x + W, camT = cam.y, camB = cam.y + H;
        for (const e of enemies) {
          if (e.dead || e.type === 'eBullet') continue;
          if (e.x < camL || e.x > camR || e.y < camT || e.y > camB) continue;
          e.hurt(dmg, 0, 0);
          e._silenced = Math.max(e._silenced || 0, p.bossWindSilenceDur || 3);
          spawnFloat(e.x, e.y - e.r, `寂静 -${Math.round(dmg)}`, '#80deea');
        }
        spawnFloat(p.x, p.y - 70, '寂静之殇！', '#80deea');
        for (let j = 0; j < 40; j++) addParticle(new Particle(p.x + rand(-W/2, W/2), p.y + rand(-H/2, H/2), '#b2ebf2'));
      }
    }
  }

  // ============================================================
  // ✨ P0：圣光法典 · 周期机制（圣盾光壁计时 / 圣光护盾 / 神圣审判 / 神罚）
  // ============================================================
  if (p.equippedWeapon === 'holy_nova' && p.novaActive) {
    const novaBaseDmg = 16 * p.damageMul * p.novaDmgMul * (p.novaDamageMul || 1);
    // 🔰 圣盾光壁剩余时间
    if (p._novaWallT > 0) p._novaWallT -= dt;
    // 🔰 圣光护盾：周期获得，吸收上限内伤害
    if (p.bossLightShield) {
      if (p._bossLightShield <= 0) {
        p._blsT = (p._blsT == null ? p.bossLightShieldCd : p._blsT) - dt;
        if (p._blsT <= 0) {
          p._blsT = p.bossLightShieldCd || 12;
          p._bossLightShield = p.maxHp * (p.bossLightShieldHp || 0.35);
          spawnFloat(p.x, p.y - 60, '圣光护盾!', '#fff59d');
        }
      }
    }
    // ☀️ 神圣审判：6 道圣光柱随机落在敌人附近
    if (p.bossLightJudgment) {
      p._bljT = (p._bljT == null ? p.bossLightJudgmentCd : p._bljT) - dt;
      if (p._bljT <= 0) {
        p._bljT = p.bossLightJudgmentCd || 10;
        const count = p.bossLightJudgmentCount || 6;
        for (let i = 0; i < count; i++) {
          const idx = Math.floor(Math.random() * Math.min(enemies.length, 60));
          const e = enemies[idx];
          if (!e || e.dead || e.type === 'eBullet') continue;
          const x = e.x + rand(-50, 50), y = e.y + rand(-50, 50);
          let dmg = novaBaseDmg * (p.bossLightJudgmentDmg || 3);
          setTimeout((xx, yy, dd) => {
            if (!player || player.dead) return;
            for (const en of enemies) {
              if (en.dead || en.type === 'eBullet') continue;
              const ddx = en.x - xx, ddy = en.y - yy;
              if (ddx * ddx + ddy * ddy <= 80 * 80) {
                let pd = dd;
                if ((en.isBoss || en.type === 'elite') && player.bossLightJudgmentBossBonus) pd *= 1 + player.bossLightJudgmentBossBonus;
                en.hurt(pd, 0, 0);
                en._stun = Math.max(en._stun || 0, 0.8);
                spawnFloat(en.x, en.y - en.r, `☀️-${Math.round(pd)}`, '#fff176');
              }
            }
            slashJudgmentFx.push({ x: xx, y: yy, t: 0.5, max: 0.5 });
          }, i * 120, x, y, dmg);
        }
        spawnFloat(p.x, p.y - 70, '神圣审判！', '#fff176');
      }
    }
    // ⚡ 神罚：锁定血量最高敌人
    if (p.bossLightSmite) {
      p._blsmT = (p._blsmT == null ? p.bossLightSmiteCd : p._blsmT) - dt;
      if (p._blsmT <= 0) {
        let tgt = null;
        for (const e of enemies) {
          if (e.dead || e.type === 'eBullet') continue;
          if (!tgt || e.hp > tgt.hp) tgt = e;
        }
        if (tgt) {
          p._blsmT = p.bossLightSmiteCd || 8;
          const dmg = novaBaseDmg * (p.bossLightSmiteDmg || 8);
          tgt.hurt(dmg, 0, 0);
          tgt._stun = Math.max(tgt._stun || 0, p.bossLightSmiteStun || 3);
          slashJudgmentFx.push({ x: tgt.x, y: tgt.y, t: 0.7, max: 0.7 });
          spawnFloat(tgt.x, tgt.y - tgt.r - 20, `神罚 -${Math.round(dmg)}`, '#ffe082');
          for (let j = 0; j < 20; j++) addParticle(new Particle(tgt.x, tgt.y, '#fff59d'));
        }
      }
    }
  }

  // ============================================================
  // 🛡️ P0：圣盾巨剑 · 周期机制（旋风斩 / 连突刺 / 审判之剑 / 神圣裁决 / 圣盾守护充能）
  // ============================================================
  if (p.equippedWeapon === 'holy_shield' && p.slashActive) {
    const slashBaseDmg = 24 * p.damageMul * p.slashDmgMul * (p._aegisDmgMul || 1);
    // 圣盾增益计时
    if (p._aegisBuffT > 0) { p._aegisBuffT -= dt; if (p._aegisBuffT <= 0) p._aegisDmgMul = 1; }
    // 🛡️ 圣盾守护 / 神圣圣盾：周期性充能（抵挡一次致命伤害，由 damage() 消耗）
    if (p.slashAegis) {
      if (!p._slashAegisReady) {
        p._slashAegisT = (p._slashAegisT == null ? p.slashAegisCd : p._slashAegisT) - dt;
        if (p._slashAegisT <= 0) { p._slashAegisReady = true; p._slashAegisT = p.slashAegisCd || 15; }
      }
    }
    if (p.bossKnightAegis) {
      if (!p._bossAegisReady) {
        p._bossAegisT = (p._bossAegisT == null ? p.bossKnightAegisCd : p._bossAegisT) - dt;
        if (p._bossAegisT <= 0) { p._bossAegisReady = true; p._bossAegisT = p.bossKnightAegisCd || 10; }
      }
    }
    // 🌀 旋风斩：360° 范围挥砍
    if (p.slashWhirlwind) {
      p._swwT = (p._swwT == null ? p.slashWhirlwindCd : p._swwT) - dt;
      if (p._swwT <= 0) {
        p._swwT = p.slashWhirlwindCd || 8;
        const R = p.slashRadius * (1 + (p.slashWhirlwindR || 0.6));
        let hitN = 0;
        for (const e of enemies) {
          if (e.dead || e.type === 'eBullet') continue;
          const ddx = e.x - p.x, ddy = e.y - p.y;
          if (ddx * ddx + ddy * ddy <= (R + e.r) * (R + e.r)) {
            p._slashApplyHit(e, slashBaseDmg, Math.atan2(ddy, ddx), 1.2, false);
            hitN++;
          }
        }
        slashFx.push({ x: p.x, y: p.y, ang: 0, t: 0.6, max: 0.6, r: R, full: true, halfAng: Math.PI,
          follow: p, dmg: 0, hitSet: new Set(), tickT: 0.1, slash360: true, fire: false, visualOnly: true });
        if (p.slashWhirlwindHeal > 0 && hitN > 0) p.hp = Math.min(p.maxHp, p.hp + p.maxHp * p.slashWhirlwindHeal * Math.min(10, hitN));
        spawnFloat(p.x, p.y - 60, '旋风斩！', '#d7dce8');
      }
    }
    // ⚡ 连突刺：连续对最近敌人造成 150% 伤害
    if (p.slashCharge) {
      p._scT = (p._scT == null ? p.slashChargeCd : p._scT) - dt;
      if (p._scT <= 0) {
        p._scT = p.slashChargeCd || 7;
        let origin = p, used = new Set();
        for (let c = 0; c < (p.slashChargeCount || 3); c++) {
          let best = null, bestD = 380 * 380;
          for (const e of enemies) {
            if (e.dead || e.type === 'eBullet' || used.has(e)) continue;
            const dd = dist2(origin, e);
            if (dd < bestD) { bestD = dd; best = e; }
          }
          if (!best) break;
          used.add(best); origin = best;
          const ang = Math.atan2(best.y - p.y, best.x - p.x);
          p._slashApplyHit(best, slashBaseDmg * (p.slashChargeDmg || 1.5), ang, 1.5, false);
          slashFx.push({ x: best.x, y: best.y, ang, t: 0.25, max: 0.25, r: 60, full: false, halfAng: 1.0,
            follow: null, dmg: 0, hitSet: new Set(), tickT: 0.1, slash360: false, fire: false, visualOnly: true });
          for (let j = 0; j < 8; j++) addParticle(new Particle(best.x, best.y, '#ffe082'));
        }
        if (used.size > 0) spawnFloat(p.x, p.y - 60, '连突刺！', '#ffe082');
      }
    }
    // ☀️ 审判之剑 / ⚡ 神圣裁决：天降光剑
    const judgmentCfg = p.bossKnightJudgment
      ? { on: true, cd: p.bossKnightJudgmentCd, dmgMul: p.bossKnightJudgmentDmg, stun: p.bossKnightJudgmentStun, t: '_bkjT', label: '神圣裁决！', color: '#fff176' }
      : p.slashJudgment
      ? { on: true, cd: p.slashJudgmentCd, dmgMul: p.slashJudgmentDmg, stun: p.slashJudgmentStun, t: '_sjT', label: '审判之剑！', color: '#ffe082' }
      : null;
    if (judgmentCfg) {
      p[judgmentCfg.t] = (p[judgmentCfg.t] == null ? judgmentCfg.cd : p[judgmentCfg.t]) - dt;
      if (p[judgmentCfg.t] <= 0) {
        const tgt = nearestEnemy(p);
        if (tgt) {
          p[judgmentCfg.t] = judgmentCfg.cd || 12;
          const dmg = slashBaseDmg * (judgmentCfg.dmgMul || 4);
          const R = 70;
          for (const e of enemies) {
            if (e.dead || e.type === 'eBullet') continue;
            const ddx = e.x - tgt.x, ddy = e.y - tgt.y;
            if (ddx * ddx + ddy * ddy <= (R + e.r) * (R + e.r)) {
              e.hurt(dmg, 0, 0);
              e._stun = Math.max(e._stun || 0, judgmentCfg.stun || 1.5);
              spawnFloat(e.x, e.y - e.r, `☄️-${Math.round(dmg)}`, judgmentCfg.color);
            }
          }
          slashJudgmentFx.push({ x: tgt.x, y: tgt.y, t: 0.5, max: 0.5 });
          spawnFloat(tgt.x, tgt.y - 60, judgmentCfg.label, judgmentCfg.color);
        }
      }
    }
  }
}

// 🌀 P0：风刃龙卷风更新（seek=追踪最近敌人；orbit=环绕玩家）——吸附 + 高频切割
function updateWindTornadoes(dt) {
  for (let i = windTornadoes.length - 1; i >= 0; i--) {
    const t = windTornadoes[i];
    t.t += dt;
    if (t.t >= t.dur) { windTornadoes.splice(i, 1); continue; }
    t.phase += dt * 6;
    if (t.type === 'orbit' && player) {
      t.orbitAng += dt * 1.6;
      const tx = player.x + Math.cos(t.orbitAng) * t.orbitR;
      const ty = player.y + Math.sin(t.orbitAng) * t.orbitR;
      t.vx = (tx - t.x) * 6; t.vy = (ty - t.y) * 6;
    } else {
      let nearest = null, nd = 9999;
      for (const e of enemies) {
        if (e.dead || e.type === 'eBullet') continue;
        const d = Math.hypot(e.x - t.x, e.y - t.y);
        if (d < nd) { nd = d; nearest = e; }
      }
      if (nearest && nd > 20) {
        const ang = Math.atan2(nearest.y - t.y, nearest.x - t.x);
        t.vx += Math.cos(ang) * 120 * dt; t.vy += Math.sin(ang) * 120 * dt;
      }
      const sp = Math.hypot(t.vx, t.vy);
      if (sp > (t.moveSpeed || 70)) { t.vx = t.vx / sp * (t.moveSpeed || 70); t.vy = t.vy / sp * (t.moveSpeed || 70); }
      t.vx *= 0.96; t.vy *= 0.96;
    }
    t.x += t.vx * dt; t.y += t.vy * dt;
    t.tickTimer -= dt;
    if (t.tickTimer <= 0) {
      t.tickTimer = 0.25;
      for (const e of enemies) {
        if (e.dead || e.type === 'eBullet') continue;
        if (Math.hypot(e.x - t.x, e.y - t.y) <= t.r) {
          e.hurt(t.dmg, 0, 0);
          applySlow(e, 0.7, 0.3);
        }
      }
    }
    for (const e of enemies) {
      if (e.dead || e.type === 'eBullet') continue;
      const dx = t.x - e.x, dy = t.y - e.y, d = Math.hypot(dx, dy);
      if (d <= t.r * 2.2 && d > 5) {
        e.vx = (e.vx || 0) + dx / d * t.pullForce * dt;
        e.vy = (e.vy || 0) + dy / d * t.pullForce * dt;
      }
    }
  }
}
// 🕳️ P0：真空黑洞更新——持续吸入 + 范围切割
function updateWindVortexes(dt) {
  for (let i = windVortexes.length - 1; i >= 0; i--) {
    const v = windVortexes[i];
    v.t += dt;
    if (v.t >= v.dur) { windVortexes.splice(i, 1); continue; }
    for (const e of enemies) {
      if (e.dead || e.type === 'eBullet') continue;
      const dx = v.x - e.x, dy = v.y - e.y, d = Math.hypot(dx, dy);
      if (d <= v.r && d > 4) {
        e.vx = (e.vx || 0) + dx / d * v.pull * dt;
        e.vy = (e.vy || 0) + dy / d * v.pull * dt;
        applySlow(e, 0.6, 0.3);
      }
    }
    v.tickTimer -= dt;
    if (v.tickTimer <= 0) {
      v.tickTimer = 0.3;
      for (const e of enemies) {
        if (e.dead || e.type === 'eBullet') continue;
        if (Math.hypot(e.x - v.x, e.y - v.y) <= v.r * 0.55) {
          e.hurt(v.dmg, 0, 0);
        }
      }
    }
  }
}
// —— 终极持续更新 & 深海高压（水龙卷：护体 AoE + 弹开敌弹）——
function updateUltimates(dt) {
  if (!player) return;
  const p = player;
  // —— 万剑归宗·被动触发：场上存活敌人 > 50 时自动激活剑阵领域（⚠️ 排除死敌人和敌弹）——
  const aliveEnemyCount = enemies.filter(e => !e.dead && e.type !== 'eBullet').length;
  if (p.swordUltimatePassive && !ultimateSwordDomain && aliveEnemyCount > 50) {
    ultimateSwordDomain = { remain: 8, radius: 300, tick: 0 };
    spawnFloat(p.x, p.y - 80, '万剑归宗！剑阵领域！', '#ffd166');
    // 生成开场爆发粒子
    for (let i = 0; i < 30; i++) addParticle(new Particle(p.x, p.y, '#ffd166'));
    // 飞剑合体：所有飞剑收拢到角色头顶形成剑阵
    for (const sw of p.swords) {
      sw.phase = 'orbit';
      sw.orbitCd = 999;  // 暂时停止突刺
    }
  }
  if (ultimateSwordDomain) {
    ultimateSwordDomain.remain -= dt;
    ultimateSwordDomain.tick += dt;
    // 全屏剑雨：每秒约 8 次，每次 3 枚（共约24枚/秒，兼顾视觉与性能）
    if (Math.random() < dt * 8) spawnSwordRain(p);
    if (ultimateSwordDomain.tick >= 0.3) {
      ultimateSwordDomain.tick = 0;
      const r = ultimateSwordDomain.radius;
      for (const e of enemies) {
        if (e.dead || e.type === 'eBullet') continue;
        const dx = e.x - p.x, dy = e.y - p.y;
        if (dx * dx + dy * dy <= r * r) {
          const dmg = 85 * p.damageMul * (p.swordDamageMul || 1);
          e.hurt(dmg, 0, 0);
          applySlow(e, 0.45, 0.4);
          spawnFloat(e.x, e.y - e.r, `-${Math.round(dmg)}`, '#ffd166');
        }
      }
    }
    if (ultimateSwordDomain.remain <= 0) {
      ultimateSwordDomain = null;
      // 恢复飞剑突刺
      for (const sw of p.swords) { sw.orbitCd = 0.5; }
      spawnFloat(p.x, p.y - 80, '剑阵消散', '#ffd166');
    }
  }
  // —— 剑气尾迹：万剑归宗期间玩家移动拖出尾迹，触碰即死（精英怪巨额伤害）——
  if (p.swordUltimatePassive && ultimateSwordDomain) {
    // 每帧生成尾迹点
    swordTrails.push({ x: p.x, y: p.y, life: 1.2, maxLife: 1.2, hitSet: new Set() });
    if (swordTrails.length > 60) swordTrails.shift();
  }
  for (let i = swordTrails.length - 1; i >= 0; i--) {
    const tr = swordTrails[i];
    tr.life -= dt;
    if (tr.life <= 0) { swordTrails.splice(i, 1); continue; }
    // 尾迹伤害判定
    for (const e of enemies) {
      if (e.dead || e.type === 'eBullet') continue;
      const cdK = e.eid || e;
      if (tr.hitSet.has(cdK)) continue;
      const dx = tr.x - e.x, dy = tr.y - e.y;
      if (dx * dx + dy * dy < (30 + e.r) * (30 + e.r)) {
        tr.hitSet.add(cdK);
        // 触碰即死：普通怪直接秒杀，精英/BOSS 巨额伤害
        if (e.isElite || e.isBoss) {
          const dmg = e.maxHp * 0.35;
          e.hurt(dmg, 0, 0);
          spawnFloat(e.x, e.y - e.r, `剑气 -${Math.round(dmg)}`, '#fff1a8');
        } else {
          e.hurt(e.hp, 0, 0);  // 秒杀
          spawnFloat(e.x, e.y - e.r, '剑气秒杀!', '#fff1a8');
        }
        for (let j = 0; j < 4; j++) addParticle(new Particle(e.x, e.y, '#fff1a8'));
      }
    }
  }
  if (ultimateForest) {
    ultimateForest.remain -= dt;
    ultimateForest.tick += dt;
    if (ultimateForest.tick >= 1) {
      ultimateForest.tick = 0;
      // 全屏毒雾：每 1s 对所有敌人上毒
      for (const e of enemies) {
        if (e.dead || e.type === 'eBullet') continue;
        applyPoison(e, 12 * p.damageMul * (p.poisonDmgMul || 1), 5);
        applySlow(e, 0.7, 0.6);
      }
    }
    if (ultimateForest.remain <= 0) ultimateForest = null;
  }
  if (p.waterUltimateOn || ultimateWater) {
    if (!ultimateWater) ultimateWater = { remain: 8, tick: 0 };
    ultimateWater.remain -= dt;
    ultimateWater.tick += dt;
    if (ultimateWater.tick >= 0.25) {
      ultimateWater.tick = 0;
      const R = 180;
      for (const e of enemies) {
        if (e.dead || e.type === 'eBullet') continue;
        const dx = e.x - p.x, dy = e.y - p.y;
        if (dx * dx + dy * dy <= R * R) {
          const dmg = 55 * p.damageMul;
          const ang = Math.atan2(dy, dx);
          e.hurt(dmg, Math.cos(ang) * 0.3, Math.sin(ang) * 0.3);
        }
      }
      // 深海高压：弹开所有敌弹（enemyBullets 兼容旧字段）
      for (let i = enemies.length - 1; i >= 0; i--) {
        const eb = enemies[i];
        if (eb.type !== 'eBullet') continue;
        const dx = eb.x - p.x, dy = eb.y - p.y;
        if (dx * dx + dy * dy <= R * R) {
          enemies.splice(i, 1);
        }
      }
      if (p.waterUltimateTimer !== undefined && p.waterUltimateTimer <= 0) {
        p.waterUltimateTimer = 0.001;
      }
    }
    if (ultimateWater.remain <= 0) {
      ultimateWater = null;
    }
  }
  // ====== 🔥 红莲业火：全屏岩浆 + 火焰尾迹 + 防御归零 + 燃烧叠加 ======
  if (ultimateLava) {
    ultimateLava.remain -= dt;
    ultimateLava.tick += dt;
    // 每帧生成火焰尾迹
    scorchedEarth.push({ x: p.x, y: p.y, r: 50, remain: 1.5, tick: 0, dps: 12 * p.fireBallDamageMul });
    if (scorchedEarth.length > 80) scorchedEarth.splice(0, scorchedEarth.length - 80);
    // 每0.5秒全屏岩浆伤害
    if (ultimateLava.tick >= 0.5) {
      ultimateLava.tick = 0;
      for (const e of enemies) {
        if (e.dead || e.type === 'eBullet') continue;
        const dmg = 25 * p.fireBallDamageMul;
        e.hurt(dmg, 0, 0, { element: 'fire', source: 'fire' });
        // 防御归零标记 + 燃烧叠加
        e._armorZero = true;
        e._burnStacks = (e._burnStacks || 0) + 1;
        e.hp -= 3 * e._burnStacks;
        spawnFloat(e.x, e.y - e.r, `-${Math.round(dmg)}`, '#ff2200');
      }
    }
    if (ultimateLava.remain <= 0) {
      ultimateLava = null;
      p.fireUltimateOn = false;
      spawnFloat(p.x, p.y - 60, '红莲业火消散', '#ff6b35');
    }
  }

  // ====== ⭐ 彗星飞剑：周期发射穿透巨剑 + 爆炸 ======
  if (p.cometSwordInterval) {
    p.cometSwordCd = (p.cometSwordCd || 0) + dt;
    if (p.cometSwordCd >= p.cometSwordInterval) {
      p.cometSwordCd = 0;
      // 找最近敌人
      let target = null, minD = Infinity;
      for (const e of enemies) {
        if (e.dead || e.type === 'eBullet') continue;
        const d = dist2(e, p);
        if (d < minD) { minD = d; target = e; }
      }
      if (target) {
        const ang = Math.atan2(target.y - p.y, target.x - p.x);
        cometSwords.push({
          x: p.x, y: p.y, vx: Math.cos(ang) * 600, vy: Math.sin(ang) * 600,
          dmg: (p.cometSwordDmg || 400) * p.damageMul,
          pierce: p.cometSwordPierce || 5,
          blastR: p.cometSwordBlastR || 80,
          hitSet: new Set(),
          ang: ang, t: 0, dead: false,
          trail: [],
        });
        spawnFloat(p.x, p.y - 40, '彗星飞剑!', '#ffd166');
      }
    }
  }
  // 更新彗星飞剑
  for (let i = cometSwords.length - 1; i >= 0; i--) {
    const cs = cometSwords[i];
    cs.t += dt;
    cs.x += cs.vx * dt;
    cs.y += cs.vy * dt;
    // 拖尾
    cs.trail.push({ x: cs.x, y: cs.y, life: 0.3 });
    if (cs.trail.length > 12) cs.trail.shift();
    for (const tr of cs.trail) tr.life -= dt;
    cs.trail = cs.trail.filter(tr => tr.life > 0);
    // 碰撞
    for (const e of enemies) {
      if (e.dead || e.type === 'eBullet') continue;
      if (cs.hitSet.has(e.eid || e)) continue;
      const dx = e.x - cs.x, dy = e.y - cs.y;
      if (dx * dx + dy * dy < (20 + e.r) * (20 + e.r)) {
        cs.hitSet.add(e.eid || e);
        e.hurt(cs.dmg, Math.cos(cs.ang) * 0.5, Math.sin(cs.ang) * 0.5);
        spawnFloat(e.x, e.y - e.r, `-${Math.round(cs.dmg)}`, '#ffe58a');
        for (let j = 0; j < 6; j++) addParticle(new Particle(e.x, e.y, '#ffd166'));
        // 爆炸
        for (const e2 of enemies) {
          if (e2.dead || e2.type === 'eBullet' || e2 === e) continue;
          const dx2 = e2.x - cs.x, dy2 = e2.y - cs.y;
          if (dx2 * dx2 + dy2 * dy2 < cs.blastR * cs.blastR) {
            e2.hurt(cs.dmg * 0.5, dx2 * 0.01, dy2 * 0.01);
          }
        }
        cs.pierce--;
        if (cs.pierce <= 0) { cs.dead = true; break; }
      }
    }
    // 超出屏幕
    const margin = 100;
    if (cs.x < cam.x - margin || cs.x > cam.x + W + margin ||
        cs.y < cam.y - margin || cs.y > cam.y + H + margin) {
      cs.dead = true;
    }
    if (cs.t > 5) cs.dead = true;
  }
  cometSwords = cometSwords.filter(cs => !cs.dead);
}
/* =============================================================
   新三职业：绘制函数
   ============================================================= */
function getSwordSprite(size) {
  const s = size || 48;
  return cacheSprite('sword_'+s, s, g => {
    const len = s / 2 - 2;
    // 剑柄
    g.fillStyle = '#8a6238';
    g.fillRect(-1.5, -4, 3, 14);
    // 护手
    g.fillStyle = '#fdd86a';
    g.fillRect(-10, 10, 20, 3);
    // 剑身（金色渐变）
    const grad = g.createLinearGradient(0, -len, 0, 4);
    grad.addColorStop(0, '#fff6c2');
    grad.addColorStop(0.5, '#ffd766');
    grad.addColorStop(1, '#c89740');
    g.fillStyle = grad;
    g.beginPath();
    g.moveTo(-3, -4);
    g.lineTo(-2.5, -len);
    g.lineTo(0, -len - 2);
    g.lineTo(2.5, -len);
    g.lineTo(3, -4);
    g.closePath();
    g.fill();
    // 锋边高光
    g.strokeStyle = 'rgba(255,255,255,0.9)';
    g.lineWidth = 0.8;
    g.beginPath(); g.moveTo(-1.2, -len); g.lineTo(-1.2, -4); g.stroke();
    g.shadowBlur = 10; g.shadowColor = '#ffd166';
    g.strokeStyle = 'rgba(255,220,120,0.4)';
    g.beginPath(); g.moveTo(0, -len - 3); g.lineTo(0, 11); g.stroke();
    g.shadowBlur = 0;
  });
}
function drawSwordsArr() {
  if (!player || !player.swords || !player.swords.length) return;
  const p = player;
  const spr = getSwordSprite(48);
  const stormMode = !!p.swordStormMode;
  // —— 万剑归宗：剑阵领域视觉渲染（半透明金色圆环 + 旋转符文）——
  if (ultimateSwordDomain) {
    const d = ultimateSwordDomain;
    const pulse = 1 + 0.08 * Math.sin(timeElapsed * 6);
    ctx.save();
    // 领域填充光晕
    const grad = ctx.createRadialGradient(p.x, p.y, d.radius * 0.3, p.x, p.y, d.radius * pulse);
    grad.addColorStop(0, 'rgba(255,210,80,0.0)');
    grad.addColorStop(0.7, 'rgba(255,210,80,0.08)');
    grad.addColorStop(1, 'rgba(255,210,80,0.25)');
    ctx.fillStyle = grad;
    ctx.beginPath(); ctx.arc(p.x, p.y, d.radius * pulse, 0, TAU); ctx.fill();
    // 领域边框
    ctx.strokeStyle = 'rgba(255,220,120,0.6)';
    ctx.lineWidth = 3;
    ctx.setLineDash([12, 8]);
    ctx.beginPath(); ctx.arc(p.x, p.y, d.radius * pulse, 0, TAU); ctx.stroke();
    ctx.setLineDash([]);
    // 旋转的剑符文
    ctx.strokeStyle = 'rgba(255,230,150,0.4)';
    ctx.lineWidth = 1.5;
    const runeR = d.radius * 0.6;
    const runeCount = 8;
    for (let i = 0; i < runeCount; i++) {
      const a = timeElapsed * 1.5 + (i / runeCount) * TAU;
      const rx = p.x + Math.cos(a) * runeR;
      const ry = p.y + Math.sin(a) * runeR;
      ctx.beginPath();
      ctx.moveTo(rx - 6, ry - 10); ctx.lineTo(rx + 6, ry + 10);
      ctx.moveTo(rx + 6, ry - 10); ctx.lineTo(rx - 6, ry + 10);
      ctx.stroke();
    }
    ctx.restore();
  }
  // 轨道画线（剑刃风暴或磁力风暴都显示）
  if (stormMode || p.swordStorm) {
    ctx.save();
    ctx.strokeStyle = stormMode ? 'rgba(255,180,60,0.35)' : 'rgba(255,220,120,0.25)';
    ctx.lineWidth = stormMode ? 2 : 1;
    ctx.setLineDash([4, 6]);
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.swordRadius, 0, TAU);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.restore();
  }
  for (const sw of p.swords) {
    const bx = sw._x, by = sw._y;
    if (!bx && !by) continue;
    // ⚔️ 旋转角度：统一使用 _drawAng（orbit=切线，thrust/return=贝塞尔切线引导）
    const rot = sw._drawAng || (sw.ang + Math.PI / 2);
    const scale = stormMode ? 1.5 : 1;
    // ⚔️ 金色流星拖尾（类似经验球：炽白→金黄→橙红消散）
    if (sw.trail && sw.trail.length > 1) {
      ctx.save();
      for (let i = sw.trail.length - 1; i > 0; i--) {
        const t1 = sw.trail[i - 1];
        const t2 = sw.trail[i];
        const lifeAvg = (t1.life + t2.life) * 0.5;
        if (lifeAvg <= 0) continue;
        const w = 5 * scale * (0.1 + lifeAvg * 0.9);
        let r, g, b;
        if (lifeAvg > 0.66) { r = 255; g = 252; b = 230; }
        else if (lifeAvg > 0.33) { r = 255; g = 200; b = 80; }
        else { r = 230; g = 120; b = 30; }
        ctx.strokeStyle = `rgba(${r},${g},${b},${(lifeAvg * 0.85).toFixed(3)})`;
        ctx.lineWidth = w;
        ctx.lineCap = 'round';
        ctx.shadowColor = `rgba(${r},${g},${b},0.8)`;
        ctx.shadowBlur = w * 1.5;
        ctx.beginPath();
        ctx.moveTo(t2.x, t2.y);
        ctx.lineTo(t1.x, t1.y);
        ctx.stroke();
      }
      ctx.restore();
    }
    // ⚔️ 头部短尾段（17px金色）
    const trailLen = 17 * scale;
    ctx.save();
    ctx.globalAlpha = sw.phase === 'thrust' ? 0.65 : 0.4;
    ctx.strokeStyle = '#FFD700';
    ctx.lineWidth = 3 * scale;
    ctx.beginPath();
    const ex = bx - Math.cos(rot - Math.PI / 2) * trailLen;
    const ey = by - Math.sin(rot - Math.PI / 2) * trailLen;
    ctx.moveTo(ex, ey); ctx.lineTo(bx, by); ctx.stroke();
    ctx.restore();
    // 剑精灵（剑头引导朝向）
    ctx.save();
    ctx.translate(bx, by);
    ctx.rotate(rot);
    ctx.scale(scale, scale);
    ctx.drawImage(spr, -24, -24);
    ctx.restore();
  }
  // —— 剑气尾迹绘制（万剑归宗被动）——
  if (swordTrails.length > 1) {
    ctx.save();
    for (let i = 0; i < swordTrails.length; i++) {
      const tr = swordTrails[i];
      const a = tr.life / tr.maxLife;
      ctx.globalAlpha = a * 0.6;
      ctx.fillStyle = '#fff1a8';
      ctx.beginPath();
      ctx.arc(tr.x, tr.y, 18 * a, 0, TAU);
      ctx.fill();
    }
    // 连接线
    ctx.globalAlpha = 0.4;
    ctx.strokeStyle = '#ffd166';
    ctx.lineWidth = 6;
    ctx.beginPath();
    ctx.moveTo(swordTrails[0].x, swordTrails[0].y);
    for (let i = 1; i < swordTrails.length; i++) {
      ctx.lineTo(swordTrails[i].x, swordTrails[i].y);
    }
    ctx.stroke();
    ctx.restore();
  }
  // 超武：水盾光环
  if (p.waterShieldOn) {
    ctx.save();
    const pulse = 1 + 0.12 * Math.sin(timeElapsed * 10);
    ctx.globalAlpha = 0.6;
    ctx.strokeStyle = '#7afcff';
    ctx.lineWidth = 4;
    ctx.beginPath(); ctx.arc(p.x, p.y, 28 * pulse, 0, TAU); ctx.stroke();
    ctx.globalAlpha = 0.2;
    ctx.fillStyle = '#7afcff';
    ctx.beginPath(); ctx.arc(p.x, p.y, 28 * pulse, 0, TAU); ctx.fill();
    ctx.restore();
  }
  // —— ⭐ 彗星飞剑绘制 ——
  for (const cs of cometSwords) {
    // 拖尾光带
    if (cs.trail.length > 1) {
      ctx.save();
      for (let i = cs.trail.length - 1; i > 0; i--) {
        const t1 = cs.trail[i - 1], t2 = cs.trail[i];
        const lifeAvg = (t1.life + t2.life) * 0.5;
        if (lifeAvg <= 0) continue;
        const w = 8 * (0.2 + lifeAvg * 0.8);
        let r, g, b;
        if (lifeAvg > 0.66) { r = 255; g = 252; b = 230; }
        else if (lifeAvg > 0.33) { r = 255; g = 200; b = 80; }
        else { r = 230; g = 120; b = 30; }
        ctx.strokeStyle = `rgba(${r},${g},${b},${(lifeAvg * 0.9).toFixed(3)})`;
        ctx.lineWidth = w;
        ctx.lineCap = 'round';
        ctx.shadowColor = `rgba(${r},${g},${b},0.9)`;
        ctx.shadowBlur = w * 2;
        ctx.beginPath();
        ctx.moveTo(t2.x, t2.y);
        ctx.lineTo(t1.x, t1.y);
        ctx.stroke();
      }
      ctx.restore();
    }
    // 巨剑本体（放大版剑精灵 + 光环）
    ctx.save();
    ctx.translate(cs.x, cs.y);
    ctx.rotate(cs.ang + Math.PI / 4);
    // 光环
    const auraGrad = ctx.createRadialGradient(0, 0, 0, 0, 0, 35);
    auraGrad.addColorStop(0, 'rgba(255,230,120,0.5)');
    auraGrad.addColorStop(0.5, 'rgba(255,200,80,0.2)');
    auraGrad.addColorStop(1, 'rgba(255,160,40,0)');
    ctx.fillStyle = auraGrad;
    ctx.beginPath(); ctx.arc(0, 0, 35, 0, TAU); ctx.fill();
    // 巨剑
    const bigSpr = getSwordSprite(72);
    ctx.drawImage(bigSpr, -36, -36);
    ctx.restore();
  }
}
// —— 火/土/风 三职业渲染 ——
function drawNewClasses() {
  // ====== 🔥 焦土渲染 ======
  for (const se of scorchedEarth) {
    const a = Math.min(1, se.remain / 1.5);
    ctx.save();
    ctx.globalAlpha = 0.35 * a;
    const grad = ctx.createRadialGradient(se.x, se.y, 0, se.x, se.y, se.r);
    grad.addColorStop(0, 'rgba(255,100,30,0.6)');
    grad.addColorStop(0.7, 'rgba(180,50,20,0.4)');
    grad.addColorStop(1, 'rgba(100,30,10,0)');
    ctx.fillStyle = grad;
    ctx.beginPath(); ctx.arc(se.x, se.y, se.r, 0, TAU); ctx.fill();
    // 火焰纹路
    ctx.globalAlpha = 0.5 * a;
    ctx.strokeStyle = '#ff6b35';
    ctx.lineWidth = 1.5;
    const flicker = Math.sin(timeElapsed * 8 + se.x * 0.1) * 3;
    for (let i = 0; i < 4; i++) {
      const ang = (i / 4) * TAU + timeElapsed;
      ctx.beginPath();
      ctx.moveTo(se.x + Math.cos(ang) * se.r * 0.3, se.y + Math.sin(ang) * se.r * 0.3);
      ctx.lineTo(se.x + Math.cos(ang) * se.r * 0.8 + flicker, se.y + Math.sin(ang) * se.r * 0.8 + flicker);
      ctx.stroke();
    }
    ctx.restore();
  }
  // ====== ⛰️ 地刺/石柱渲染 ======
  for (const sp of earthSpikes) {
    const a = Math.min(1, sp.remain / (sp.isPillar ? 2 : 3.0));  // ⚔️ 普通地刺淡出时间匹配持续3秒
    ctx.save();
    ctx.globalAlpha = a;
    if (sp.isPillar) {
      // 石柱
      ctx.fillStyle = '#8b6f47';
      ctx.strokeStyle = '#6b4423';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(sp.x - sp.r * 0.6, sp.y + sp.r * 0.5);
      ctx.lineTo(sp.x - sp.r * 0.4, sp.y - sp.r * 0.6);
      ctx.lineTo(sp.x + sp.r * 0.4, sp.y - sp.r * 0.6);
      ctx.lineTo(sp.x + sp.r * 0.6, sp.y + sp.r * 0.5);
      ctx.closePath();
      ctx.fill(); ctx.stroke();
      // 顶部尖
      ctx.fillStyle = '#a0826d';
      ctx.beginPath();
      ctx.moveTo(sp.x, sp.y - sp.r);
      ctx.lineTo(sp.x - sp.r * 0.3, sp.y - sp.r * 0.5);
      ctx.lineTo(sp.x + sp.r * 0.3, sp.y - sp.r * 0.5);
      ctx.closePath();
      ctx.fill();
    } else {
      // 普通地刺（持续伤害区，脉冲闪烁提示）
      const pulse = 0.7 + 0.3 * Math.sin(timeElapsed * 10 + sp.x * 0.1 + sp.y * 0.1);
      ctx.globalAlpha = a * pulse;
      // 外圈伤害区光晕
      ctx.fillStyle = 'rgba(160,130,109,0.25)';
      ctx.beginPath(); ctx.arc(sp.x, sp.y, sp.r * 1.3, 0, TAU); ctx.fill();
      // 地刺主体
      ctx.fillStyle = '#a0826d';
      ctx.beginPath();
      ctx.moveTo(sp.x, sp.y - sp.r);
      ctx.lineTo(sp.x - sp.r * 0.4, sp.y + sp.r * 0.5);
      ctx.lineTo(sp.x + sp.r * 0.4, sp.y + sp.r * 0.5);
      ctx.closePath();
      ctx.fill();
      // 高光
      ctx.fillStyle = 'rgba(255,220,180,0.6)';
      ctx.beginPath();
      ctx.moveTo(sp.x, sp.y - sp.r);
      ctx.lineTo(sp.x - sp.r * 0.15, sp.y + sp.r * 0.3);
      ctx.lineTo(sp.x + sp.r * 0.05, sp.y + sp.r * 0.3);
      ctx.closePath();
      ctx.fill();
    }
    ctx.restore();
  }
  // ====== 🌪️ 风刃手里剑渲染 ======
  const _wbRadiusMul = (player && player.windRadius) ? Math.max(0.5, player.windRadius / 70) : 1;
  for (const wb of windBlades) {
    ctx.save();
    ctx.translate(wb._x, wb._y);
    const rot = Math.atan2(wb.ty - wb.oy, wb.tx - wb.ox);
    ctx.rotate(rot + Math.PI / 4);
    const r = 14 * _wbRadiusMul * (wb.phase === 'outbound' ? (1 + wb.t * (wb.expand - 1)) : 1);
    ctx.fillStyle = '#48cae4';
    ctx.globalAlpha = 0.85;
    // 手里剑四角
    for (let i = 0; i < 4; i++) {
      ctx.save();
      ctx.rotate((i / 4) * TAU);
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.lineTo(r * 0.4, -r);
      ctx.lineTo(-r * 0.4, -r);
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    }
    // 中心
    ctx.fillStyle = '#b8f2e6';
    ctx.beginPath(); ctx.arc(0, 0, r * 0.3, 0, TAU); ctx.fill();
    ctx.restore();
  }
  // ====== 🌀 P0：风刃龙卷风渲染 ======
  for (const t of windTornadoes) {
    ctx.save();
    ctx.translate(t.x, t.y);
    for (let ring = 0; ring < 3; ring++) {
      const rr = t.r * (0.5 + ring * 0.28) * (1 + 0.08 * Math.sin(t.phase * 3 + ring));
      ctx.globalAlpha = 0.30 - ring * 0.07;
      ctx.strokeStyle = ring === 0 ? '#e0f7fa' : '#4dd0e1';
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.arc(0, 0, rr, t.phase + ring, t.phase + ring + Math.PI * 1.35);
      ctx.stroke();
    }
    ctx.restore();
  }
  // ====== 🕳️ P0：真空黑洞渲染 ======
  for (const v of windVortexes) {
    const k = v.t / v.dur;
    ctx.save();
    ctx.translate(v.x, v.y);
    ctx.globalAlpha = 0.35 * Math.sin(Math.min(1, k * 4) * Math.PI);
    ctx.fillStyle = '#5c6bc0';
    ctx.beginPath(); ctx.arc(0, 0, v.r, 0, TAU); ctx.fill();
    ctx.globalAlpha = 0.8;
    ctx.strokeStyle = '#9fa8da';
    ctx.lineWidth = 2.5;
    for (let i = 0; i < 3; i++) {
      ctx.beginPath();
      ctx.arc(0, 0, v.r * (0.35 + i * 0.2), timeElapsed * 4 * (i % 2 ? -1 : 1), timeElapsed * 4 * (i % 2 ? -1 : 1) + Math.PI * 1.2);
      ctx.stroke();
    }
    ctx.restore();
  }
  // ====== ⚡ P0：疾风连斩闪电轨迹 ======
  for (const c of windChainFx) {
    const a = c.t / c.max;
    ctx.save();
    ctx.globalAlpha = a;
    ctx.strokeStyle = '#82e9ff';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(c.x1, c.y1);
    const mx = (c.x1 + c.x2) / 2 + rand(-10, 10), my = (c.y1 + c.y2) / 2 + rand(-10, 10);
    ctx.lineTo(mx, my); ctx.lineTo(c.x2, c.y2);
    ctx.stroke();
    ctx.restore();
  }
  // ====== 🌪️ P0：风暴领域 + 💨 风之壁垒 光环 ======
  if (player && player.equippedWeapon === 'wind_blade') {
    if (player.windStorm && player.windStormDps > 0) {
      const R = player.windStormR || 120;
      ctx.save();
      ctx.globalAlpha = 0.12 + 0.05 * Math.sin(timeElapsed * 5);
      ctx.fillStyle = '#4dd0e1';
      ctx.beginPath(); ctx.arc(player.x, player.y, R, 0, TAU); ctx.fill();
      ctx.globalAlpha = 0.4;
      ctx.strokeStyle = '#80deea';
      ctx.lineWidth = 2;
      ctx.setLineDash([6, 8]);
      ctx.beginPath(); ctx.arc(player.x, player.y, R, timeElapsed * 2, timeElapsed * 2 + TAU); ctx.stroke();
      ctx.setLineDash([]);
      ctx.restore();
    }
    if (player.bossWindBarrier) {
      const R = player.bossWindBarrierR || 100;
      ctx.save();
      ctx.globalAlpha = 0.18 + 0.06 * Math.sin(timeElapsed * 6);
      ctx.strokeStyle = '#b8f2e6';
      ctx.lineWidth = 3;
      ctx.beginPath(); ctx.arc(player.x, player.y, R, 0, TAU); ctx.stroke();
      ctx.restore();
    }
  }
  // ====== ☀️ P0：审判之剑光柱渲染 ======
  for (const j of slashJudgmentFx) {
    const a = j.t / j.max;
    ctx.save();
    ctx.translate(j.x, j.y);
    ctx.globalAlpha = a;
    const grad = ctx.createLinearGradient(0, -260, 0, 0);
    grad.addColorStop(0, 'rgba(255,241,118,0)');
    grad.addColorStop(1, 'rgba(255,224,130,0.85)');
    ctx.fillStyle = grad;
    ctx.fillRect(-16, -260, 32, 260);
    ctx.globalAlpha = a * 0.6;
    ctx.fillStyle = '#fff59d';
    ctx.beginPath(); ctx.arc(0, 0, 70 * (1.2 - a * 0.4), 0, TAU); ctx.fill();
    ctx.restore();
  }
  // ====== 🛡️ P0：圣盾守护就绪指示 ======
  if (player && player.equippedWeapon === 'holy_shield' && (player._slashAegisReady || player._bossAegisReady)) {
    ctx.save();
    ctx.globalAlpha = 0.35 + 0.15 * Math.sin(timeElapsed * 6);
    ctx.strokeStyle = '#ffe9a8';
    ctx.lineWidth = 2.5;
    ctx.beginPath(); ctx.arc(player.x, player.y, player.r + 12, 0, TAU); ctx.stroke();
    ctx.restore();
  }
  // ====== 🔥 红莲业火岩浆渲染 ======
  if (ultimateLava) {
    ctx.save();
    ctx.globalAlpha = 0.25 + 0.1 * Math.sin(timeElapsed * 4);
    ctx.fillStyle = '#e63946';
    ctx.fillRect(cam.x, cam.y, W, H);
    ctx.restore();
  }
}

function drawThornZones() {
  if (!thornZones || !thornZones.length) return;
  for (const t of thornZones) {
    const a = Math.max(0, Math.min(1, t.life / (t.maxLife || 5)));
    ctx.save();
    // 外圈毒绿
    ctx.globalAlpha = 0.35 * a;
    const g1 = ctx.createRadialGradient(t.x, t.y, 0, t.x, t.y, t.r);
    g1.addColorStop(0, '#3cc86a');
    g1.addColorStop(0.7, '#2a8b4a');
    g1.addColorStop(1, 'rgba(40,120,60,0)');
    ctx.fillStyle = g1;
    ctx.beginPath(); ctx.arc(t.x, t.y, t.r, 0, TAU); ctx.fill();
    // 荆棘刺
    ctx.globalAlpha = 0.8 * a;
    ctx.strokeStyle = '#1d5c33';
    ctx.lineWidth = 1.5;
    const spokes = 12;
    for (let i = 0; i < spokes; i++) {
      const ang = (i / spokes) * TAU + (timeElapsed * 0.4);
      const r1 = t.r * 0.45;
      const r2 = t.r * 0.92;
      ctx.beginPath();
      ctx.moveTo(t.x + Math.cos(ang) * r1, t.y + Math.sin(ang) * r1);
      ctx.lineTo(t.x + Math.cos(ang) * r2, t.y + Math.sin(ang) * r2);
      ctx.stroke();
      // 小刺十字
      const px = t.x + Math.cos(ang) * r2;
      const py = t.y + Math.sin(ang) * r2;
      ctx.beginPath();
      ctx.arc(px, py, 3, 0, TAU);
      ctx.fillStyle = '#2e7a44';
      ctx.fill();
    }
    // 中心脉动
    ctx.globalAlpha = 0.4 * a;
    ctx.beginPath();
    ctx.arc(t.x, t.y, 16 + 4 * Math.sin(timeElapsed * 4), 0, TAU);
    ctx.fillStyle = '#88ff88';
    ctx.fill();
    ctx.restore();
  }
}
function drawPlantsArr() {
  if (!plantsArr || !plantsArr.length) return;
  for (const pl of plantsArr) {
    ctx.save();
    ctx.translate(pl.x, pl.y);
    const pulse = 1 + 0.05 * Math.sin(pl.pulseT * 3);
    if (pl.kind === 'flower') {
      // 食人花：茎+5花瓣+嘴
      ctx.strokeStyle = '#2a8b4a';
      ctx.lineWidth = 3;
      ctx.beginPath(); ctx.moveTo(0, 6); ctx.lineTo(0, 14); ctx.stroke();
      const petals = 6;
      for (let i = 0; i < petals; i++) {
        const a = (i / petals) * TAU + pl.pulseT;
        const px = Math.cos(a) * 9 * pulse;
        const py = Math.sin(a) * 9 * pulse - 1;
        ctx.fillStyle = '#ff66aa';
        ctx.beginPath(); ctx.arc(px, py, 6, 0, TAU); ctx.fill();
        ctx.fillStyle = 'rgba(255,255,255,0.4)';
        ctx.beginPath(); ctx.arc(px - 1.5, py - 1.5, 2, 0, TAU); ctx.fill();
      }
      // 花蕊/嘴
      ctx.fillStyle = '#5a1022';
      ctx.beginPath(); ctx.arc(0, -1, 5, 0, TAU); ctx.fill();
      // 两颗牙
      ctx.fillStyle = '#fff';
      ctx.beginPath(); ctx.moveTo(-2, -1); ctx.lineTo(-1, 3); ctx.lineTo(0, -1); ctx.fill();
      ctx.beginPath(); ctx.moveTo(2, -1); ctx.lineTo(1, 3); ctx.lineTo(0, -1); ctx.fill();
    } else {
      // 毒蘑菇：茎+帽+白点
      ctx.fillStyle = '#efe2c8';
      ctx.fillRect(-3, 0, 6, 12);
      ctx.fillStyle = '#b986e5';
      ctx.beginPath(); ctx.ellipse(0, -1, 14 * pulse, 9, 0, Math.PI, TAU); ctx.fill();
      ctx.fillStyle = '#ffffff';
      for (const [dx, dy, r] of [[-6,-3,2],[4,-5,1.5],[0,-7,1.8],[7,-2,1.4]]) {
        ctx.beginPath(); ctx.arc(dx, dy, r, 0, TAU); ctx.fill();
      }
    }
    // 影子
    ctx.globalAlpha = 0.25;
    ctx.fillStyle = '#000';
    ctx.beginPath(); ctx.ellipse(0, 16, 10, 2.5, 0, 0, TAU); ctx.fill();
    ctx.restore();
  }
}
function drawWavesArr() {
  if (!waves || !waves.length) return;
  for (const w of waves) {
    ctx.save();
    ctx.translate(w.x, w.y);
    ctx.rotate(w.ang);
    const width = w.width;
    const prog = w.traveled / w.maxTravel;
    const isTsunami = !!w.isTsunami;
    const intensity = isTsunami ? 1.6 : 1.0;
    // 底层浪花（大范围柔和渐变）
    const gr0 = ctx.createLinearGradient(-w.r * 1.2, 0, w.r * 1.2, 0);
    gr0.addColorStop(0, 'rgba(80,180,240,0)');
    gr0.addColorStop(0.3, `rgba(100,200,255,${0.3 * intensity})`);
    gr0.addColorStop(0.7, `rgba(130,220,255,${0.5 * intensity})`);
    gr0.addColorStop(1, 'rgba(180,240,255,0)');
    ctx.fillStyle = gr0;
    ctx.fillRect(-w.r * 1.2, -width / 2 - 10, w.r * 2.4, width + 20);
    // 主浪身
    const gr = ctx.createLinearGradient(-w.r, 0, w.r, 0);
    gr.addColorStop(0, 'rgba(100,200,255,0)');
    gr.addColorStop(0.4, `rgba(120,210,255,${0.55 * intensity})`);
    gr.addColorStop(0.8, `rgba(160,230,255,${0.75 * intensity})`);
    gr.addColorStop(1, `rgba(200,240,255,${0.3 * intensity})`);
    ctx.fillStyle = gr;
    ctx.fillRect(-w.r, -width / 2, w.r * 1.5, width);
    // 高光条（浪峰）
    const gr2 = ctx.createLinearGradient(w.r * 0.3, 0, w.r, 0);
    gr2.addColorStop(0, 'rgba(255,255,255,0)');
    gr2.addColorStop(0.6, `rgba(255,255,255,${0.5 * intensity})`);
    gr2.addColorStop(1, `rgba(220,245,255,${0.2 * intensity})`);
    ctx.fillStyle = gr2;
    ctx.fillRect(w.r * 0.3, -width / 2 + 4, w.r * 0.7, width - 8);
    // 泡沫前沿（波浪形白色线 + 飞溅水滴）
    ctx.strokeStyle = `rgba(255,255,255,${0.85 + 0.1 * Math.sin(timeElapsed * 10)})`;
    ctx.lineWidth = isTsunami ? 4 : 3;
    ctx.beginPath();
    for (let y = -width / 2; y <= width / 2; y += 6) {
      const yo = y + Math.sin(timeElapsed * 10 + y * 0.08) * 4 + Math.sin(timeElapsed * 6 + y * 0.03) * 2;
      if (y === -width / 2) ctx.moveTo(w.r, yo);
      else ctx.lineTo(w.r, yo);
    }
    ctx.stroke();
    // 飞溅水滴（前沿随机飞出）
    const dropCount = isTsunami ? 8 : 5;
    for (let i = 0; i < dropCount; i++) {
      const yPos = -width / 2 + (i / (dropCount - 1)) * width;
      const yo = yPos + Math.sin(timeElapsed * 8 + i * 1.3) * 3;
      const dropR = 2 + Math.sin(timeElapsed * 5 + i) * 1.5;
      const dropX = w.r + 4 + Math.sin(timeElapsed * 6 + i * 0.7) * 6;
      ctx.fillStyle = 'rgba(255,255,255,0.8)';
      ctx.beginPath(); ctx.arc(dropX, yo, dropR, 0, TAU); ctx.fill();
    }
    // 泡沫圆点（更大更多）
    for (let y = -width / 2 + 15; y <= width / 2 - 15; y += 25) {
      const yo = y + Math.sin(timeElapsed * 7 + y * 0.06) * 4;
      ctx.fillStyle = 'rgba(255,255,255,0.6)';
      ctx.beginPath(); ctx.arc(w.r - 2 + rand(-3, 3), yo + rand(-4, 4), rand(2, 5), 0, TAU); ctx.fill();
      ctx.fillStyle = 'rgba(200,240,255,0.4)';
      ctx.beginPath(); ctx.arc(w.r - 8 + rand(-2, 2), yo + rand(-3, 3), rand(3, 6), 0, TAU); ctx.fill();
    }
    // 🌊 海啸特效：外发光 + 彩虹边缘
    if (isTsunami) {
      ctx.shadowColor = 'rgba(120,200,255,0.8)';
      ctx.shadowBlur = 20;
      ctx.strokeStyle = 'rgba(180,230,255,0.6)';
      ctx.lineWidth = 2;
      ctx.strokeRect(-w.r, -width / 2, w.r * 1.5, width);
      ctx.shadowBlur = 0;
    }
    ctx.restore();
  }
}
function drawFrostZonesArr() {
  if (!frostZones || !frostZones.length) return;
  for (const fz of frostZones) {
    const a = Math.min(1, fz.t / 0.3) * Math.min(1, (fz.dur - fz.t) / 0.5);
    ctx.save();
    // 外圈渐变冰雾
    const grad = ctx.createRadialGradient(fz.x, fz.y, 0, fz.x, fz.y, fz.r);
    grad.addColorStop(0, `rgba(180,230,255,${0.35 * a})`);
    grad.addColorStop(0.6, `rgba(140,210,255,${0.25 * a})`);
    grad.addColorStop(1, 'rgba(100,180,240,0)');
    ctx.fillStyle = grad;
    ctx.beginPath(); ctx.arc(fz.x, fz.y, fz.r, 0, TAU); ctx.fill();
    // 冰晶旋转
    ctx.strokeStyle = `rgba(200,240,255,${0.5 * a})`;
    ctx.lineWidth = 1.5;
    for (let i = 0; i < 6; i++) {
      const ang = (i / 6) * TAU + timeElapsed * 0.5 + fz.x * 0.01;
      const r1 = fz.r * 0.6 + Math.sin(timeElapsed * 2 + i) * 8;
      const r2 = fz.r * 0.85 + Math.cos(timeElapsed * 1.5 + i) * 5;
      const x1 = fz.x + Math.cos(ang) * r1;
      const y1 = fz.y + Math.sin(ang) * r1;
      const x2 = fz.x + Math.cos(ang) * r2;
      const y2 = fz.y + Math.sin(ang) * r2;
      ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
    }
    // 雪花粒子
    ctx.fillStyle = `rgba(255,255,255,${0.7 * a})`;
    for (let i = 0; i < 5; i++) {
      const ang = timeElapsed * 0.8 + i * 1.3 + fz.x * 0.02;
      const r = fz.r * 0.5 + Math.sin(timeElapsed * 1.2 + i * 0.7) * 20;
      const px = fz.x + Math.cos(ang) * r;
      const py = fz.y + Math.sin(ang) * r + Math.sin(timeElapsed * 3 + i) * 6;
      const sz = 2 + Math.sin(timeElapsed * 4 + i) * 1;
      ctx.beginPath();
      ctx.moveTo(px, py - sz);
      ctx.lineTo(px - sz, py + sz * 0.5);
      ctx.lineTo(px + sz, py + sz * 0.5);
      ctx.closePath();
      ctx.fill();
    }
    ctx.restore();
  }
}
function drawWaterTornadoesArr() {
  if (!waterTornadoes || !waterTornadoes.length) return;
  for (const t of waterTornadoes) {
    const prog = t.t / t.dur;
    const a = Math.min(1, t.t / 0.5) * Math.min(1, (t.dur - t.t) / 0.5);
    const pulse = 1 + 0.05 * Math.sin(timeElapsed * 3);
    ctx.save();
    // 外层大范围水雾（环境效果）
    const outerGrad = ctx.createRadialGradient(t.x, t.y, t.r * 0.5, t.x, t.y, t.r * 1.3);
    outerGrad.addColorStop(0, `rgba(150,220,255,${0.25 * a})`);
    outerGrad.addColorStop(1, 'rgba(100,190,240,0)');
    ctx.fillStyle = outerGrad;
    ctx.beginPath(); ctx.arc(t.x, t.y, t.r * 1.3 * pulse, 0, TAU); ctx.fill();
    // 中心水柱
    const grad = ctx.createRadialGradient(t.x, t.y, 0, t.x, t.y, t.r);
    grad.addColorStop(0, `rgba(200,240,255,${0.7 * a})`);
    grad.addColorStop(0.3, `rgba(140,215,255,${0.55 * a})`);
    grad.addColorStop(0.7, `rgba(100,195,245,${0.35 * a})`);
    grad.addColorStop(1, 'rgba(80,180,240,0)');
    ctx.fillStyle = grad;
    ctx.beginPath(); ctx.arc(t.x, t.y, t.r * pulse, 0, TAU); ctx.fill();
    // 螺旋水流（5条螺旋臂，更像真正的龙卷风）
    for (let arm = 0; arm < 5; arm++) {
      ctx.strokeStyle = `rgba(210,245,255,${(0.55 - arm * 0.08) * a})`;
      ctx.lineWidth = 4 - arm * 0.6;
      ctx.beginPath();
      const armOffset = (arm / 5) * TAU + t.phase;
      for (let i = 0; i <= 30; i++) {
        const radFrac = i / 30;  // 0~1 从内到外
        const ang = armOffset + radFrac * TAU * 1.8 + t.phase * 0.5;
        const wobble = Math.sin(radFrac * 8 + timeElapsed * 4 + arm) * (4 + radFrac * 8);
        const r = t.r * radFrac * pulse + wobble;
        const px = t.x + Math.cos(ang) * r;
        const py = t.y + Math.sin(ang) * r - radFrac * radFrac * 20;  // 向上抬升感
        if (i === 0) ctx.moveTo(px, py);
        else ctx.lineTo(px, py);
      }
      ctx.stroke();
    }
    // 内部亮芯
    const coreGrad = ctx.createRadialGradient(t.x, t.y - 10, 0, t.x, t.y - 10, t.r * 0.4);
    coreGrad.addColorStop(0, `rgba(255,255,255,${0.5 * a})`);
    coreGrad.addColorStop(1, 'rgba(200,240,255,0)');
    ctx.fillStyle = coreGrad;
    ctx.beginPath(); ctx.arc(t.x, t.y - 10, t.r * 0.4, 0, TAU); ctx.fill();
    // 飞溅水滴（螺旋上升）
    for (let i = 0; i < 12; i++) {
      const dropPhase = (i / 12) * TAU + t.phase * 2;
      const dropR = t.r * 0.3 + ((timeElapsed * 60 + i * 20) % (t.r * 0.6));
      const px = t.x + Math.cos(dropPhase) * dropR;
      const py = t.y + Math.sin(dropPhase) * dropR - (dropR / t.r) * 25;
      const sz = 2.5 + Math.sin(timeElapsed * 6 + i * 0.8) * 1.5;
      ctx.fillStyle = `rgba(255,255,255,${0.8 * a})`;
      ctx.beginPath(); ctx.arc(px, py, sz, 0, TAU); ctx.fill();
    }
    // 底部水花环
    ctx.strokeStyle = `rgba(200,240,255,${0.6 * a})`;
    ctx.lineWidth = 2;
    ctx.beginPath();
    const bottomR = t.r * 0.9;
    for (let i = 0; i <= 24; i++) {
      const ang = (i / 24) * TAU + t.phase;
      const rVar = Math.sin(ang * 4 + timeElapsed * 5) * 4;
      const px = t.x + Math.cos(ang) * (bottomR + rVar);
      const py = t.y + Math.sin(ang) * (bottomR * 0.5 + rVar * 0.5) + t.r * 0.3;
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.stroke();
    // 顶部水雾柱
    const topY = t.y - t.r * 0.8;
    const topGrad = ctx.createRadialGradient(t.x, topY, 0, t.x, topY, t.r);
    topGrad.addColorStop(0, `rgba(230,250,255,${0.35 * a})`);
    topGrad.addColorStop(0.5, `rgba(190,235,255,${0.2 * a})`);
    topGrad.addColorStop(1, 'rgba(160,220,255,0)');
    ctx.fillStyle = topGrad;
    ctx.beginPath(); ctx.arc(t.x, topY, t.r, 0, TAU); ctx.fill();
    ctx.restore();
  }
}
function drawBubbleSplashFxArr() {
  if (!bubbleSplashFx || !bubbleSplashFx.length) return;
  for (const f of bubbleSplashFx) {
    const a = 1 - f.t / f.maxT;
    ctx.save();
    ctx.globalAlpha = a;
    ctx.strokeStyle = '#7afcff';
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.arc(f.x, f.y, f.r + f.t * 60, 0, TAU); ctx.stroke();
    ctx.globalAlpha = 0.2 * a;
    ctx.fillStyle = '#c9f3ff';
    ctx.beginPath(); ctx.arc(f.x, f.y, f.r + f.t * 40, 0, TAU); ctx.fill();
    ctx.restore();
  }
}
function drawUltimateEffects() {
  // 森林：全屏毒雾
  if (ultimateForest) {
    ctx.save();
    const a = Math.max(0.22, ultimateForest.remain / 8 * 0.5);
    ctx.globalAlpha = a;
    const g = ctx.createLinearGradient(cam.x, cam.y, cam.x, cam.y + H);
    g.addColorStop(0, 'rgba(80,180,100,0.55)');
    g.addColorStop(1, 'rgba(30,100,60,0.7)');
    ctx.fillStyle = g;
    ctx.fillRect(cam.x, cam.y, W, H);
    // 飘动毒泡
    for (let i = 0; i < 18; i++) {
      const px = cam.x + ((i * 97 + (timeElapsed * 60)) % W);
      const py = cam.y + ((i * 53 + Math.sin(timeElapsed + i) * 40) % H);
      ctx.globalAlpha = 0.35;
      ctx.fillStyle = '#b9f6ca';
      ctx.beginPath(); ctx.arc(px, py, 6 + (i%3), 0, TAU); ctx.fill();
    }
    ctx.restore();
  }
  // 金：剑阵领域 + 剑雨
  if (ultimateSwordDomain || (player && player.swordUltimateOn)) {
    const p = player;
    if (p) {
      const r = ultimateSwordDomain ? ultimateSwordDomain.radius : 220;
      ctx.save();
      const pulse = 1 + 0.04 * Math.sin(timeElapsed * 6);
      ctx.globalAlpha = 0.25;
      const g = ctx.createRadialGradient(p.x, p.y, 0, p.x, p.y, r);
      g.addColorStop(0, 'rgba(255,220,120,0.6)');
      g.addColorStop(1, 'rgba(255,180,60,0)');
      ctx.fillStyle = g;
      ctx.beginPath(); ctx.arc(p.x, p.y, r * pulse, 0, TAU); ctx.fill();
      ctx.globalAlpha = 0.6;
      ctx.strokeStyle = '#ffd166';
      ctx.lineWidth = 2;
      ctx.setLineDash([8, 6]);
      ctx.beginPath(); ctx.arc(p.x, p.y, r * pulse, 0, TAU); ctx.stroke();
      ctx.setLineDash([]);
      ctx.restore();
    }
  }
  // 剑雨下落
  for (const s of swordRains) {
    const prog = s.t / s.maxT;
    const ang = s.ang || Math.PI / 4;
    ctx.save();
    ctx.translate(s.x + Math.cos(ang) * (-40 + prog * 80), s.y + Math.sin(ang) * (-40 + prog * 80));
    ctx.rotate(ang);
    const spr = getSwordSprite(36);
    ctx.globalAlpha = Math.max(0, Math.min(1, 1 - Math.abs(prog - 0.5) * 2));
    ctx.drawImage(spr, -18, -18);
    ctx.restore();
  }
  // 水：深海高压水龙卷
  if (ultimateWater && player) {
    const p = player;
    ctx.save();
    const t = timeElapsed;
    for (let layer = 0; layer < 4; layer++) {
      const r = 60 + layer * 35 + Math.sin(t * 3 + layer) * 6;
      ctx.globalAlpha = 0.18 + 0.06 * layer;
      ctx.strokeStyle = ['#66d9ff','#7afcff','#a8e8ff','#c9f3ff'][layer];
      ctx.lineWidth = 4 + layer;
      ctx.beginPath();
      for (let i = 0; i <= 48; i++) {
        const a = (i / 48) * TAU + t * 1.5 * (1 + layer * 0.2);
        const rr = r + Math.sin(a * 6 + t * 4) * 8;
        const px = p.x + Math.cos(a) * rr;
        const py = p.y + Math.sin(a) * rr;
        if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
      }
      ctx.closePath();
      ctx.stroke();
    }
    // 中心核心
    ctx.globalAlpha = 0.45;
    ctx.fillStyle = '#7afcff';
    ctx.beginPath(); ctx.arc(p.x, p.y, 26 + Math.sin(t*5)*4, 0, TAU); ctx.fill();
    ctx.restore();
  }
}
/* =============================================================
   绘制：飞刃 / 特效 / 背景 / 提示
   ============================================================= */
function drawBlades() {
  if (!player || player.bladeCount === 0) return;
  const spr = getBladeSprite();
  for (const bd of player.blades) {
    const x = bd._x !== undefined ? bd._x : player.x + Math.cos(bd.ang) * bd.radius;
    const y = bd._y !== undefined ? bd._y : player.y + Math.sin(bd.ang) * bd.radius;
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(bd.ang * 2);
    ctx.drawImage(spr, -spr.width / 2, -spr.height / 2);
    ctx.restore();
  }
}

function drawSummons() {
  if (!player || !player.summons || player.summons.length === 0) return;
  const t = (typeof timeElapsed === 'number' ? timeElapsed : 0) + performance.now() * 1e-3;
  for (const s of player.summons) {
    ctx.save();
    ctx.translate(s.x, s.y);

    // 外发光光晕
    const pulse = 1 + Math.sin(t * 3 + s.bobPhase) * 0.08;
    ctx.shadowColor = '#a3e4ff'; ctx.shadowBlur = 16;
    const aura = ctx.createRadialGradient(0, 2, 1, 0, 2, 14 * pulse);
    aura.addColorStop(0, 'rgba(220,245,255,0.7)');
    aura.addColorStop(0.5, 'rgba(130,220,255,0.4)');
    aura.addColorStop(1, 'rgba(50,140,220,0)');
    ctx.fillStyle = aura;
    ctx.beginPath(); ctx.arc(0, 2, 14 * pulse, 0, TAU); ctx.fill();
    ctx.shadowBlur = 0;

    // 翅膀拍动
    const wingFlap = 0.5 + 0.5 * Math.abs(Math.sin(t * 10 + s.bobPhase));
    const wingScale = 0.6 + wingFlap * 0.5;

    // 左翼
    ctx.save();
    ctx.translate(-1, 0);
    ctx.scale(-wingScale, wingScale * 0.9);
    const wg = ctx.createRadialGradient(-6, -2, 0, -6, -2, 8);
    wg.addColorStop(0, 'rgba(255,255,255,0.85)');
    wg.addColorStop(0.5, 'rgba(180,220,255,0.5)');
    wg.addColorStop(1, 'rgba(130,180,255,0)');
    ctx.fillStyle = wg;
    ctx.beginPath();
    ctx.moveTo(0, -2);
    ctx.quadraticCurveTo(-7, -8, -11, -2);
    ctx.quadraticCurveTo(-7, 3, 0, 2);
    ctx.closePath(); ctx.fill();
    ctx.restore();

    // 右翼
    ctx.save();
    ctx.translate(1, 0);
    ctx.scale(wingScale, wingScale * 0.9);
    ctx.fillStyle = wg;
    ctx.beginPath();
    ctx.moveTo(0, -2);
    ctx.quadraticCurveTo(7, -8, 11, -2);
    ctx.quadraticCurveTo(7, 3, 0, 2);
    ctx.closePath(); ctx.fill();
    ctx.restore();

    // 身体（淡蓝光球）
    const bodyGrd = ctx.createRadialGradient(0, -1, 1, 0, 0, 7);
    bodyGrd.addColorStop(0, '#ffffff');
    bodyGrd.addColorStop(0.4, '#b3e5fc');
    bodyGrd.addColorStop(1, '#4fc3f7');
    ctx.fillStyle = bodyGrd;
    ctx.shadowColor = '#81d4fa'; ctx.shadowBlur = 8;
    ctx.beginPath(); ctx.arc(0, 0, 6.5, 0, TAU); ctx.fill();
    ctx.shadowBlur = 0;

    // 头顶光环
    ctx.globalAlpha = 0.7 + 0.3 * Math.sin(t * 2 + s.bobPhase);
    ctx.strokeStyle = '#fff59d';
    ctx.lineWidth = 1.5;
    ctx.shadowColor = '#ffd54f'; ctx.shadowBlur = 6;
    ctx.beginPath();
    ctx.ellipse(0, -8, 5, 1.5, 0, 0, TAU);
    ctx.stroke();
    ctx.shadowBlur = 0;
    ctx.globalAlpha = 1;

    // 眼睛（两个小亮点）
    ctx.fillStyle = '#1a237e';
    ctx.beginPath(); ctx.arc(-2, -0.5, 0.9, 0, TAU); ctx.fill();
    ctx.beginPath(); ctx.arc(2, -0.5, 0.9, 0, TAU); ctx.fill();
    // 眼睛高光
    ctx.fillStyle = '#ffffff';
    ctx.beginPath(); ctx.arc(-1.7, -0.8, 0.35, 0, TAU); ctx.fill();
    ctx.beginPath(); ctx.arc(2.3, -0.8, 0.35, 0, TAU); ctx.fill();

    // 微笑
    ctx.strokeStyle = '#1a237e';
    ctx.lineWidth = 0.8;
    ctx.beginPath();
    ctx.arc(0, 1, 1.5, 0.2, Math.PI - 0.2);
    ctx.stroke();

    ctx.restore();
  }
}

function drawFx() {
  for (const s of slashFx) {
    const a = Math.max(0, s.t / s.max);
    const progress = 1 - a; // 0→1 延伸进度
    // 🔥 火焰斩击（炽烈怒焰）：整把刀光换为焰色
    const fire = !!s.fire;
    const cGlow  = fire ? '#ff5722' : '#ffd1dc';
    const cMain  = fire ? '#ff9800' : '#ffd1dc';
    const cCore  = fire ? '#ffeb3b' : '#ffe082';
    ctx.save();
    ctx.translate(s.x, s.y);

    if (s.chain) {
      // 链式闪电特效
      ctx.globalAlpha = a;
      ctx.strokeStyle = '#82e9ff';
      ctx.lineWidth = 3;
      ctx.shadowColor = '#82e9ff'; ctx.shadowBlur = 14;
      ctx.beginPath();
      const segs = 5;
      ctx.moveTo(0, 0);
      for (let i = 1; i <= segs; i++) {
        const tt = i / segs;
        const cx = Math.cos(s.ang) * s.r * tt + rand(-6, 6);
        const cy = Math.sin(s.ang) * s.r * tt + rand(-6, 6);
        ctx.lineTo(cx, cy);
      }
      ctx.stroke();
      ctx.restore();
      continue;
    }

    // 挥砍动画：从本体延伸到末端，中间厚两侧尖的刀刃形
    const curR = s.r * Math.min(1, progress * 1.5);
    const ha = s.halfAng || 1.15;

    if (s.full) {
      // 环形斩：360° 填充
      ctx.globalAlpha = a * 0.3;
      const grd = ctx.createRadialGradient(0, 0, 0, 0, 0, curR);
      grd.addColorStop(0, fire ? 'rgba(255, 120, 30, 0)' : 'rgba(255, 209, 221, 0)');
      grd.addColorStop(0.7, fire ? 'rgba(255, 110, 20, 0.14)' : 'rgba(255, 209, 221, 0.12)');
      grd.addColorStop(1, fire ? 'rgba(255, 87, 34, 0.34)' : 'rgba(255, 160, 180, 0.3)');
      ctx.fillStyle = grd;
      ctx.beginPath(); ctx.arc(0, 0, curR, 0, TAU); ctx.fill();

      ctx.globalAlpha = a * 0.9;
      ctx.strokeStyle = '#ffffff';
      ctx.lineWidth = 5; ctx.lineCap = 'round';
      ctx.shadowColor = cGlow; ctx.shadowBlur = 16;
      ctx.beginPath(); ctx.arc(0, 0, curR, 0, TAU); ctx.stroke();
    } else {
      // 扇形刀刃：中间厚两侧尖 —— 用多段渐变宽度绘制
      const segs = 24;
      const maxW = 14; // 中间最大半宽（px）

      // 外层光晕填充
      ctx.globalAlpha = a * 0.25;
      const grd = ctx.createRadialGradient(0, 0, 0, 0, 0, curR);
      grd.addColorStop(0, fire ? 'rgba(255, 120, 30, 0)' : 'rgba(255, 209, 221, 0)');
      grd.addColorStop(0.6, fire ? 'rgba(255, 110, 20, 0.1)' : 'rgba(255, 209, 221, 0.08)');
      grd.addColorStop(1, fire ? 'rgba(255, 87, 34, 0.24)' : 'rgba(255, 160, 180, 0.2)');
      ctx.fillStyle = grd;
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.arc(0, 0, curR, s.ang - ha, s.ang + ha);
      ctx.closePath();
      ctx.fill();

      // 刀刃主体：从中心到末端，宽度按 cos 曲线从中间到两侧递减 → 尖端
      // 逐段填充三角形条带
      for (let i = 0; i < segs; i++) {
        const t0 = i / segs, t1 = (i + 1) / segs;
        const a0 = s.ang - ha + t0 * ha * 2;
        const a1 = s.ang - ha + t1 * ha * 2;
        // 宽度：中间 (t=0.5) 最宽，两端为 0
        const w0 = maxW * Math.sin(t0 * Math.PI);
        const w1 = maxW * Math.sin(t1 * Math.PI);
        // 法线方向（垂直于弧线切线）
        const nx0 = -Math.sin(a0), ny0 = Math.cos(a0);
        const nx1 = -Math.sin(a1), ny1 = Math.cos(a1);
        const r = curR;
        // 四个顶点：内/外弧线 ± 半宽偏移
        const p1x = Math.cos(a0) * r + nx0 * w0, p1y = Math.sin(a0) * r + ny0 * w0;
        const p2x = Math.cos(a1) * r + nx1 * w1, p2y = Math.sin(a1) * r + ny1 * w1;
        const p3x = Math.cos(a1) * r - nx1 * w1, p3y = Math.sin(a1) * r - ny1 * w1;
        const p4x = Math.cos(a0) * r - nx0 * w0, p4y = Math.sin(a0) * r - ny0 * w0;

        const segT = (t0 + t1) / 2;
        const brightness = 0.5 + 0.5 * Math.sin(segT * Math.PI); // 中间最亮

        ctx.globalAlpha = a * (0.6 + brightness * 0.4);
        ctx.fillStyle = brightness > 0.7 ? '#ffffff' : (fire ? (brightness > 0.45 ? '#ffb300' : '#ff7043') : '#ffd1dc');
        ctx.shadowColor = cGlow; ctx.shadowBlur = brightness > 0.5 ? 14 : 6;
        ctx.beginPath();
        ctx.moveTo(p1x, p1y);
        ctx.lineTo(p2x, p2y);
        ctx.lineTo(p3x, p3y);
        ctx.lineTo(p4x, p4y);
        ctx.closePath();
        ctx.fill();
      }

      // 中心高亮线（明亮核心）
      ctx.globalAlpha = a * 0.85;
      ctx.strokeStyle = '#ffffff';
      ctx.lineWidth = 3; ctx.lineCap = 'round';
      ctx.shadowColor = cCore; ctx.shadowBlur = 12;
      ctx.beginPath();
      ctx.arc(0, 0, curR, s.ang - ha * 0.5, s.ang + ha * 0.5);
      ctx.stroke();

      // 内层金色/焰心弧线
      ctx.globalAlpha = a * 0.5;
      ctx.strokeStyle = cCore;
      ctx.lineWidth = 2;
      ctx.shadowColor = cMain; ctx.shadowBlur = 8;
      ctx.beginPath();
      ctx.arc(0, 0, curR * 0.8, s.ang - ha * 0.35, s.ang + ha * 0.35);
      ctx.stroke();

      // 前端能量冲击（弧线末端亮点）
      if (progress < 0.9) {
        ctx.globalAlpha = a;
        ctx.fillStyle = '#fff';
        ctx.shadowColor = cGlow; ctx.shadowBlur = 20;
        const tipA1 = s.ang - ha, tipA2 = s.ang + ha;
        ctx.beginPath();
        ctx.arc(Math.cos(tipA1) * curR, Math.sin(tipA1) * curR, 3, 0, TAU);
        ctx.fill();
        ctx.beginPath();
        ctx.arc(Math.cos(tipA2) * curR, Math.sin(tipA2) * curR, 3, 0, TAU);
        ctx.fill();
      }

      // 🔥 火焰斩击：沿刀光跳动的焰苗（纯绘制，不产生新粒子）
      if (fire) {
        for (let i = 0; i < 9; i++) {
          const fa = s.ang - ha + (i + 0.5) / 9 * ha * 2;
          const flick = Math.sin(timeElapsed * 26 + i * 2.4) * 3;
          const fr = curR * (0.55 + 0.3 * (i % 3)) + flick;
          const fx2 = Math.cos(fa) * fr;
          const fy2 = Math.sin(fa) * fr - Math.abs(Math.sin(timeElapsed * 15 + i)) * 3;
          ctx.globalAlpha = a * (0.45 + 0.45 * Math.abs(Math.sin(timeElapsed * 20 + i * 1.3)));
          ctx.fillStyle = i % 3 === 1 ? '#ffeb3b' : (i % 3 === 2 ? '#ff7043' : '#ffb300');
          ctx.shadowColor = '#ff5722'; ctx.shadowBlur = 10;
          ctx.beginPath();
          ctx.arc(fx2, fy2, Math.max(1.4, 3.4 - (i % 3) * 0.8), 0, TAU);
          ctx.fill();
        }
      }
    }

    ctx.restore();
  }
  for (const n of novaFx) {
    const p = Math.min(1, n.t / 1.0);
    ctx.save();
    ctx.translate(n.x, n.y);
    // 前 30% 时间快速扩张，后 70% 稳定发光（持续伤害阶段）
    const expandP = Math.min(1, p / 0.3);
    const glowP = p < 0.3 ? 1 : Math.max(0.4, 1 - (p - 0.3) / 0.7 * 0.6);
    ctx.globalAlpha = glowP * 0.85;
    ctx.strokeStyle = '#ffe9a8';
    ctx.lineWidth = 5 - 2 * expandP;
    ctx.shadowColor = '#ffd166'; ctx.shadowBlur = 18;
    ctx.beginPath(); ctx.arc(0, 0, n.r * (0.5 + 0.5 * expandP), 0, TAU); ctx.stroke();
    // 内层柔光
    if (p > 0.3) {
      ctx.globalAlpha = glowP * 0.3;
      ctx.lineWidth = 2;
      ctx.beginPath(); ctx.arc(0, 0, n.r * 0.85, 0, TAU); ctx.stroke();
    }
    ctx.restore();
  }
  for (const ex of orbExplosionFx) {
    const p = Math.min(1, ex.t / 0.35);
    ctx.save();
    ctx.translate(ex.x, ex.y);
    ctx.globalAlpha = (1 - p) * 0.85;
    const grd = ctx.createRadialGradient(0, 0, 0, 0, 0, ex.r * (0.4 + 0.6 * p));
    grd.addColorStop(0, 'rgba(243,229,255,0.6)');
    grd.addColorStop(0.5, 'rgba(201,139,255,0.35)');
    grd.addColorStop(1, 'rgba(122,63,214,0)');
    ctx.fillStyle = grd;
    ctx.beginPath(); ctx.arc(0, 0, ex.r * (0.4 + 0.6 * p), 0, TAU); ctx.fill();
    ctx.strokeStyle = '#c98bff';
    ctx.lineWidth = 4 - 3 * p;
    ctx.shadowColor = '#b47aff'; ctx.shadowBlur = 18;
    ctx.beginPath(); ctx.arc(0, 0, ex.r * (0.3 + 0.7 * p), 0, TAU); ctx.stroke();
    ctx.restore();
  }
}


const hpBar = document.getElementById('hpBar');
const xpBar = document.getElementById('xpBar');
const hpText = document.getElementById('hpText');
const xpText = document.getElementById('xpText');
const lvlText = document.getElementById('lvlText');
const timerEl = document.getElementById('timer');
const killEl  = document.getElementById('killCount');
const bossTEl = document.getElementById('bossTimer');
const waveInfoEl = document.getElementById('waveInfo');
const coinHudEl = document.getElementById('coinHud');
// v3
const pauseOverlay = document.getElementById('pauseOverlay');
const btnPause = document.getElementById('btnPause');
const btnPauseResume = document.getElementById('btnPauseResume');
const btnPauseQuit = document.getElementById('btnPauseQuit');

function togglePause(on) {
  if (on === undefined) on = gameState !== 'paused';
  if (on) {
    if (gameState !== 'playing') return;
    gameState = 'paused';
    if (pauseOverlay) pauseOverlay.classList.add('show');
    populatePauseInfo();
  } else {
    if (gameState !== 'paused') return;
    gameState = 'playing';
    if (pauseOverlay) pauseOverlay.classList.remove('show');
    _lastTick = performance.now();
  }
}

function populatePauseInfo() {
  if (!player) return;
  const cls = getClass(player.classId);
  const portraitEl = document.getElementById('pausePortrait');
  const upgradesEl = document.getElementById('pauseUpgrades');
  // ⚔️ 副武器（主菜单装备的 holy_nova / holy_shield）及其专属强化数量
  const wpId = player.equippedWeapon;
  const wp = (wpId && wpId !== 'none') ? getWeapon(wpId) : null;
  const lv0 = player.upgradeLevels || {};
  let wpUpCount = 0;
  if (wp) {
    for (const u of UPGRADES) {
      const l = lv0[u.id] || 0;
      if (l > 0 && ((u.weaponOnly && u.weaponOnly.includes(wpId)) || (u.weaponMatch && u.weaponMatch.includes(wpId)))) wpUpCount++;
    }
    for (const a of AWAKEN_POOL) {
      const l = lv0[a.id] || 0;
      if (l > 0 && a.wakeFor === wpId) wpUpCount++;
    }
  }
  if (portraitEl) {
    const eq = player.equipment || {};
    const slotNames = { head: '头盔', chest: '胸甲', legs: '裤子' };
    const eqHtml = ['head','chest','legs'].map(s => {
      const item = eq[s];
      if (!item) return `<div style="color:#6a7a9a;font-size:11px;">${slotNames[s]}：—</div>`;
      const rc = item.rarity === '史诗' ? '#e1bee7' : item.rarity === '稀有' ? '#82e9ff' : '#a9b9db';
      return `<div style="font-size:11px;color:${rc};">${item.icon} ${slotNames[s]}：${item.name} <span style="color:#6a7a9a;">(${item.rarity})</span></div>`;
    }).join('');
    portraitEl.innerHTML = `
      <div class="pp-icon">${cls ? cls.icon : '🎮'}</div>
      <div class="pp-name">${cls ? cls.name : '金·白庚'}</div>
      <div class="pp-hp">❤️ ${Math.ceil(player.hp)}/${player.maxHp}</div>
      <div class="pp-stats">
        Lv.${player.level}<br>
        ⚔️ 伤害 x${player.damageMul.toFixed(2)}<br>
        🏹 攻速 x${player.fireRateMul.toFixed(2)}<br>
        👟 移速 x${player.speedMul.toFixed(2)}
      </div>
      <div style="margin-top:8px; padding-top:8px; border-top:1px solid rgba(255,255,255,0.1); width:100%;">
        <div style="font-size:12px; color:#ffe082; margin-bottom:4px; text-align:center;">🛡️ 装备</div>
        ${eqHtml}
      </div>
      <div style="margin-top:8px; padding-top:8px; border-top:1px solid rgba(255,255,255,0.1); width:100%;">
        <div style="font-size:12px; color:#ffe082; margin-bottom:4px; text-align:center;">⚔️ 副武器</div>
        ${wp
          ? `<div style="font-size:11.5px;color:#ffe9a8;text-align:center;">${wp.icon} ${wp.name}</div>
             <div style="font-size:10px;color:#82e9ff;text-align:center;margin-top:2px;">${wpUpCount > 0 ? '专属强化 ' + wpUpCount + ' 项' : '暂无专属强化'}</div>`
          : `<div style="color:#6a7a9a;font-size:11px;text-align:center;">未装备副武器</div>`}
      </div>
    `;
  }
  if (upgradesEl) {
    const lv = player.upgradeLevels || {};
    // ⚔️ 副武器专属强化（weaponOnly / weaponMatch / 武器觉醒 wakeFor）单独分组
    const weaponIds = new Set();
    const wpItems = [];
    if (wp) {
      for (const u of UPGRADES) {
        const level = lv[u.id] || 0;
        if (level <= 0) continue;
        const match = (u.weaponOnly && u.weaponOnly.includes(wpId)) || (u.weaponMatch && u.weaponMatch.includes(wpId));
        if (match) {
          weaponIds.add(u.id);
          wpItems.push({ icon: u.icon, name: u.name, lv: level, max: u.max, desc: u.desc, descLv: u.descLv ? u.descLv(level - 1) : '', cat: 'weapon' });
        }
      }
      for (const a of AWAKEN_POOL) {
        const level = lv[a.id] || 0;
        if (level > 0 && a.wakeFor === wpId) {
          weaponIds.add(a.id);
          wpItems.push({ icon: a.icon, name: a.name, lv: '✨', max: 1, desc: a.desc, descLv: '副武器觉醒', cat: 'weapon' });
        }
      }
    }
    const items = [];
    for (const u of UPGRADES) {
      const level = lv[u.id] || 0;
      if (level > 0 && !weaponIds.has(u.id)) items.push({ icon: u.icon, name: u.name, lv: level, max: u.max, desc: u.desc, descLv: u.descLv ? u.descLv(level - 1) : '', cat: u.cat || '' });
    }
    // 职业觉醒（武器觉醒已归入副武器组）
    for (const a of AWAKEN_POOL) {
      const level = lv[a.id] || 0;
      if (level > 0 && !weaponIds.has(a.id)) items.push({ icon: a.icon, name: a.name, lv: '✨', max: 1, desc: a.desc, descLv: '觉醒 · 全局永久', cat: 'awake' });
    }
    // 宝箱稀有强化
    const chestIds = Object.keys(lv).filter(k => k.startsWith('chest_'));
    for (const cid of chestIds) {
      const clv = lv[cid];
      if (!clv) continue;
      const realId = cid.replace('chest_', '');
      const info = player && player.chestInfo && player.chestInfo[realId];
      if (info) {
        const dlv = typeof info.descLv === 'function' ? info.descLv(clv) : `已取 ${clv} 次`;
        items.push({ icon: info.icon || '🎁', name: info.name, lv: clv, max: info.max || 5, desc: info.desc, descLv: dlv, cat: 'chest' });
      } else {
        items.push({ icon: '🎁', name: realId, lv: clv, max: 5, desc: 'BOSS 宝箱稀有强化', descLv: `已取 ${clv} 次`, cat: 'chest' });
      }
    }
    const itemHtml = (it) => {
      const catLabel = it.cat === 'awake' ? '✨ 职业觉醒' : it.cat === 'chest' ? '🎁 稀有' : it.cat === 'weapon' ? '⚔️ 副武器强化' : '';
      const bg = it.cat === 'weapon' ? 'rgba(255,224,130,0.08)' : 'rgba(255,255,255,0.03)';
      return `<div class="pu-item" data-bg="${bg}" style="cursor:pointer;transition:background 0.15s;background:${bg};">
        <span class="pu-icon">${it.icon}</span>
        <span class="pu-name">${it.name}</span>
        <span class="pu-lv">Lv.${it.lv}${it.max && it.max <= 50 ? '/' + it.max : ''}</span>
        <div class="pu-detail" style="display:none; width:100%; margin-top:6px; padding:6px 8px; background:rgba(0,0,0,0.2); border-radius:6px; font-size:11px; color:#a9b9db; line-height:1.5;">
          ${it.desc}<br><span style="color:#ffe082;">${it.descLv}</span>${catLabel ? '<br><span style="color:#82e9ff;">' + catLabel + '</span>' : ''}
        </div>
      </div>`;
    };
    // 副武器区块（装备了副武器时显示）
    const wpBlock = wp ? `
      <div class="pu-title" style="color:#ffe9a8;">⚔️ 副武器 · ${wp.icon} ${wp.name}${wpItems.length ? ` · 强化 ${wpItems.length}` : ''}</div>
      ${wpItems.length ? wpItems.map(itemHtml).join('') : '<div class="pu-empty" style="padding:10px;">暂未获得专属强化（升级时可抽到）</div>'}
    ` : '';
    // 通用强化区块
    const genBlock = items.length
      ? `<div class="pu-title" style="margin-top:${wp ? '12px' : '0'};">已选强化 (${items.length}) — 点击展开详情</div>` + items.map(itemHtml).join('')
      : (wp ? '<div class="pu-title" style="margin-top:12px;">已选强化</div><div class="pu-empty">暂无其他强化</div>' : '<div class="pu-title">已选强化</div><div class="pu-empty">暂无强化</div>');
    upgradesEl.innerHTML = wpBlock + genBlock;
    upgradesEl.querySelectorAll('.pu-item').forEach(el => {
      el.onclick = () => {
        const detail = el.querySelector('.pu-detail');
        if (detail) {
          const isOpen = detail.style.display !== 'none';
          detail.style.display = isOpen ? 'none' : 'block';
          el.style.background = isOpen ? (el.dataset.bg || 'rgba(255,255,255,0.03)') : 'rgba(130,233,255,0.08)';
        }
      };
    });
  }
}
if (btnPause)       btnPause.onclick       = () => togglePause();
if (btnPauseResume) btnPauseResume.onclick = () => togglePause(false);
