const menuPortraitAttrs = document.getElementById('menuPortraitAttrs');
const menuPortraitDesc  = document.getElementById('menuPortraitDesc');
const menuSwapBtn       = document.getElementById('menuSwapBtn');
function renderMenuPortrait() {
  if (!menuPortraitImg) return;
  const cls = getClass(selectedClassId) || getClass('metal_sword');
  // 立绘 canvas → img（用 toDataURL，避免跨域污染，纯本地 canvas 没问题）
  const pc = getPlayerPortrait(cls.id);
  menuPortraitImg.src = pc.toDataURL('image/png');
  // 五行职业覆盖为内嵌半身立绘（必须在默认 src 赋值之后）
  if (typeof _setClassPortraitFrame === 'function') _setClassPortraitFrame(cls.id);
  menuPortraitName.textContent = cls.name;
  const subMap = {
    metal_sword: 'METAL BLADE',
    wood_qingluo: 'WOOD VINE',
    water_canglan: 'WATER TIDE',
    fire_chiyan: 'FIRE FLAME',
    earth_panshi: 'EARTH STONE',
  };
  menuPortraitSub.textContent = subMap[cls.id] || 'CLASS';
  // 灞炴€э細jieshao 闈㈡澘涓?4 涓湪妗嗭紝鍙～绾枃瀛楋紙鍙栧墠 4 鏉?tags锛屽幓闄?emoji/鍥炬爣锛屼笉瓒冲垯鐣欑┖锛塦r
  const stripEmoji = (s) => String(s || '')
    .replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{2B00}-\u{2BFF}\u{FE0F}\u{2190}-\u{21FF}\u{2300}-\u{23FF}]/gu, '')
    .replace(/\s{2,}/g, ' ').trim();
  const attrs = (cls.tags || []).slice(0, 4).map(stripEmoji).filter(a => a);
  menuPortraitAttrs.innerHTML = '';
  for (let i = 0; i < attrs.length; i++) {
    const row = document.createElement('div');
    row.className = 'js-attr-row';
    row.textContent = attrs[i];
    menuPortraitAttrs.appendChild(row);
  }
  // 描述（含进化名）
  const evo = cls.evo ? `　进化：「${cls.evo.name}」— ${cls.evo.desc}` : '';
  menuPortraitDesc.textContent = cls.desc + (evo ? '\n' + evo : '');
  menuPortraitDesc.style.whiteSpace = 'pre-line';
}


