/* ========== 🌿 五行修炼渲染（命石祭坛·极简版） ========== */
function renderAltarView() {
  const m = getMeta();
  const spirit = m.spirit || 0;
  const frags = m.fragments || {};
  const origin = m.origin || 0;
  const luckLv = m.luck || 0;
  altarCoins.innerHTML = `灵石：<b>${spirit}</b>　|　碎片：金<b>${frags.metal||0}</b>/木<b>${frags.wood||0}</b>/水<b>${frags.water||0}</b>/火<b>${frags.fire||0}</b>/土<b>${frags.earth||0}</b>　|　五行之源：<b>${origin}</b>　|　幸运 Lv.<b>${luckLv}</b>`;
  altarGrid.innerHTML = '';
  // 五系祭坛卡片
  for (const el of ['metal', 'wood', 'water', 'fire', 'earth']) {
    const cfg = GAME_CONFIG.altar[el];
    const lv = (m.altar && m.altar[el]) || 0;
    const isOpen = GAME_CONFIG.altar.unlocked.includes(el);
    const card = document.createElement('div');
    card.className = 'altar-card';
    card.dataset.el = el;
    const icon = WUXING_ICON[el];
    const name = WUXING_NAME[el];
    let body = '';
    if (isOpen && cfg) {
      const eff = altarEffect(el, lv);
      const target = lv + 1;
      const cost = target <= GAME_CONFIG.altar.maxLevel ? altarCost(el, target) : null;
      const isMax = lv >= GAME_CONFIG.altar.maxLevel;
      const hasGate11 = target === 11 && cfg.gate11;
      const hasGate21 = target === 21 && cfg.gate21;
      const canAfford = cost && (cost.spirit <= spirit)
        && (!cost.fragment || (frags[cost.fragment.el] || 0) >= cost.fragment.n)
        && (!cost.origin || origin >= cost.origin);
      // 构建属性摘要（按元素主属性/被动/光环显示）
      const statLabel = {
        armor: '护甲', regen: '再生', fireRateMul: '攻速', damageMul: '攻击力',
        dmgReduction: '减伤', shelter: '森之庇护', shieldChance: '水盾', igniteChance: '点燃',
        regenMul: '再生', cdr: '冷却缩减', critChance: '暴击率', critDmg: '暴击伤害'
      };
      const auraName = { metal: '万剑归宗', wood: '荆棘光环', water: '冰封领域', fire: '业火', earth: '大地震击' };
      let statParts = [`最大生命 +${eff.hp}`];
      if (eff.primaryType && eff.primary > 0) {
        const pctStats = ['fireRateMul', 'damageMul', 'critChance', 'critDmg', 'cdr'];
        const pct = pctStats.includes(eff.primaryType) ? '%' : '';
        statParts.push(`${statLabel[eff.primaryType] || eff.primaryType} +${(eff.primary * (pct ? 100 : 1)).toFixed(pct ? 0 : 1)}${pct}`);
      }
      if (eff.passive11) {
        const pt = eff.passive11.type;
        if (pt === 'shelter') statParts.push('🌿 森之庇护');
        else statParts.push(`${statLabel[pt] || pt} +${(eff.passive11.value * 100).toFixed(0)}%`);
      }
      if (eff.per12_20Type && eff.per12_20 > 0) {
        const flatStats = ['armor', 'regen'];
        const isPct = !flatStats.includes(eff.per12_20Type);
        const val = isPct ? (eff.per12_20 * 100).toFixed(0) + '%' : eff.per12_20.toFixed(1);
        statParts.push(`${statLabel[eff.per12_20Type] || eff.per12_20Type} +${val}`);
      }
      if (eff.aura21) statParts.push(`✨ ${auraName[el] || '光环'}`);
      body = `
        <div class="altar-title"><span class="altar-name">${icon} ${name}命石</span><span class="altar-lv">Lv.${lv}<small> / ${GAME_CONFIG.altar.maxLevel}</small></span></div>
        <div class="altar-stats">${statParts.join(' · ')}</div>`;
      if (isMax) {
        body += `<div class="altar-max">★ 已达最高等级</div>`;
      } else {
        const costTxt = [`灵石 ${cost.spirit}`];
        if (hasGate11) costTxt.push(`${WUXING_NAME[cost.fragment.el]}碎片×${cost.fragment.n}`);
        if (hasGate21) costTxt.push(`五行之源×${cost.origin}`);
        body += `
          <div class="altar-cost">升到 Lv.${target}：${costTxt.join('　')}</div>
          <button class="btn ${canAfford ? 'success' : 'ghost'}" data-el="${el}" ${canAfford ? '' : 'disabled'}>${canAfford ? '升级' : '资源不足'}</button>`;
      }
    } else {
      body = `<div class="altar-title"><span class="altar-name">${icon} ${name}命石</span><span class="altar-lv zero">Lv.0</span></div>
        <div class="altar-locked">未开放·模板预留</div>`;
    }
    card.innerHTML = body;
    altarGrid.appendChild(card);
  }
  // 幸运卡片
  const lk = GAME_CONFIG.luck;
  const lkMax = luckLv >= lk.maxLevel;
  const lkCost = lk.costBase + luckLv * lk.costStep;
  const lkCan = !lkMax && spirit >= lkCost;
  const lkCard = document.createElement('div');
  lkCard.className = 'altar-card altar-luck';
  lkCard.innerHTML = `
    <div class="altar-title"><span class="altar-name">🍀 幸运</span><span class="altar-lv">Lv.${luckLv}<small> / ${lk.maxLevel}</small></span></div>
    <div class="altar-stats">命石卡位率 +${((lk.stoneSlotPerLevel * luckLv) * 100).toFixed(1)}%</div>
    ${lkMax
      ? `<div class="altar-max">★ 已满级</div>`
      : `<div class="altar-cost">升到 Lv.${luckLv + 1}：灵石 ${lkCost}</div>
         <button class="btn ${lkCan ? 'success' : 'ghost'}" id="buyLuckBtn" ${lkCan ? '' : 'disabled'}>${lkCan ? '提升幸运' : '灵石不足'}</button>`}`;

  altarGrid.appendChild(lkCard);
  // 绑定升级按钮
  altarGrid.querySelectorAll('button[data-el]').forEach(btn => {
    btn.onclick = () => {
      const el = btn.dataset.el;
      const r = SpiritStoneUpgrade(el);
      if (r.ok) spawnFloat && console.log('[祭坛]', el, '升级到 Lv.' + r.lv);
      renderAltarView();
    };
  });
  const lb = document.getElementById('buyLuckBtn');
  if (lb) lb.onclick = () => { buyLuck(); renderAltarView(); };
}
window.renderAltarView = renderAltarView;

