/* -------- 结算画面 -------- */
function triggerGameOver(win) {
  if (gameState === 'victory' || gameState === 'gameover') return;
  gameState = win ? 'victory' : 'gameover';
  levelOverlay.classList.remove('show');

  // 💰 金币入账（胜利额外 +300）
  const coins = Math.floor(runCoins) + (win ? 300 : 0);
  const meta = getMeta();
  meta.coins += coins;
  if (win) meta.wins = (meta.wins || 0) + 1;

  // Phase-1 zone unlock progression: winning full run unlocks next zone, marks current as cleared
  if (win) {
    try {
      const _curIdx = _pendingStartZone || 1;
      const _curL = MAP_LAYERS[_curIdx - 1];
      if (_curL) {
        // mark zone as cleared
        const _cs = meta.flags.zonesCleared || [];
        if (_cs.indexOf(_curL.id) < 0) _cs.push(_curL.id);
        meta.flags.zonesCleared = _cs;
        // unlock up to 5th zone (max)
        meta.flags.zoneUnlocked = Math.max(
          meta.flags.zoneUnlocked || 1,
          Math.min(5, _curIdx + 1)
        );
      }
    } catch(_) {}
  }

  // ☯ 灵石结算：命石等级折算 + 局内溢出累计 + 通关五行之源 + 隐藏成就判定
  const _Ec = GAME_CONFIG.economy;
  let spiritGain = 0;
  const spiritBreakdown = [];
  for (const el of WUXING_ELEMENTS) {
    const lv = stoneLevel(player, el);
    if (lv > 0) {
      const inc = _Ec.payoutByStoneLevel[lv] || 0;
      spiritGain += inc;
      spiritBreakdown.push({ el, lv, inc });
    }
  }
  const overflow = player._spiritOverflow || 0;
  spiritGain += overflow;
  if (spiritGain > 0) meta.spirit = (meta.spirit || 0) + spiritGain;
  if (win && _Ec.originPerVictory > 0) meta.origin = (meta.origin || 0) + _Ec.originPerVictory;
  // 隐藏成就判定（awardUnlock 内部会 saveMeta，之后重新读 meta 合并）
  const freshSecrets = evaluateRunSecrets(player, win);
  const meta2 = getMeta(); // 拿 awardUnlock 写入后的最新状态
  meta2.coins = meta.coins; meta2.spirit = (meta2.spirit || 0) + (spiritGain > 0 ? 0 : 0); // spirit 已在 meta 上
  // 把本函数局部 meta 的改动合并到 meta2
  meta2.spirit = meta.spirit; meta2.origin = meta.origin; meta2.coins = meta.coins; meta2.wins = meta.wins;
  if (spiritGain > 0 && meta2.spirit > 0 && !meta2.flags.spiritGuide) {
    meta2.flags.spiritGuide = true;
    setTimeout(() => { try { toast('恭喜获得灵石！快去【⛩ 五行修炼】中提升命石等级，解锁强力流派吧！', 'ok'); } catch (_) {} }, 600);
  }
  // 发放隐藏成就奖励（在同一对象上操作）
  for (const id of freshSecrets) {
    const entry = COLLECTION_MAP[id];
    if (entry && entry.reward) {
      if (entry.reward.type === 'fragment') meta2.fragments[entry.reward.el] = (meta2.fragments[entry.reward.el] || 0) + entry.reward.n;
      else if (entry.reward.type === 'spirit') meta2.spirit = (meta2.spirit || 0) + entry.reward.n;
    }
  }
  saveMeta(meta2);

  // 🏆 最佳战绩 + 自动存档
  const record = updateBestScore(win);
  SaveIO.saveToLocal(true);

  // 填充结算
  settleTitle.textContent = win ? '🏆 胜 利 生 还' : '💀 阵 亡';
  settleTitle.className = win ? 'win' : 'lose';
  newRecordEl.textContent = record.any ? '🎖️ 刷新最佳纪录！' : '';
  const cls = getClass(player.classId);
  const upCount = Object.values(player.upgradeLevels).reduce((a, b) => a + b, 0);
  settleGrid.innerHTML = `
    <div class="row"><span>出战职业</span><b>${cls ? cls.icon + ' ' + cls.name : '⚔️ 金·白庚'}${player.evolved ? ' ⚡' : ''}</b></div>
    <div class="row"><span>挑战难度</span><b>${curDiff.icon} ${curDiff.name}</b></div>
    <div class="row"><span>存活时间</span><b>${fmtTime(timeElapsed)}</b></div>
    <div class="row"><span>最终等级</span><b>Lv.${player.level}</b></div>
    <div class="row"><span>累计击杀</span><b>${killCount}</b></div>
    <div class="row"><span>选择强化</span><b>${upCount} 次</b></div>
    <div class="row"><span>☯ 灵石获得</span><b style="color:#a5d6a7;">+${spiritGain}</b></div>
    ${win ? `<div class="row"><span>五行之源</span><b style="color:#ffd166;">+${_Ec.originPerVictory}</b></div>` : ''}
    ${freshSecrets.length ? `<div class="row"><span>🏆 新解锁</span><b style="color:#ffd166;">${freshSecrets.map(id => (COLLECTION_MAP[id]||{}).name || id).join(' · ')}</b></div>` : ''}
  `;
  settleCoinsEl.innerHTML = `💰 本局获得 <b>+${coins}</b> 金币　（总资产 ${meta.coins}）　☯ 灵石 <b style="color:#a5d6a7;">+${spiritGain}</b>（总灵石 ${getMeta().spirit}）`;
  const ups = Object.entries(player.upgradeLevels)
    .map(([id, lv]) => {
      const u = UPGRADES.find(x => x.id === id);
      return u ? `<span>${u.icon} ${u.name} Lv.${lv}</span>` : '';
    })
    .join('');
  const evoTag = player.evolved && cls && cls.evo ? `<span style="border-color:#ffd166;color:#ffd166;">⚡ ${cls.evo.name}</span>` : '';
  settleUpgradesEl.innerHTML = (ups || '<span>无强化</span>') + evoTag;
  settleOverlay.classList.add('show');
  updateMenuCoins();
}

